export const sources = {
 "src/components/CommunityPackChecker/CommunityPackChecker.jsx": "import { measuredIssueSummary, silenceSummaryParts } from './packCheckerIssueClassification.js';\nimport { useEffect, useMemo, useRef, useState } from 'react';\nimport { Button } from '../common/Button';\nimport { CommunityPackMetadataModal } from './CommunityPackMetadataModal';\nimport {\n  Check,\n  ChevronDown,\n  CircleCheck,\n  Download,\n  FilePen,\n  Image,\n  Info,\n  Loader2,\n  Moon,\n  Music,\n  Network,\n  Scissors,\n  TriangleAlert,\n  Wrench,\n} from '../icons/LucideLocal';\nimport {\n  Measure,\n  audioMeasureRows,\n  cleanLabel,\n  expectedImageOk,\n  formatLufs,\n  formatPeak,\n  imageMeasureRows,\n} from './packCheckerMeasures';\nimport { ConformingSection } from './CommunityPackConforming';\nimport { formatPackAudioEdgeSilence } from '../../config/audioProcessing';\nimport {\n  issueHasMeasure,\n  isAudioFormatIssue,\n  isSaturatedIssue,\n  hasMeasureIssue as hasMeasureIssues,\n  automaticCorrectionCount,\n  categoryConformanceStats,\n  isAutomaticSilenceIssue,\n  isAutomaticVolumeIssue,\n  isOptionalSilenceIssue,\n  optionalSilenceSelectionKey,\n} from './packCheckerIssueClassification';\nimport './CommunityPackChecker.css';\n\nconst EDGE_SILENCE_LABEL = formatPackAudioEdgeSilence();\n\nconst PROBLEM_SECTIONS = [\n  {\n    id: 'quality',\n    title: 'Audio de mauvaise qualité (source saturée)',\n    badge: 'Source',\n    bucket: 'listen',\n    Icon: TriangleAlert,\n    explanation: \"La saturation est présente dans le fichier d'origine : aucune correction ne la rattrape. Reprends le pack depuis une meilleure source.\",\n    action: 'Reprends le pack depuis une meilleure source.',\n    match: (issue) => (\n      issue.category === 'audio'\n      && !issue.autoFixAvailable\n      && isSaturatedIssue(issue)\n    ),\n  },\n  {\n    id: 'listen',\n    title: 'À écouter',\n    badge: 'Manuel',\n    bucket: 'listen',\n    Icon: Info,\n    explanation: \"L'outil ne sait pas corriger ce point tout seul.\",\n    action: \"Écoute ou vérifie ces fichiers avant de valider le pack.\",\n    match: (issue) => !isOptionalSilenceIssue(issue) && !issue.autoFixAvailable && issue.category !== 'structure' && issue.category !== 'title',\n  },\n  {\n    id: 'silence',\n    title: 'Silence début / fin incorrect',\n    badge: 'Auto',\n    bucket: 'fix',\n    Icon: Scissors,\n    explanation: 'Le blanc avant ou après la voix sort de la fenêtre attendue.',\n    action: `On ajuste le silence vers ${EDGE_SILENCE_LABEL}.`,\n    match: isAutomaticSilenceIssue,\n  },\n  {\n    id: 'optionalSilence',\n    title: 'Suggestions facultatives',\n    badge: 'Facultatif',\n    bucket: 'optional',\n    Icon: Scissors,\n    explanation: 'Ces silences longs peuvent être volontaires. Le pack reste conforme.',\n    action: `Chaque bord peut être ramené à ${EDGE_SILENCE_LABEL} si tu le souhaites.`,\n    match: isOptionalSilenceIssue,\n  },\n  {\n    id: 'volume',\n    title: 'Niveau sonore incorrect',\n    badge: 'Auto',\n    bucket: 'fix',\n    Icon: Music,\n    explanation: 'Le niveau moyen est trop faible ou trop fort par rapport au reste.',\n    action: 'On normalise le volume au bon niveau.',\n    match: isAutomaticVolumeIssue,\n  },\n  {\n    id: 'audioFormat',\n    title: 'Format audio à convertir',\n    badge: 'Auto',\n    bucket: 'fix',\n    Icon: Wrench,\n    explanation: \"L'audio n'est pas dans le format attendu.\",\n    action: 'On reconvertit en MP3 mono 44,1 kHz.',\n    match: isAudioFormatIssue,\n  },\n  {\n    id: 'image',\n    title: 'Image à corriger',\n    badge: 'Auto',\n    bucket: 'fix',\n    Icon: Image,\n    explanation: \"L'image n'a pas le format ou la taille attendue.\",\n    action: 'On convertit ou redimensionne en 320×240.',\n    match: (issue) => issue.autoFixAvailable && issue.category === 'image',\n  },\n  {\n    id: 'title',\n    title: 'Nom du pack à corriger',\n    badge: 'Assisté',\n    bucket: 'fix',\n    Icon: FilePen,\n    explanation: 'Le nom ou la convention du pack demande une correction.',\n    action: 'On ouvre les métadonnées avant de créer le ZIP corrigé.',\n    match: (issue) => issue.category === 'title',\n  },\n  {\n    id: 'structure',\n    title: 'Structure à vérifier',\n    badge: 'Manuel',\n    bucket: 'listen',\n    Icon: Network,\n    explanation: 'Un lien, une référence ou un champ du pack demande une vérification.',\n    action: 'Vérifie la navigation ou les fichiers référencés.',\n    match: (issue) => issue.category === 'structure',\n  },\n];\n\nfunction IconFrame({ Icon }) {\n  return <Icon className=\"checker-icon\" aria-hidden=\"true\" strokeWidth={2} absoluteStrokeWidth />;\n}\n\nfunction severityLabel(severity) {\n  switch (severity) {\n    case 'error':\n      return 'Erreur';\n    case 'warning':\n      return 'Avertissement';\n    case 'info':\n      return 'Info';\n    case 'ok':\n      return 'OK';\n    default:\n      return severity || 'Info';\n  }\n}\n\nfunction recordProblemSummary(record) {\n  const scopedIssues = record.sectionIssues?.length ? record.sectionIssues : [record.issue];\n  if (record.kind === 'audio') {\n    if (scopedIssues.some((issue) => isSaturatedIssue(issue))) {\n      const peak = record.item?.truePeakDb;\n      return typeof peak === 'number' ? `Saturé · crête ${formatPeak(peak)}` : 'Saturé (source)';\n    }\n    const silenceIssues = scopedIssues.filter((issue) => (issueHasMeasure(issue, 'silenceStart') || issueHasMeasure(issue, 'silenceEnd')));\n    if (silenceIssues.length > 0) {\n      const parts = silenceSummaryParts(silenceIssues, record.item);\n      if (parts.length > 0) return parts.join(' | ');\n    }\n\n    if (scopedIssues.some((issue) => (issueHasMeasure(issue, 'volume') && issue.code !== 'CHECKER_AUDIO_NEAR_MUTE'))) {\n      const lufs = record.item?.integratedLufs;\n      const direction = typeof lufs === 'number' && lufs > -10 ? 'trop haut' : 'trop bas';\n      return `Niveau sonore ${direction} (${formatLufs(lufs)})`;\n    }\n  }\n\n  if (record.kind === 'image') {\n    return scopedIssues\n      .map((issue) => measuredIssueSummary(issue, record.item, record.kind))\n      .filter(Boolean)\n      .join(' · ');\n  }\n\n  return scopedIssues\n    .map((issue) => measuredIssueSummary(issue, record.item, record.kind))\n    .filter(Boolean)\n    .join(' · ');\n}\n\nfunction hasMeasureIssue(record, key) {\n  const issues = record.sectionIssues?.length ? record.sectionIssues : record.issues;\n  return hasMeasureIssues(issues, key);\n}\n\nfunction roleLabel(record) {\n  const raw = record.item?.itemType || record.issue?.itemType || record.issue?.category || 'Fichier';\n  if (raw === 'image') return 'Image';\n  if (raw === 'audio') return 'Audio';\n  return raw;\n}\n\nfunction issuesByFilePath(report) {\n  const map = new Map();\n  for (const issue of report?.issues || []) {\n    if (!issue.filePath) continue;\n    if (!map.has(issue.filePath)) map.set(issue.filePath, []);\n    map.get(issue.filePath).push(issue);\n  }\n  return map;\n}\n\nfunction buildItemMap(report) {\n  const map = new Map();\n  for (const item of report?.audioItems || []) {\n    map.set(item.filePath, { kind: 'audio', item });\n  }\n  for (const item of report?.imageItems || []) {\n    map.set(item.filePath, { kind: 'image', item });\n  }\n  return map;\n}\n\nfunction uniqueIssueKey(issue) {\n  return issue.filePath || `${issue.category}:${issue.code ?? issue.label}`;\n}\n\nfunction buildProblemGroups(report) {\n  if (!report) return [];\n  const itemMap = buildItemMap(report);\n  const used = new Set();\n  const relevantIssues = (report.issues || []).filter((issue) => (\n    issue.severity === 'error' || issue.severity === 'warning' || isOptionalSilenceIssue(issue)\n  ));\n\n  return PROBLEM_SECTIONS.map((section) => {\n    const records = [];\n    const seen = new Set();\n    for (const issue of relevantIssues) {\n      if (used.has(issue) || !section.match(issue)) continue;\n      used.add(issue);\n      const key = section.id === 'optionalSilence'\n        ? `${uniqueIssueKey(issue)}:${issue.code}`\n        : uniqueIssueKey(issue);\n      if (seen.has(key)) continue;\n      seen.add(key);\n      const itemEntry = issue.filePath ? itemMap.get(issue.filePath) : null;\n      const allFileIssues = issue.filePath ? (issuesByFilePath(report).get(issue.filePath) || [issue]) : [issue];\n      records.push({\n        id: `${section.id}:${key}`,\n        issue,\n        issues: allFileIssues,\n        sectionIssues: allFileIssues.filter((candidate) => section.match(candidate)),\n        item: itemEntry?.item || null,\n        kind: itemEntry?.kind || issue.category,\n      });\n    }\n    return {\n      ...section,\n      records,\n      count: records.length,\n      fixCount: section.id === 'title'\n        ? records.length\n        : records.reduce((sum, record) => sum + automaticCorrectionCount(record), 0),\n      optionalCount: section.id === 'optionalSilence' ? records.length : 0,\n    };\n  }).filter((group) => group.count > 0);\n}\n\nfunction saturatedFileCount(groups) {\n  return groups\n    .filter((group) => group.id === 'quality')\n    .reduce((sum, group) => sum + group.count, 0);\n}\n\nfunction summarizeGroups(groups, report) {\n  const listenCount = groups\n    .filter((group) => group.bucket === 'listen')\n    .reduce((sum, group) => sum + group.count, 0);\n  const fixCount = groups\n    .filter((group) => group.bucket === 'fix')\n    .reduce((sum, group) => sum + group.fixCount, 0);\n  const optionalCount = groups\n    .filter((group) => group.bucket === 'optional')\n    .reduce((sum, group) => sum + group.optionalCount, 0);\n  const saturatedCount = saturatedFileCount(groups);\n  const hasBlocking = report?.verdict === 'invalid' || groups.some((group) => (\n    group.bucket === 'listen' && group.records.some((record) => record.issue.severity === 'error')\n  ));\n\n  if (!groups.length) {\n    return {\n      tone: 'ok',\n      Icon: CircleCheck,\n      title: 'Pack conforme',\n      subtitle: 'Aucun problème automatique ou manuel détecté.',\n      listenCount,\n      fixCount,\n      optionalCount,\n    };\n  }\n  if (hasBlocking) {\n    return {\n      tone: 'listen',\n      Icon: TriangleAlert,\n      title: 'Pack à vérifier avant export',\n      subtitle: 'Certains points demandent une vérification manuelle.',\n      listenCount,\n      fixCount,\n      optionalCount,\n    };\n  }\n  // Audio saturé : défaut de qualité que la correction ne résout pas → on ne\n  // promet jamais « corrigeable en un clic », on conseille de repartir d'une\n  // source propre.\n  if (saturatedCount > 0) {\n    return {\n      tone: 'quality',\n      Icon: TriangleAlert,\n      title: fixCount > 0 ? 'Pack corrigeable, mais audio déjà saturé' : 'Audio déjà saturé',\n      subtitle: fixCount > 0\n        ? \"Le reste sera corrigé ; l'audio saturé doit être repris depuis une source propre.\"\n        : 'Nous conseillons de refaire le pack depuis une source audio propre.',\n      listenCount,\n      fixCount,\n      optionalCount,\n    };\n  }\n  if (listenCount > 0) {\n    return {\n      tone: 'listen',\n      Icon: Info,\n      title: listenCount === 1\n        ? 'Pack corrigeable, avec un fichier à écouter'\n        : `Pack corrigeable, avec ${listenCount} fichiers à écouter`,\n      subtitle: 'Le reste peut être corrigé automatiquement.',\n      listenCount,\n      fixCount,\n      optionalCount,\n    };\n  }\n  if (fixCount === 0 && listenCount === 0 && optionalCount > 0) {\n    return {\n      tone: 'ok',\n      Icon: CircleCheck,\n      title: `Pack conforme, avec ${optionalCount} ajustement${optionalCount > 1 ? 's' : ''} facultatif${optionalCount > 1 ? 's' : ''}`,\n      subtitle: 'Les pauses longues peuvent être conservées telles quelles.',\n      listenCount,\n      fixCount,\n      optionalCount,\n    };\n  }\n  return {\n    tone: 'fix',\n    Icon: Wrench,\n    title: 'Pack corrigeable en un clic',\n    subtitle: 'Aucun point manuel détecté.',\n    listenCount,\n    fixCount,\n    optionalCount,\n  };\n}\n\nexport function titleNeedsCorrection(report) {\n  return (report?.titleSummary?.warnings || 0) > 0 || (report?.titleSummary?.errors || 0) > 0;\n}\n\nfunction SummaryTile({ title, Icon, tone = 'neutral', children }) {\n  return (\n    <div className={`checker-summary-tile checker-summary-tile--${tone}`}>\n      <div className=\"checker-summary-tile-head\">\n        <IconFrame Icon={Icon} />\n        <span>{title}</span>\n      </div>\n      {children}\n    </div>\n  );\n}\n\nfunction SplitStat({ ok, needsFix }) {\n  return (\n    <div className=\"checker-split-stat\">\n      <span className=\"checker-split-stat-ok\"><strong>{ok}</strong> OK</span>\n      <span className={`checker-split-stat-fix ${needsFix === 0 ? 'is-clean' : ''}`}>\n        <strong>{needsFix}</strong> à corriger\n      </span>\n    </div>\n  );\n}\n\nfunction SummaryTiles({ report, saturatedCount = 0 }) {\n  const audio = categoryConformanceStats(report.audioSummary);\n  const images = categoryConformanceStats(report.imageSummary);\n  const title = categoryConformanceStats(report.titleSummary);\n  const titleOk = title.total > 0 && title.needsFix === 0;\n  const structureOk = report.structureSummary?.luniiCompatible && report.structureSummary?.storyStudioEditable;\n  const nightMode = Boolean(report.nightMode?.detected);\n  return (\n    <div className=\"checker-summary-tiles\" aria-label=\"Résumé du pack\">\n      <SummaryTile title=\"Audio\" Icon={Music} tone={saturatedCount > 0 ? 'danger' : (audio.needsFix > 0 ? 'fix' : 'ok')}>\n        <SplitStat ok={audio.ok} needsFix={audio.needsFix} />\n      </SummaryTile>\n      <SummaryTile title=\"Images\" Icon={Image} tone={images.needsFix ? 'fix' : 'ok'}>\n        <SplitStat ok={images.ok} needsFix={images.needsFix} />\n      </SummaryTile>\n      <SummaryTile title=\"Nom du pack\" Icon={FilePen} tone={titleOk ? 'ok' : 'fix'}>\n        <div className=\"checker-single-stat\">\n          <strong>{titleOk ? 'Valide' : 'À corriger'}</strong>\n          <span>{titleOk ? 'Convention OK' : 'Métadonnées'}</span>\n        </div>\n      </SummaryTile>\n      <SummaryTile title=\"Structure\" Icon={Network} tone={structureOk ? 'ok' : 'listen'}>\n        <div className=\"checker-single-stat\">\n          <strong>{structureOk ? 'Correcte' : 'Vérification manuelle'}</strong>\n          <span>{report.structureSummary?.stageCount ?? 0} étapes</span>\n        </div>\n      </SummaryTile>\n      <SummaryTile title=\"Mode nuit\" Icon={Moon} tone={nightMode ? 'ok' : 'neutral'}>\n        <div className=\"checker-single-stat\">\n          <strong>{nightMode ? 'Disponible' : 'Absent'}</strong>\n          <span>{nightMode ? 'Détecté dans le pack' : 'Non bloquant'}</span>\n        </div>\n      </SummaryTile>\n    </div>\n  );\n}\n\nfunction TechnicalDetail({ record }) {\n  const item = record.item;\n  return (\n    <div className=\"checker-tech-detail\">\n      <div>\n        <div className=\"checker-tech-title\">Mesures</div>\n        {record.kind === 'audio' ? (\n          audioMeasureRows(item).map((row) => (\n            <Measure\n              key={row.key}\n              label={row.label}\n              value={row.value}\n              status={hasMeasureIssue(record, row.key)\n                ? (record.issue.fixDisposition === 'optional' ? 'info' : 'bad')\n                : 'ok'}\n            />\n          ))\n        ) : record.kind === 'image' ? (\n          <>\n            {imageMeasureRows(item).map((row) => (\n              <Measure\n                key={row.key}\n                label={row.label}\n                value={row.value}\n                status={hasMeasureIssue(record, row.key) ? 'bad' : 'ok'}\n              />\n            ))}\n            <Measure label=\"Attendu\" value=\"320×240\" status={expectedImageOk(item) ? 'ok' : 'bad'} />\n          </>\n        ) : (\n          <Measure label=\"Catégorie\" value={record.issue.category} status={record.issue.severity === 'ok' ? 'ok' : 'bad'} />\n        )}\n      </div>\n      <div>\n        <div className=\"checker-tech-title\">Ce qu'on va faire</div>\n        {(record.sectionIssues?.length ? record.sectionIssues : record.issues).map((issue, index) => (\n          <div className=\"checker-tech-action\" key={`${issue.message}-${index}`}>\n            <IconFrame Icon={issue.autoFixAvailable ? Wrench : Info} />\n            <div>\n              <strong>{issue.autoFixDescription || issue.message}</strong>\n              {issue.technicalDetails ? <span>{issue.technicalDetails}</span> : null}\n            </div>\n          </div>\n        ))}\n      </div>\n    </div>\n  );\n}\n\nfunction MiniFile({ record, open, onToggle }) {\n  const firstIssue = record.issue;\n  const issueSummary = recordProblemSummary(record);\n  return (\n    <div className=\"checker-mini-file\">\n      <button type=\"button\" className=\"checker-mini-file-button\" onClick={onToggle}>\n        <span className=\"checker-role\">{roleLabel(record)}</span>\n        <span className=\"checker-mini-name\" title={firstIssue.filePath || firstIssue.label}>\n          {cleanLabel(firstIssue.label)}\n        </span>\n        <span className=\"checker-mini-problem\" title={issueSummary}>\n          {issueSummary}\n        </span>\n        <span className={`checker-mini-severity checker-mini-severity--${firstIssue.severity}`}>\n          {severityLabel(firstIssue.severity)}\n        </span>\n        <ChevronDown className={`checker-mini-chevron ${open ? 'is-open' : ''}`} aria-hidden=\"true\" />\n      </button>\n      {open ? <TechnicalDetail record={record} /> : null}\n    </div>\n  );\n}\n\nfunction ProblemGroupCard({\n  group,\n  expanded,\n  onToggle,\n  countValue = group.count,\n  countLabel = null,\n  selectedOptionalSilences = new Set(),\n  onToggleOptionalSilence,\n}) {\n  const [openFile, setOpenFile] = useState(null);\n  const Icon = group.Icon;\n  const displayedCountLabel = countLabel || (countValue > 1 ? 'fichiers' : 'fichier');\n  return (\n    <div className={`checker-group checker-group--${group.bucket} checker-group--${group.id} ${expanded ? 'is-expanded' : ''}`}>\n      <button type=\"button\" className=\"checker-group-head\" onClick={onToggle}>\n        <span className=\"checker-group-icon\"><IconFrame Icon={Icon} /></span>\n        <span className=\"checker-group-copy\">\n          <span className=\"checker-group-title-row\">\n            <strong>{group.title}</strong>\n            <span className=\"checker-group-badge\">{group.badge}</span>\n          </span>\n          <span>{group.bucket === 'fix' ? group.action : group.explanation}</span>\n        </span>\n        <span className=\"checker-group-count\">\n          <strong>{countValue}</strong>\n          <small>{displayedCountLabel}</small>\n        </span>\n        <ChevronDown className=\"checker-group-chevron\" aria-hidden=\"true\" />\n      </button>\n      {expanded ? (\n        <div className=\"checker-group-body\">\n          <div className=\"checker-mini-list\">\n            {group.records.map((record) => (\n              <div key={record.id} className=\"checker-optional-record\">\n                {group.bucket === 'optional' ? (\n                  <label className=\"checker-optional-choice\">\n                    <input\n                      type=\"checkbox\"\n                      checked={selectedOptionalSilences.has(optionalSilenceSelectionKey(record.issue))}\n                      onChange={() => onToggleOptionalSilence?.(record.issue)}\n                    />\n                    <span>{record.issue.autoFixDescription || `Ramener ce silence à ${EDGE_SILENCE_LABEL}`}</span>\n                  </label>\n                ) : null}\n                <MiniFile\n                  record={record}\n                  open={openFile === record.id}\n                  onToggle={() => setOpenFile(openFile === record.id ? null : record.id)}\n                />\n              </div>\n            ))}\n          </div>\n          {group.bucket === 'listen' ? (\n            <div className=\"checker-group-help\">\n              <IconFrame Icon={Info} />\n              Ces fichiers ne sont pas corrigés automatiquement.\n            </div>\n          ) : null}\n        </div>\n      ) : null}\n    </div>\n  );\n}\n\nexport function FixableCorrectionsList({ report, selectedOptionalSilences, onToggleOptionalSilence }) {\n  const groups = useMemo(\n    () => buildProblemGroups(report).filter((group) => group.bucket === 'fix' || group.bucket === 'optional'),\n    [report],\n  );\n\n  if (!groups.length) {\n    return (\n      <div className=\"checker-empty checker-empty--success\">\n        <IconFrame Icon={Check} />\n        Aucune correction automatique à appliquer.\n      </div>\n    );\n  }\n\n  return (\n    <div className=\"checker-groups checker-groups--preview\">\n      {groups.map((group) => (\n        <ProblemGroupCard\n          key={group.id}\n          group={group}\n          expanded\n          onToggle={() => {}}\n          countValue={group.bucket === 'optional' ? group.count : group.fixCount}\n          countLabel={group.bucket === 'optional'\n            ? (group.count > 1 ? 'suggestions' : 'suggestion')\n            : (group.fixCount > 1 ? 'corrections' : 'correction')}\n          selectedOptionalSilences={selectedOptionalSilences}\n          onToggleOptionalSilence={onToggleOptionalSilence}\n        />\n      ))}\n    </div>\n  );\n}\n\nexport function ReportView({\n  report,\n  busy,\n  canFix,\n  onExportReport,\n  onFixPack,\n  onStartFix,\n  showFixButton = true,\n  selectedOptionalSilences,\n  onToggleOptionalSilence,\n}) {\n  const groups = useMemo(() => buildProblemGroups(report), [report]);\n  const summary = useMemo(() => summarizeGroups(groups, report), [groups, report]);\n  const saturatedCount = useMemo(() => saturatedFileCount(groups), [groups]);\n  const [expanded, setExpanded] = useState(groups[0]?.id || null);\n  const [metadataOpen, setMetadataOpen] = useState(false);\n  if (!report) return null;\n  const SummaryIcon = summary.Icon;\n\n  function startFixFlow() {\n    if (onStartFix) {\n      onStartFix();\n      return;\n    }\n    setMetadataOpen(true);\n  }\n\n  return (\n    <div className=\"checker-report\">\n      <div className={`checker-report-verdict checker-report-verdict--${summary.tone}`}>\n        <span className=\"checker-report-orb\"><IconFrame Icon={SummaryIcon} /></span>\n        <div className=\"checker-report-copy\">\n          <div className=\"checker-pack-name\" title={report.packName}>{report.packName}</div>\n          <strong>{summary.title}</strong>\n          <span>{summary.subtitle}</span>\n        </div>\n        <div className=\"checker-report-callout\">\n          <Info className=\"checker-icon\" aria-hidden=\"true\" />\n          <span><strong>{summary.listenCount}</strong> à écouter · <strong>{summary.fixCount}</strong> automatiques · <strong>{summary.optionalCount}</strong> facultatives</span>\n        </div>\n      </div>\n\n      <SummaryTiles report={report} saturatedCount={saturatedCount} />\n\n      {groups.length === 0 ? (\n        <div className=\"checker-empty checker-empty--success\">\n          <IconFrame Icon={Check} />\n          Tout est conforme dans ce rapport.\n        </div>\n      ) : (\n        <div className=\"checker-groups\">\n          {groups.map((group) => (\n            <ProblemGroupCard\n              key={group.id}\n              group={group}\n              expanded={expanded === group.id}\n              onToggle={() => setExpanded(expanded === group.id ? null : group.id)}\n              selectedOptionalSilences={selectedOptionalSilences}\n              onToggleOptionalSilence={onToggleOptionalSilence}\n            />\n          ))}\n        </div>\n      )}\n\n      <ConformingSection report={report} />\n\n      <div className=\"checker-report-footer\">\n        <span><strong>{summary.fixCount}</strong> corrections prêtes · <strong>{summary.optionalCount}</strong> suggestions.</span>\n        <Button size=\"sm\" onClick={() => onExportReport('report')}>\n          <Download className=\"checker-button-icon\" aria-hidden=\"true\" />\n          Exporter le rapport\n        </Button>\n        {showFixButton ? (\n          <button\n            type=\"button\"\n            className=\"chrome-toolbar-cta checker-correction-cta\"\n            onClick={startFixFlow}\n            disabled={!canFix || busy}\n          >\n            {busy ? 'Correction...' : 'Corriger le pack'}\n          </button>\n        ) : null}\n      </div>\n\n      {metadataOpen && !onStartFix ? (\n        <CommunityPackMetadataModal\n          report={report}\n          busy={busy}\n          onCancel={() => setMetadataOpen(false)}\n          onSubmit={(metadataPatch) => {\n            setMetadataOpen(false);\n            onFixPack(metadataPatch);\n          }}\n        />\n      ) : null}\n    </div>\n  );\n}\n\nexport function TechnicalLog({ report, onCopyLog, onExportLog, onExportJson }) {\n  if (!report) return null;\n  return (\n    <details className=\"checker-log\">\n      <summary>Journal technique</summary>\n      <div className=\"checker-log-actions\">\n        <Button size=\"sm\" onClick={onCopyLog}>Copier le log</Button>\n        <Button size=\"sm\" onClick={() => onExportLog('log')}>Exporter le log</Button>\n        <Button size=\"sm\" onClick={() => onExportJson('json')}>Exporter JSON</Button>\n      </div>\n      <pre>{(report.technicalLog || []).join('\\n')}</pre>\n    </details>\n  );\n}\n\nexport function ProcessLog({ status, lines }) {\n  const linesRef = useRef(null);\n  useEffect(() => {\n    const node = linesRef.current;\n    if (!node) return;\n    node.scrollTop = node.scrollHeight;\n  }, [lines]);\n\n  if (!lines?.length) return null;\n  const title = status === 'fixing'\n    ? 'Correction en cours'\n    : status === 'analyzing'\n      ? 'Analyse en cours'\n      : 'Dernières opérations';\n  return (\n    <div className={`checker-process-log ${status === 'idle' ? 'is-idle' : 'is-active'}`}>\n      <div className=\"checker-process-log-head\">\n        {status !== 'idle' ? <IconFrame Icon={Loader2} /> : <IconFrame Icon={CircleCheck} />}\n        <strong>{title}</strong>\n      </div>\n      <div className=\"checker-process-log-lines\" ref={linesRef} aria-live=\"polite\">\n        {lines.map((line, index) => (\n          <div key={`${index}-${line}`}>{line}</div>\n        ))}\n      </div>\n    </div>\n  );\n}\n",
 "src/components/CommunityPackChecker/CommunityPackCheckerFunnel.jsx": "import { TechnicalDetail } from '../common/UserMessage.jsx';\nimport { useMemo, useState } from 'react';\nimport { open as openDialog } from '@tauri-apps/plugin-dialog';\nimport { openPath } from '@tauri-apps/plugin-opener';\nimport {\n  FunnelDoneState,\n  FunnelDropZone,\n  FunnelFooter,\n  FunnelGenerationState,\n  FunnelSectionHeader,\n  FunnelShell,\n  FunnelStepper,\n  FunnelToolButton,\n} from '../funnels';\nimport { CommunityPackMetadataModal } from './CommunityPackMetadataModal';\nimport {\n  FixableCorrectionsList,\n  ProcessLog,\n  ReportView,\n  TechnicalLog,\n  titleNeedsCorrection,\n} from './CommunityPackChecker';\nimport { useCommunityPackChecker } from './useCommunityPackChecker';\nimport { Download, FolderOpen, House, Package, TriangleAlert, Wrench } from '../icons/LucideLocal';\nimport { getLastExportDir, saveLastExportDir } from '../../hooks/useFileDialog';\nimport { basename } from '../../utils/fileUtils';\nimport {\n  optionalSilenceSelectionKey,\n  packCorrectionCounts,\n  serializeOptionalSilenceSelection,\n} from './packCheckerIssueClassification';\nimport './CommunityPackChecker.css';\nimport './CommunityPackCheckerFunnel.css';\n\nconst STEPS = [\n  { key: 'pack', label: 'Pack' },\n  { key: 'report', label: 'Rapport' },\n  { key: 'output', label: 'Correction' },\n];\n\nfunction latestLine(lines) {\n  return lines?.length ? lines[lines.length - 1] : '';\n}\n\nfunction correctionCount(result) {\n  if (!result) return '';\n  const parts = [];\n  if (result.audioFixed) parts.push(`${result.audioFixed} audio`);\n  if (result.imageFixed) parts.push(`${result.imageFixed} image${result.imageFixed > 1 ? 's' : ''}`);\n  if (result.metadataFixed) parts.push('métadonnées');\n  return parts.length ? parts.join(' · ') : 'Pack corrigé';\n}\n\nexport function CommunityPackCheckerFunnel({ onClose }) {\n  const checker = useCommunityPackChecker();\n  const [step, setStep] = useState(0);\n  const [phase, setPhase] = useState('collect');\n  const [outputDir, setOutputDir] = useState(() => getLastExportDir() || '');\n  const [metadataOpen, setMetadataOpen] = useState(false);\n  const [result, setResult] = useState(null);\n  const [localError, setLocalError] = useState('');\n  const [selectedOptionalSilences, setSelectedOptionalSilences] = useState(() => new Set());\n\n  const busy = phase === 'analyzing' || phase === 'fixing' || checker.status === 'analyzing' || checker.status === 'fixing';\n  const correctionCounts = useMemo(() => packCorrectionCounts(checker.report), [checker.report]);\n  const canCreateFixedPack = useMemo(() => (\n    (correctionCounts.automatic > 0 || titleNeedsCorrection(checker.report) || selectedOptionalSilences.size > 0)\n    && !busy\n  ), [checker.report, correctionCounts.automatic, selectedOptionalSilences, busy]);\n  const canOpenReport = !!checker.report;\n  const canOpenCorrection = canOpenReport && (canCreateFixedPack || correctionCounts.optional > 0);\n  const error = localError || checker.error;\n\n  async function analyzePath(path) {\n    const selected = String(path || '').trim();\n    if (!selected) return;\n    setLocalError('');\n    setResult(null);\n    setSelectedOptionalSilences(new Set());\n    setPhase('analyzing');\n    const report = await checker.analyzePath(selected);\n    setPhase('collect');\n    if (report) setStep(1);\n  }\n\n  async function pickPack() {\n    const selected = await openDialog({\n      multiple: false,\n      title: 'Pack à vérifier',\n      filters: [{ name: 'Pack Lunii', extensions: ['zip', '7z'] }],\n    });\n    if (selected) await analyzePath(Array.isArray(selected) ? selected[0] : selected);\n  }\n\n  async function chooseOutputDir() {\n    const selected = await openDialog({\n      directory: true,\n      multiple: false,\n      title: 'Dossier du pack corrigé',\n      defaultPath: outputDir || getLastExportDir() || undefined,\n    });\n    const nextOutputDir = Array.isArray(selected) ? selected[0] : selected;\n    if (!nextOutputDir) return null;\n    setOutputDir(nextOutputDir);\n    saveLastExportDir(nextOutputDir);\n    return nextOutputDir;\n  }\n\n  async function fixPack(metadataPatch = null) {\n    setMetadataOpen(false);\n    setLocalError('');\n    const selectedOutputDir = await chooseOutputDir();\n    if (!selectedOutputDir) {\n      return;\n    }\n    setPhase('fixing');\n    const fixed = await checker.fixPack(metadataPatch, {\n      outputDir: selectedOutputDir,\n      correctionSelection: {\n        optionalAudioSilences: serializeOptionalSilenceSelection(\n          checker.report,\n          selectedOptionalSilences,\n        ),\n      },\n    });\n    setPhase(fixed ? 'done' : 'collect');\n    if (fixed) setResult(fixed);\n  }\n\n  function handlePrimary() {\n    if (step === 0) {\n      // CTA actif seulement quand un pack est déjà choisi (zone de dépôt ou\n      // bouton « Choisir un pack ») : le footer ne duplique plus le picker.\n      if (checker.zipPath) void analyzePath(checker.zipPath);\n      return;\n    }\n    if (step === 1) {\n      if (!canOpenCorrection) {\n        onClose();\n        return;\n      }\n      setStep(2);\n      return;\n    }\n    // La fenêtre des métadonnées s'ouvre toujours avant de créer le ZIP\n    // corrigé : l'identité du pack s'y garde ou s'y renouvelle, comme au Libre.\n    setMetadataOpen(true);\n  }\n\n  function handleStepClick(index) {\n    if (index === 0) setStep(0);\n    if (index === 1 && canOpenReport) setStep(1);\n    if (index === 2 && canOpenCorrection) setStep(2);\n  }\n\n  const primaryLabel = step === 0\n    ? 'Analyser'\n    : step === 1\n      ? (canCreateFixedPack ? 'Corriger le pack' : (correctionCounts.optional > 0 ? 'Voir les suggestions' : 'Terminer'))\n      : 'Créer le pack corrigé';\n\n  function toggleOptionalSilence(issue) {\n    const key = optionalSilenceSelectionKey(issue);\n    if (!key) return;\n    setSelectedOptionalSilences((current) => {\n      const next = new Set(current);\n      if (next.has(key)) next.delete(key);\n      else next.add(key);\n      return next;\n    });\n  }\n\n  return (\n    <FunnelShell\n      icon={<Wrench />}\n      title=\"Vérifier / corriger un pack\"\n      subtitle=\"Analyse un ZIP et crée une version corrigée si besoin.\"\n      size=\"wide\"\n      onClose={busy ? () => {} : onClose}\n      showChrome={phase === 'collect'}\n      ariaLabel=\"Vérifier ou corriger un pack\"\n      stepper={(\n        <FunnelStepper\n          steps={STEPS}\n          current={step}\n          onStepClick={handleStepClick}\n        />\n      )}\n      footer={(\n        <FunnelFooter\n          onBack={() => setStep(Math.max(0, step - 1))}\n          backDisabled={step === 0}\n          stepLabel={`Étape ${step + 1} / ${STEPS.length}`}\n          onPrimary={handlePrimary}\n          primaryLabel={primaryLabel}\n          primaryDisabled={busy || (step === 0 && !checker.zipPath) || (step === 2 && !canCreateFixedPack)}\n        />\n      )}\n    >\n      {phase === 'analyzing' ? (\n        <FunnelGenerationState\n          title=\"Analyse du pack…\"\n          hint={latestLine(checker.liveLog) || 'Lecture du ZIP, des médias et de la structure.'}\n        />\n      ) : phase === 'fixing' ? (\n        <FunnelGenerationState\n          title=\"Correction du pack…\"\n          hint={latestLine(checker.liveLog) || 'Création du nouveau ZIP corrigé.'}\n        />\n      ) : phase === 'done' ? (\n        <FunnelDoneState\n          title=\"Pack corrigé créé\"\n          fileName={basename(result?.fixedZipPath) || result?.fixedZipPath}\n          meta={correctionCount(result)}\n        >\n          <button type=\"button\" className=\"funnel-btn\" onClick={() => outputDir && openPath(outputDir)}>\n            <FolderOpen />\n            Ouvrir le dossier\n          </button>\n          <button type=\"button\" className=\"funnel-btn\" onClick={() => checker.exportReport('report')}>\n            <Download />\n            Exporter le rapport\n          </button>\n          <button type=\"button\" className=\"funnel-btn funnel-btn-primary\" onClick={onClose}>\n            <House />\n            Terminer\n          </button>\n        </FunnelDoneState>\n      ) : (\n        <div className=\"checker-root pack-checker-funnel\">\n          {step === 0 ? (\n            <div className=\"funnel-step-content pack-checker-step\">\n              <FunnelSectionHeader\n                icon={<Package />}\n                title=\"Pack à vérifier\"\n                description=\"Choisis ou dépose un fichier ZIP ou 7z. Le fichier source reste intact.\"\n              />\n              <FunnelDropZone\n                icon={<Package />}\n                title=\"Déposer un pack .zip ou .7z\"\n                hint=\"L'analyse vérifie l'audio, les images, le nom, la structure et le mode nuit.\"\n                disabled={busy}\n                onFiles={(paths) => analyzePath(paths?.[0])}\n              >\n                <button type=\"button\" className=\"funnel-btn\" onClick={pickPack} disabled={busy}>\n                  Choisir un pack\n                </button>\n              </FunnelDropZone>\n              {checker.zipPath ? (\n                <div className=\"pack-checker-selected\" title={checker.zipPath}>\n                  <Package />\n                  <span>{checker.zipPath}</span>\n                </div>\n              ) : null}\n              <ProcessLog status={checker.status} lines={checker.liveLog} />\n              {error ? <div className=\"funnel-error\" role=\"alert\">{error}<TechnicalDetail value={localError ? null : checker.technicalDetail} /></div> : null}\n            </div>\n          ) : step === 1 ? (\n            <div className=\"funnel-step-content pack-checker-step pack-checker-step--report\">\n              <FunnelSectionHeader\n                icon={<TriangleAlert />}\n                title=\"Rapport\"\n                description=\"Lis les points conformes, les corrections possibles et les vérifications manuelles.\"\n              />\n              {error ? <div className=\"funnel-error\" role=\"alert\">{error}<TechnicalDetail value={localError ? null : checker.technicalDetail} /></div> : null}\n              <ReportView\n                report={checker.report}\n                busy={busy}\n                canFix={canCreateFixedPack}\n                onExportReport={checker.exportReport}\n                onFixPack={(metadataPatch) => fixPack(metadataPatch)}\n                onStartFix={() => setStep(2)}\n                showFixButton={false}\n                selectedOptionalSilences={selectedOptionalSilences}\n                onToggleOptionalSilence={toggleOptionalSilence}\n              />\n              <TechnicalLog\n                report={checker.report}\n                onCopyLog={checker.copyLog}\n                onExportLog={checker.exportReport}\n                onExportJson={checker.exportReport}\n              />\n            </div>\n          ) : (\n            <div className=\"funnel-step-content pack-checker-step\">\n              <FunnelSectionHeader\n                icon={<Wrench />}\n                title=\"Voici ce qui va être corrigé\"\n                description=\"Le clic final ouvrira le choix du dossier de sortie, puis créera le ZIP corrigé.\"\n              />\n              <FixableCorrectionsList\n                report={checker.report}\n                selectedOptionalSilences={selectedOptionalSilences}\n                onToggleOptionalSilence={toggleOptionalSilence}\n              />\n              {checker.exportNotice ? <div className=\"info-box\">{checker.exportNotice}</div> : null}\n              {error ? <div className=\"funnel-error\" role=\"alert\">{error}<TechnicalDetail value={localError ? null : checker.technicalDetail} /></div> : null}\n              <div className=\"pack-checker-inline-actions\">\n                <FunnelToolButton icon={<Download />} accent=\"neutral\" onClick={() => checker.exportReport('report')}>\n                  Exporter le rapport\n                </FunnelToolButton>\n              </div>\n              {metadataOpen ? (\n                <CommunityPackMetadataModal\n                  report={checker.report}\n                  busy={busy}\n                  onCancel={() => setMetadataOpen(false)}\n                  onSubmit={(metadataPatch) => fixPack(metadataPatch)}\n                />\n              ) : null}\n            </div>\n          )}\n        </div>\n      )}\n    </FunnelShell>\n  );\n}\n",
 "src/components/CommunityPackChecker/CommunityPackConforming.jsx": "// Section « Ce qui est conforme » : miroir vert des cartes de problemes.\n// Toute la donnee vient deja du rapport (report.audioItems / imageItems avec\n// leur `status`, et les resumes pack-level) : aucun appel backend.\n\nimport { useMemo, useState } from 'react';\nimport {\n  Check,\n  ChevronDown,\n  FilePen,\n  Image,\n  Moon,\n  Music,\n  Network,\n} from '../icons/LucideLocal';\nimport {\n  Measure,\n  audioMeasureRows,\n  cleanLabel,\n  formatLufs,\n  formatSeconds,\n  imageMeasureRows,\n  isConforming,\n  structureConforming,\n  titleConforming,\n} from './packCheckerMeasures';\n\nfunction IconFrame({ Icon }) {\n  return <Icon className=\"checker-icon\" aria-hidden=\"true\" strokeWidth={2} absoluteStrokeWidth />;\n}\n\nfunction fileSummary(kind, item) {\n  if (kind === 'audio') {\n    return `Silence ${formatSeconds(item.leadingSilenceSecs)} / ${formatSeconds(item.trailingSilenceSecs)} · ${formatLufs(item.integratedLufs)}`;\n  }\n  const dimensions = item.width && item.height ? `${item.width}×${item.height}` : 'dimensions ?';\n  return `${dimensions} · ${item.format || 'format ?'}`;\n}\n\nfunction buildConformingGroups(report) {\n  if (!report) return [];\n  const groups = [];\n\n  const audioFiles = (report.audioItems || []).filter((item) => isConforming(item.status));\n  if (audioFiles.length) {\n    groups.push({\n      id: 'audio',\n      title: 'Audio conforme',\n      subtitle: 'Silence, volume, format et crête dans les clous.',\n      Icon: Music,\n      mode: 'files',\n      kind: 'audio',\n      files: audioFiles,\n      metricStrong: String(audioFiles.length),\n      metricSmall: audioFiles.length > 1 ? 'fichiers' : 'fichier',\n    });\n  }\n\n  const imageFiles = (report.imageItems || []).filter((item) => isConforming(item.status));\n  if (imageFiles.length) {\n    groups.push({\n      id: 'image',\n      title: 'Images conformes',\n      subtitle: 'Dimensions et format conformes.',\n      Icon: Image,\n      mode: 'files',\n      kind: 'image',\n      files: imageFiles,\n      metricStrong: String(imageFiles.length),\n      metricSmall: imageFiles.length > 1 ? 'fichiers' : 'fichier',\n    });\n  }\n\n  if (titleConforming(report)) {\n    groups.push({\n      id: 'title',\n      title: 'Nom du pack',\n      subtitle: 'Nom et convention valides.',\n      Icon: FilePen,\n      mode: 'facts',\n      metricStrong: 'Valide',\n      metricSmall: 'Convention OK',\n      facts: [\n        { key: 'name', label: 'Nom', value: report.packName || '—' },\n        { key: 'title', label: 'Titre', value: report.packTitle || '—' },\n        { key: 'version', label: 'Version', value: String(report.packVersion ?? '—') },\n      ],\n    });\n  }\n\n  if (structureConforming(report)) {\n    const structure = report.structureSummary || {};\n    groups.push({\n      id: 'structure',\n      title: 'Structure',\n      subtitle: 'Navigation et références cohérentes.',\n      Icon: Network,\n      mode: 'facts',\n      metricStrong: 'Correcte',\n      metricSmall: `${structure.stageCount ?? 0} étapes`,\n      facts: [\n        { key: 'lunii', label: 'Compatible Lunii', value: structure.luniiCompatible ? 'Oui' : 'Non' },\n        { key: 'editable', label: 'Éditable Story Studio', value: structure.storyStudioEditable ? 'Oui' : 'Non' },\n        { key: 'stories', label: 'Histoires', value: String(structure.storyCount ?? 0) },\n        { key: 'stages', label: 'Étapes', value: String(structure.stageCount ?? 0) },\n        { key: 'actions', label: 'Listes de choix', value: String(structure.actionCount ?? 0) },\n        { key: 'refAudio', label: 'Audios référencés', value: String(structure.referencedAudioCount ?? 0) },\n        { key: 'refImage', label: 'Images référencées', value: String(structure.referencedImageCount ?? 0) },\n      ],\n    });\n  }\n\n  const nightDetected = Boolean(report.nightMode?.detected);\n  groups.push({\n    id: 'night',\n    title: 'Mode nuit',\n    subtitle: nightDetected ? 'Piste nuit détectée dans le pack.' : 'Aucune piste nuit (non requis).',\n    Icon: Moon,\n    mode: 'facts',\n    metricStrong: nightDetected ? 'Disponible' : 'Absent',\n    metricSmall: 'Non bloquant',\n    facts: [\n      { key: 'detected', label: 'Mode nuit', value: nightDetected ? 'Disponible' : 'Absent' },\n      { key: 'blocking', label: 'Bloquant', value: 'Non' },\n    ],\n  });\n\n  return groups;\n}\n\nfunction ConformingMeasures({ rows, title = 'Mesures' }) {\n  return (\n    <div className=\"checker-tech-detail checker-tech-detail--facts\">\n      <div>\n        <div className=\"checker-tech-title\">{title}</div>\n        {rows.map((row) => (\n          <Measure key={row.key} label={row.label} value={row.value} status=\"ok\" />\n        ))}\n      </div>\n    </div>\n  );\n}\n\nfunction ConformingFile({ kind, item, open, onToggle }) {\n  const rows = kind === 'audio'\n    ? audioMeasureRows(item)\n    : [...imageMeasureRows(item), { key: 'expected', label: 'Attendu', value: '320×240' }];\n  const summary = fileSummary(kind, item);\n  return (\n    <div className=\"checker-mini-file\">\n      <button type=\"button\" className=\"checker-mini-file-button\" onClick={onToggle}>\n        <span className=\"checker-role\">{kind === 'audio' ? 'Audio' : 'Image'}</span>\n        <span className=\"checker-mini-name\" title={item.filePath || item.label}>{cleanLabel(item.label)}</span>\n        <span className=\"checker-mini-problem\" title={summary}>{summary}</span>\n        <span className=\"checker-mini-severity checker-mini-severity--ok\">OK</span>\n        <ChevronDown className={`checker-mini-chevron ${open ? 'is-open' : ''}`} aria-hidden=\"true\" />\n      </button>\n      {open ? <ConformingMeasures rows={rows} /> : null}\n    </div>\n  );\n}\n\nfunction ConformingGroupCard({ group, expanded, onToggle }) {\n  const [openFile, setOpenFile] = useState(null);\n  const Icon = group.Icon;\n  return (\n    <div className={`checker-group checker-group--ok checker-group--${group.id} ${expanded ? 'is-expanded' : ''}`}>\n      <button type=\"button\" className=\"checker-group-head\" onClick={onToggle}>\n        <span className=\"checker-group-icon\"><IconFrame Icon={Icon} /></span>\n        <span className=\"checker-group-copy\">\n          <span className=\"checker-group-title-row\">\n            <strong>{group.title}</strong>\n            <span className=\"checker-group-badge\">Conforme</span>\n          </span>\n          <span>{group.subtitle}</span>\n        </span>\n        <span className=\"checker-group-count\">\n          <strong>{group.metricStrong}</strong>\n          <small>{group.metricSmall}</small>\n        </span>\n        <ChevronDown className=\"checker-group-chevron\" aria-hidden=\"true\" />\n      </button>\n      {expanded ? (\n        <div className=\"checker-group-body\">\n          {group.mode === 'files' ? (\n            <div className=\"checker-mini-list\">\n              {group.files.map((item) => {\n                const fileId = item.filePath || item.label;\n                return (\n                  <ConformingFile\n                    key={fileId}\n                    kind={group.kind}\n                    item={item}\n                    open={openFile === fileId}\n                    onToggle={() => setOpenFile(openFile === fileId ? null : fileId)}\n                  />\n                );\n              })}\n            </div>\n          ) : (\n            <ConformingMeasures rows={group.facts} title=\"Détails\" />\n          )}\n        </div>\n      ) : null}\n    </div>\n  );\n}\n\nexport function ConformingSection({ report }) {\n  const groups = useMemo(() => buildConformingGroups(report), [report]);\n  const [expanded, setExpanded] = useState(null);\n  if (!groups.length) return null;\n  return (\n    <div className=\"checker-conform\">\n      <div className=\"checker-conform-head\">\n        <IconFrame Icon={Check} />\n        Ce qui est conforme\n      </div>\n      <div className=\"checker-groups\">\n        {groups.map((group) => (\n          <ConformingGroupCard\n            key={group.id}\n            group={group}\n            expanded={expanded === group.id}\n            onToggle={() => setExpanded(expanded === group.id ? null : group.id)}\n          />\n        ))}\n      </div>\n    </div>\n  );\n}\n",
 "src/components/CommunityPackChecker/CommunityPackMetadataModal.jsx": "import { useEffect, useMemo, useRef, useState } from 'react';\nimport { invoke } from '@tauri-apps/api/core';\nimport { Button } from '../common/Button';\nimport { CircleCheck, FilePen, Package, TriangleAlert, X } from '../icons/LucideLocal';\nimport { useEscapeKey } from '../../hooks/useEscapeKey';\nimport { generateConventionName, parseConventionName } from '../../utils/packConvention';\nimport { generateUuid } from '../../utils/uuid';\nimport { packIdentityRefusal } from '../../store/packIdentityCheck';\nimport { useErrorDialog } from '../common/Dialog';\nimport './CommunityPackMetadataModal.css';\n\nconst AGE_CHIPS = ['2', '3', '6', '9', '12'];\n\nfunction normalizeVersion(value) {\n  const parsed = Number.parseInt(String(value || '').replace(/\\D/g, ''), 10);\n  return Number.isFinite(parsed) && parsed > 0 ? parsed : 1;\n}\n\nfunction normalizeDraft(draft) {\n  const parsedTitle = parseConventionName(draft.title || '');\n  return {\n    title: parsedTitle?.title || String(draft.title || '').trim(),\n    author: parsedTitle?.author || String(draft.author || '').trim(),\n    producer: parsedTitle?.producer || String(draft.producer || '').trim(),\n    bonus: parsedTitle?.bonus || String(draft.bonus || '').trim(),\n    description: String(draft.description || '').trim(),\n    uuid: String(draft.uuid || '').trim(),\n    minAge: parsedTitle?.minAge || String(draft.minAge || '3').replace(/\\D/g, '') || '3',\n    version: Math.max(normalizeVersion(parsedTitle?.version), normalizeVersion(draft.version)),\n    namingMode: 'convention',\n  };\n}\n\nfunction defaultDraft(report) {\n  const parsed = parseConventionName(report?.packTitle || '')\n    || parseConventionName(report?.packName || '')\n    || {};\n  const currentVersion = Math.max(\n    normalizeVersion(parsed.version),\n    normalizeVersion(report?.packVersion),\n  );\n  return {\n    title: parsed.title || report?.packTitle || report?.packName || '',\n    author: parsed.author || '',\n    producer: parsed.producer || '',\n    bonus: parsed.bonus || '',\n    description: report?.packDescription || parsed.description || '',\n    // Un pack sans identité lisible en reçoit une neuve, sans avertissement.\n    uuid: report?.packUuid || generateUuid(),\n    minAge: parsed.minAge || '3',\n    version: currentVersion + 1,\n    namingMode: 'convention',\n  };\n}\n\nfunction filenameTokens(exportName) {\n  if (!exportName) return [{ kind: 'empty', text: 'Titre requis' }];\n  const tokens = [];\n  const ageMatch = exportName.match(/^(\\d+\\+\\])/);\n  let rest = exportName;\n  if (ageMatch) {\n    tokens.push({ kind: 'age', text: ageMatch[1] });\n    rest = rest.slice(ageMatch[1].length);\n  }\n  const authorIndex = rest.indexOf('[by_');\n  const body = authorIndex === -1 ? rest : rest.slice(0, authorIndex);\n  const author = authorIndex === -1 ? '' : rest.slice(authorIndex);\n  if (body) tokens.push({ kind: 'title', text: body });\n  if (author) tokens.push({ kind: 'author', text: author });\n  return tokens;\n}\n\nfunction titleIssues(report) {\n  return (report?.issues || []).filter((issue) => (\n    issue.category === 'title' && (issue.severity === 'warning' || issue.severity === 'error')\n  ));\n}\n\nexport function CommunityPackMetadataModal({\n  report,\n  busy = false,\n  onCancel,\n  onSubmit,\n}) {\n  const [draft, setDraft] = useState(() => defaultDraft(report));\n  const [uuidPromptOpen, setUuidPromptOpen] = useState(false);\n  const [identityRefusal, setIdentityRefusal] = useState(null);\n  const uuidPromptRequestRef = useRef(null);\n  const currentReportRef = useRef(report);\n  currentReportRef.current = report;\n  const { showConfirmDialog } = useErrorDialog();\n  const normalized = useMemo(() => normalizeDraft(draft), [draft]);\n  const exportName = useMemo(() => generateConventionName(normalized), [normalized]);\n  const tokens = useMemo(() => filenameTokens(exportName), [exportName]);\n  const issues = useMemo(() => titleIssues(report), [report]);\n  const currentAge = String(draft.minAge || '3').replace(/\\D/g, '') || '3';\n  const customAge = AGE_CHIPS.includes(currentAge) ? '' : currentAge;\n  const canSubmit = normalized.title.length > 0 && !busy && !uuidPromptOpen;\n  useEscapeKey(!busy && !uuidPromptOpen, onCancel);\n\n  useEffect(() => {\n    const currentUuid = String(report?.packUuid || '').trim();\n    if (!currentUuid) {\n      uuidPromptRequestRef.current = null;\n      setUuidPromptOpen(false);\n      return undefined;\n    }\n\n    let request = uuidPromptRequestRef.current;\n    // StrictMode rejoue l'effet : la même promesse est réutilisée pour ne pas\n    // rouvrir le dialogue tout en laissant la seconde exécution traiter le choix.\n    if (!request || request.uuid !== currentUuid) {\n      request = {\n        uuid: currentUuid,\n        report,\n        promise: showConfirmDialog({\n          title: 'Générer un nouvel UUID ?',\n          message:\n            'La correction crée une nouvelle archive. Un nouvel UUID permet de '\n            + \"l'identifier comme un pack distinct.\",\n          variant: 'warning',\n          okLabel: 'Générer un nouvel UUID',\n          cancelLabel: \"Conserver l'UUID actuel\",\n        }),\n      };\n      uuidPromptRequestRef.current = request;\n    }\n\n    let cancelled = false;\n    setUuidPromptOpen(true);\n    request.promise.then((wantsNewUuid) => {\n      if (cancelled || uuidPromptRequestRef.current !== request) return;\n      setUuidPromptOpen(false);\n      if (!wantsNewUuid || currentReportRef.current !== request.report) return;\n      setDraft((current) => ({ ...current, uuid: generateUuid() }));\n    });\n\n    return () => {\n      cancelled = true;\n    };\n  }, [report?.packUuid, showConfirmDialog]);\n\n  function updateField(field, value) {\n    setDraft((current) => ({\n      ...current,\n      [field]: field === 'version' ? normalizeVersion(value) : value,\n    }));\n  }\n\n  function updateAge(value) {\n    updateField('minAge', String(value || '').replace(/\\D/g, ''));\n  }\n\n  function regenerateUuid() {\n    updateField('uuid', generateUuid());\n  }\n\n  async function submit() {\n    if (!canSubmit) return;\n    // Même contrôle que la fiche du pack : une graphie que les passerelles ne\n    // liraient pas est refusée ici, avec sa raison.\n    const refusal = await packIdentityRefusal(normalized.uuid, invoke);\n    setIdentityRefusal(refusal);\n    if (refusal) return;\n    onSubmit?.(normalized);\n  }\n\n  return (\n    <div\n      className=\"checker-meta-overlay\"\n      data-modal-surface=\"\"\n      role=\"dialog\"\n      aria-modal=\"true\"\n      aria-label=\"Correction des métadonnées\"\n      onMouseDown={onCancel}\n    >\n      <div className=\"checker-meta-modal\" onMouseDown={(event) => event.stopPropagation()}>\n        <header className=\"checker-meta-header\">\n          <span className=\"checker-meta-header-icon\"><FilePen className=\"checker-icon\" aria-hidden=\"true\" /></span>\n          <div className=\"checker-meta-heading\">\n            <span>Correction des métadonnées</span>\n            <h2 title={exportName || undefined}>{exportName || 'Nom du pack'}</h2>\n            <p>Chaque correction crée une nouvelle révision : la version est proposée à +1.</p>\n          </div>\n          <button type=\"button\" className=\"checker-meta-close\" onClick={onCancel} aria-label=\"Fermer\">\n            <X className=\"checker-icon\" aria-hidden=\"true\" />\n          </button>\n        </header>\n\n        <div className=\"checker-meta-body\">\n          <aside className=\"checker-meta-side\">\n            <div className=\"checker-meta-pack-icon\">\n              <Package className=\"checker-icon\" aria-hidden=\"true\" />\n            </div>\n            <div>\n              <strong>{report?.packName || 'Pack communautaire'}</strong>\n              <span title={report?.zipPath}>{report?.zipPath}</span>\n            </div>\n            {issues.length > 0 ? (\n              <div className=\"checker-meta-issues\">\n                {issues.map((issue, index) => (\n                  <div key={`${issue.message}-${index}`}>\n                    <TriangleAlert className=\"checker-icon\" aria-hidden=\"true\" />\n                    <span>{issue.message}</span>\n                  </div>\n                ))}\n              </div>\n            ) : (\n              <div className=\"checker-meta-ok\">\n                <CircleCheck className=\"checker-icon\" aria-hidden=\"true\" />\n                <span>Le nom semble déjà valide.</span>\n              </div>\n            )}\n          </aside>\n\n          <section className=\"checker-meta-form\">\n            <label>\n              <span>Titre du pack</span>\n              <input\n                autoFocus\n                value={draft.title || ''}\n                onChange={(event) => updateField('title', event.target.value)}\n                placeholder=\"Titre du pack\"\n              />\n            </label>\n\n            <label>\n              <span>Âge minimum</span>\n              <div className=\"checker-meta-age\">\n                {AGE_CHIPS.map((age) => (\n                  <button\n                    key={age}\n                    type=\"button\"\n                    className={currentAge === age ? 'is-active' : ''}\n                    onClick={() => updateAge(age)}\n                  >\n                    {age}+\n                  </button>\n                ))}\n                <input\n                  value={customAge}\n                  onChange={(event) => updateAge(event.target.value)}\n                  inputMode=\"numeric\"\n                  placeholder=\"Autre\"\n                />\n              </div>\n            </label>\n\n            <div className=\"checker-meta-grid\">\n              <label>\n                <span>Auteur</span>\n                <input value={draft.author || ''} onChange={(event) => updateField('author', event.target.value)} placeholder=\"Nom de l'auteur\" />\n              </label>\n              <label>\n                <span>Version</span>\n                <input type=\"number\" min=\"1\" value={draft.version || 1} onChange={(event) => updateField('version', event.target.value)} />\n              </label>\n            </div>\n\n            <div className=\"checker-meta-grid\">\n              <label>\n                <span>Producteur</span>\n                <input value={draft.producer || ''} onChange={(event) => updateField('producer', event.target.value)} placeholder=\"Ex. producteur...\" />\n              </label>\n              <label>\n                <span>Bonus</span>\n                <input value={draft.bonus || ''} onChange={(event) => updateField('bonus', event.target.value)} placeholder=\"facultatif\" />\n              </label>\n            </div>\n\n            <label>\n              <span>Description</span>\n              <textarea value={draft.description || ''} onChange={(event) => updateField('description', event.target.value)} rows={3} placeholder=\"Description ou changelog...\" />\n            </label>\n\n            <label>\n              <span>UUID</span>\n              <div className=\"checker-meta-uuid\">\n                <input value={draft.uuid || ''} onChange={(event) => updateField('uuid', event.target.value)} placeholder=\"UUID du pack\" />\n                <button type=\"button\" onClick={regenerateUuid}>Générer</button>\n              </div>\n              {identityRefusal ? <p className=\"funnel-error\" role=\"alert\">{identityRefusal}</p> : null}\n            </label>\n          </section>\n        </div>\n\n        <div className=\"checker-meta-preview\">\n          <span>Aperçu convention communautaire</span>\n          <div title={exportName ? `${exportName}.zip` : undefined}>\n            {tokens.map((token, index) => (\n              <em key={`${token.kind}-${index}-${token.text}`} className={`is-${token.kind}`}>{token.text}</em>\n            ))}\n            <em className=\"is-ext\">.zip</em>\n          </div>\n        </div>\n\n        <footer className=\"checker-meta-footer\">\n          <Button onClick={onCancel} disabled={busy}>Annuler</Button>\n          <button type=\"button\" className=\"chrome-toolbar-cta checker-correction-cta\" onClick={submit} disabled={!canSubmit}>\n            {busy ? 'Correction...' : 'Corriger le pack'}\n          </button>\n        </footer>\n      </div>\n    </div>\n  );\n}\n",
 "src/components/CommunityPackChecker/communityPackExports.js": "import { presentCheckerReport } from '../../i18n/checkerMessages.js';\nimport { measuredIssueSummary, silenceSummaryParts } from './packCheckerIssueClassification.js';\nimport { getIntlLocale } from '../../i18n/language.js';\nimport {\n  audioMeasureRows,\n  cleanLabel,\n  expectedImageOk,\n  formatLufs,\n  formatPeak,\n  formatSeconds,\n  imageMeasureRows,\n  isConforming,\n  structureConforming,\n  titleConforming,\n} from './packCheckerFormat.js';\nimport { formatPackAudioEdgeSilence } from '../../config/audioProcessing.js';\nimport {\n  issueHasMeasure,\n  isAudioFormatIssue,\n  isSaturatedIssue,\n  hasMeasureIssue as hasMeasureIssues,\n  automaticCorrectionCount,\n  categoryConformanceStats,\n  isAutomaticSilenceIssue,\n  isAutomaticVolumeIssue,\n  isOptionalSilenceIssue,\n  packCorrectionCounts,\n} from './packCheckerIssueClassification.js';\n\nconst EDGE_SILENCE_LABEL = formatPackAudioEdgeSilence();\n\nfunction severityLabel(severity) {\n  switch (severity) {\n    case 'error':\n      return 'Erreur';\n    case 'warning':\n      return 'Avertissement';\n    case 'info':\n      return 'Info';\n    case 'ok':\n      return 'OK';\n    default:\n      return severity || 'Info';\n  }\n}\n\nfunction verdictLabel(verdict) {\n  switch (verdict) {\n    case 'valid':\n      return 'Pack conforme';\n    case 'validWithWarnings':\n      return 'Pack validable avec avertissements';\n    case 'needsFix':\n      return 'Pack à corriger avant validation';\n    case 'invalid':\n      return 'Pack invalide ou illisible';\n    default:\n      return 'Pack analysé';\n  }\n}\n\nfunction escapeHtml(value) {\n  return String(value ?? '')\n    .replace(/&/g, '&amp;')\n    .replace(/</g, '&lt;')\n    .replace(/>/g, '&gt;')\n    .replace(/\"/g, '&quot;')\n    .replace(/'/g, '&#39;');\n}\n\nfunction html(strings, ...values) {\n  return strings.reduce((output, chunk, index) => (\n    `${output}${chunk}${values[index] ?? ''}`\n  ), '');\n}\n\nconst ICONS = {\n  audio: '<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M9 18V5l10-2v13\"/><circle cx=\"6\" cy=\"18\" r=\"3\"/><circle cx=\"16\" cy=\"16\" r=\"3\"/></svg>',\n  check: '<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"m5 13 4 4L19 7\"/></svg>',\n  file: '<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M14 2H7a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h10a2 2 0 0 0 2-2V7z\"/><path d=\"M14 2v5h5\"/><path d=\"M10 14h4\"/><path d=\"M10 18h2\"/></svg>',\n  image: '<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><rect x=\"3\" y=\"3\" width=\"18\" height=\"18\" rx=\"2\"/><circle cx=\"9\" cy=\"9\" r=\"2\"/><path d=\"m21 15-3.5-3.5a2 2 0 0 0-3 0L5 21\"/></svg>',\n  info: '<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><path d=\"M12 16v-4\"/><path d=\"M12 8h.01\"/></svg>',\n  moon: '<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M12 3a6 6 0 1 0 9 7.4A8.5 8.5 0 1 1 12 3z\"/></svg>',\n  network: '<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><rect x=\"16\" y=\"16\" width=\"6\" height=\"6\" rx=\"1\"/><rect x=\"2\" y=\"16\" width=\"6\" height=\"6\" rx=\"1\"/><rect x=\"9\" y=\"2\" width=\"6\" height=\"6\" rx=\"1\"/><path d=\"M12 8v4\"/><path d=\"M5 16v-2a2 2 0 0 1 2-2h10a2 2 0 0 1 2 2v2\"/></svg>',\n  package: '<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"m12 3 8 4.5v9L12 21l-8-4.5v-9z\"/><path d=\"m4 7.5 8 4.5 8-4.5\"/><path d=\"M12 12v9\"/></svg>',\n  warning: '<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"m12 3 10 18H2z\"/><path d=\"M12 9v5\"/><path d=\"M12 18h.01\"/></svg>',\n  wrench: '<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M14.7 6.3a4 4 0 0 0-5 5L3 18v3h3l6.7-6.7a4 4 0 0 0 5-5l-2.4 2.4-2.8-2.8z\"/></svg>',\n};\n\nfunction icon(name) {\n  return ICONS[name] || ICONS.info;\n}\n\nfunction hasMeasureIssue(issues, key) {\n  return hasMeasureIssues(issues, key);\n}\n\nfunction itemMap(report) {\n  const map = new Map();\n  for (const item of report?.audioItems || []) map.set(item.filePath, { kind: 'audio', item });\n  for (const item of report?.imageItems || []) map.set(item.filePath, { kind: 'image', item });\n  return map;\n}\n\nfunction issuesByFilePath(report) {\n  const map = new Map();\n  for (const issue of report?.issues || []) {\n    if (!issue.filePath) continue;\n    if (!map.has(issue.filePath)) map.set(issue.filePath, []);\n    map.get(issue.filePath).push(issue);\n  }\n  return map;\n}\n\nfunction uniqueIssueKey(issue) {\n  return issue.filePath || `${issue.category}:${issue.code ?? ''}:${issue.label}`;\n}\n\nconst PROBLEM_SECTIONS = [\n  {\n    id: 'quality',\n    title: 'Audio de mauvaise qualité (source saturée)',\n    badge: 'Source',\n    bucket: 'listen',\n    icon: 'warning',\n    action: \"Reprends le pack depuis une source audio plus propre.\",\n    match: (issue) => (\n      issue.category === 'audio'\n      && !issue.autoFixAvailable\n      && isSaturatedIssue(issue)\n    ),\n  },\n  {\n    id: 'listen',\n    title: 'À écouter',\n    badge: 'Manuel',\n    bucket: 'listen',\n    icon: 'info',\n    action: 'Écoute ou vérifie ces fichiers avant de valider le pack.',\n    match: (issue) => !isOptionalSilenceIssue(issue) && !issue.autoFixAvailable && issue.category !== 'structure' && issue.category !== 'title',\n  },\n  {\n    id: 'silence',\n    title: 'Silence début / fin incorrect',\n    badge: 'Auto',\n    bucket: 'fix',\n    icon: 'wrench',\n    action: `On ajuste le silence vers ${EDGE_SILENCE_LABEL}.`,\n    match: isAutomaticSilenceIssue,\n  },\n  {\n    id: 'optionalSilence',\n    title: 'Suggestions facultatives',\n    badge: 'Facultatif',\n    bucket: 'optional',\n    icon: 'info',\n    action: `Ces silences longs peuvent être volontaires. Le pack reste conforme ; ils peuvent être ramenés à ${EDGE_SILENCE_LABEL}.`,\n    match: isOptionalSilenceIssue,\n  },\n  {\n    id: 'volume',\n    title: 'Niveau sonore incorrect',\n    badge: 'Auto',\n    bucket: 'fix',\n    icon: 'audio',\n    action: 'On normalise le volume au bon niveau.',\n    match: isAutomaticVolumeIssue,\n  },\n  {\n    id: 'audioFormat',\n    title: 'Format audio à convertir',\n    badge: 'Auto',\n    bucket: 'fix',\n    icon: 'wrench',\n    action: 'On reconvertit en MP3 mono 44,1 kHz.',\n    match: isAudioFormatIssue,\n  },\n  {\n    id: 'image',\n    title: 'Image à corriger',\n    badge: 'Auto',\n    bucket: 'fix',\n    icon: 'image',\n    action: 'On convertit ou redimensionne en 320×240.',\n    match: (issue) => issue.autoFixAvailable && issue.category === 'image',\n  },\n  {\n    id: 'title',\n    title: 'Nom du pack à corriger',\n    badge: 'Assisté',\n    bucket: 'fix',\n    icon: 'file',\n    action: 'Les métadonnées du pack demandent une correction.',\n    match: (issue) => issue.category === 'title',\n  },\n  {\n    id: 'structure',\n    title: 'Structure à vérifier',\n    badge: 'Manuel',\n    bucket: 'listen',\n    icon: 'network',\n    action: 'Vérifie la navigation ou les fichiers référencés.',\n    match: (issue) => issue.category === 'structure',\n  },\n];\n\nfunction buildProblemGroups(report) {\n  if (!report) return [];\n  const byFile = issuesByFilePath(report);\n  const files = itemMap(report);\n  const used = new Set();\n  const relevantIssues = (report.issues || []).filter((issue) => (\n    issue.severity === 'error' || issue.severity === 'warning' || isOptionalSilenceIssue(issue)\n  ));\n\n  return PROBLEM_SECTIONS.map((section) => {\n    const records = [];\n    const seen = new Set();\n    for (const issue of relevantIssues) {\n      if (used.has(issue) || !section.match(issue)) continue;\n      used.add(issue);\n      const key = section.id === 'optionalSilence'\n        ? `${uniqueIssueKey(issue)}:${issue.code}`\n        : uniqueIssueKey(issue);\n      if (seen.has(key)) continue;\n      seen.add(key);\n      const fileIssues = issue.filePath ? (byFile.get(issue.filePath) || [issue]) : [issue];\n      const fileEntry = issue.filePath ? files.get(issue.filePath) : null;\n      records.push({\n        id: `${section.id}:${key}`,\n        issue,\n        issues: fileIssues,\n        sectionIssues: fileIssues.filter((candidate) => section.match(candidate)),\n        item: fileEntry?.item || null,\n        kind: fileEntry?.kind || issue.category,\n      });\n    }\n    return {\n      ...section,\n      records,\n      count: records.length,\n      fixCount: section.id === 'title'\n        ? records.length\n        : records.reduce((sum, record) => sum + automaticCorrectionCount(record), 0),\n      optionalCount: section.id === 'optionalSilence' ? records.length : 0,\n    };\n  }).filter((group) => group.count > 0);\n}\n\nfunction recordProblemSummary(record) {\n  const scopedIssues = record.sectionIssues?.length ? record.sectionIssues : [record.issue];\n  if (record.kind === 'audio') {\n    if (scopedIssues.some((issue) => isSaturatedIssue(issue))) {\n      const peak = record.item?.truePeakDb;\n      return typeof peak === 'number' ? `Saturé · crête ${formatPeak(peak)}` : 'Saturé (source)';\n    }\n    const silenceIssues = scopedIssues.filter((issue) => (issueHasMeasure(issue, 'silenceStart') || issueHasMeasure(issue, 'silenceEnd')));\n    if (silenceIssues.length > 0) {\n      const parts = silenceSummaryParts(silenceIssues, record.item);\n      if (parts.length > 0) return parts.join(' | ');\n    }\n    if (scopedIssues.some((issue) => (issueHasMeasure(issue, 'volume') && issue.code !== 'CHECKER_AUDIO_NEAR_MUTE'))) {\n      const lufs = record.item?.integratedLufs;\n      const direction = typeof lufs === 'number' && lufs > -10 ? 'trop haut' : 'trop bas';\n      return `Niveau sonore ${direction} (${formatLufs(lufs)})`;\n    }\n  }\n  if (record.kind === 'image') {\n    return scopedIssues.map((issue) => measuredIssueSummary(issue, record.item, record.kind)).filter(Boolean).join(' · ');\n  }\n  return scopedIssues.map((issue) => measuredIssueSummary(issue, record.item, record.kind)).filter(Boolean).join(' · ');\n}\n\nfunction saturatedFileCount(groups) {\n  return groups\n    .filter((group) => group.id === 'quality')\n    .reduce((sum, group) => sum + group.count, 0);\n}\n\nfunction summarizeGroups(groups, report) {\n  const listenCount = groups\n    .filter((group) => group.bucket === 'listen')\n    .reduce((sum, group) => sum + group.count, 0);\n  const fixCount = groups\n    .filter((group) => group.bucket === 'fix')\n    .reduce((sum, group) => sum + group.fixCount, 0);\n  const optionalCount = groups\n    .filter((group) => group.bucket === 'optional')\n    .reduce((sum, group) => sum + group.optionalCount, 0);\n  const saturatedCount = saturatedFileCount(groups);\n  const hasBlocking = report?.verdict === 'invalid' || groups.some((group) => (\n    group.bucket === 'listen' && group.records.some((record) => record.issue.severity === 'error')\n  ));\n\n  if (!groups.length) {\n    return {\n      tone: 'ok',\n      icon: 'check',\n      title: 'Pack conforme',\n      subtitle: 'Aucun problème automatique ou manuel détecté.',\n      listenCount,\n      fixCount,\n      optionalCount,\n    };\n  }\n  if (hasBlocking) {\n    return {\n      tone: 'listen',\n      icon: 'warning',\n      title: 'Pack à vérifier avant export',\n      subtitle: 'Certains points demandent une vérification manuelle.',\n      listenCount,\n      fixCount,\n      optionalCount,\n    };\n  }\n  if (saturatedCount > 0) {\n    return {\n      tone: 'quality',\n      icon: 'warning',\n      title: fixCount > 0 ? 'Pack corrigeable, mais audio déjà saturé' : 'Audio déjà saturé',\n      subtitle: fixCount > 0\n        ? \"Le reste sera corrigé ; l'audio saturé doit être repris depuis une source propre.\"\n        : 'Nous conseillons de refaire le pack depuis une source audio propre.',\n      listenCount,\n      fixCount,\n      optionalCount,\n    };\n  }\n  if (listenCount > 0) {\n    return {\n      tone: 'listen',\n      icon: 'info',\n      title: listenCount === 1\n        ? 'Pack corrigeable, avec un fichier à écouter'\n        : `Pack corrigeable, avec ${listenCount} fichiers à écouter`,\n      subtitle: 'Le reste peut être corrigé automatiquement.',\n      listenCount,\n      fixCount,\n      optionalCount,\n    };\n  }\n  if (fixCount === 0 && listenCount === 0 && optionalCount > 0) {\n    return {\n      tone: 'ok',\n      icon: 'check',\n      title: `Pack conforme, avec ${optionalCount} ajustement${optionalCount > 1 ? 's' : ''} facultatif${optionalCount > 1 ? 's' : ''}`,\n      subtitle: 'Les pauses longues peuvent être conservées telles quelles.',\n      listenCount,\n      fixCount,\n      optionalCount,\n    };\n  }\n  return {\n    tone: 'fix',\n    icon: 'wrench',\n    title: 'Pack corrigeable en un clic',\n    subtitle: 'Aucun point manuel détecté.',\n    listenCount,\n    fixCount,\n    optionalCount,\n  };\n}\n\nfunction fileSummary(kind, item) {\n  if (kind === 'audio') {\n    return `Silence ${formatSeconds(item?.leadingSilenceSecs)} / ${formatSeconds(item?.trailingSilenceSecs)} · ${formatLufs(item?.integratedLufs)}`;\n  }\n  const dimensions = item?.width && item?.height ? `${item.width}×${item.height}` : 'dimensions ?';\n  return `${dimensions} · ${item?.format || 'format ?'}`;\n}\n\nfunction roleLabel(kind) {\n  if (kind === 'audio') return 'Audio';\n  if (kind === 'image') return 'Image';\n  return 'Fichier';\n}\n\nfunction measureRowsHtml(rows, badKeys = new Set(), infoKeys = new Set()) {\n  return rows.map((row) => {\n    const status = infoKeys.has(row.key) ? 'info' : (badKeys.has(row.key) ? 'bad' : 'ok');\n    return html`<div class=\"measure measure--${status}\">\n      <span>${icon(status === 'bad' ? 'warning' : (status === 'info' ? 'info' : 'check'))}${escapeHtml(row.label)}</span>\n      <strong>${escapeHtml(row.value)}</strong>\n    </div>`;\n  }).join('');\n}\n\nfunction recordDetailHtml(record) {\n  const item = record.item;\n  let rows = [];\n  if (record.kind === 'audio') rows = audioMeasureRows(item);\n  else if (record.kind === 'image') rows = [...imageMeasureRows(item), { key: 'expected', label: 'Attendu', value: '320×240' }];\n  else rows = [{ key: 'category', label: 'Catégorie', value: record.issue.category || 'Info' }];\n  const scopedIssues = record.sectionIssues?.length ? record.sectionIssues : record.issues;\n  const flaggedKeys = new Set(rows.filter((row) => hasMeasureIssue(scopedIssues, row.key)).map((row) => row.key));\n  const optional = record.issue.fixDisposition === 'optional';\n  const badKeys = optional ? new Set() : flaggedKeys;\n  const infoKeys = optional ? flaggedKeys : new Set();\n  return html`<div class=\"tech-detail\">\n    <div>\n      <div class=\"tech-title\">Mesures</div>\n      ${measureRowsHtml(rows, badKeys, infoKeys)}\n    </div>\n    <div>\n      <div class=\"tech-title\">Ce qui est proposé</div>\n      ${(record.sectionIssues?.length ? record.sectionIssues : record.issues).map((issue) => html`<div class=\"tech-action\">\n        ${icon(issue.autoFixAvailable ? 'wrench' : 'info')}\n        <div>\n          <strong>${escapeHtml(issue.autoFixDescription || issue.message)}</strong>\n          ${issue.technicalDetails ? `<span>${escapeHtml(issue.technicalDetails)}</span>` : ''}\n        </div>\n      </div>`).join('')}\n    </div>\n  </div>`;\n}\n\nfunction problemGroupHtml(group, open = false) {\n  return html`<details class=\"group group--${group.bucket} group--${group.id}\" ${open ? 'open' : ''}>\n    <summary class=\"group-head\">\n      <span class=\"group-icon\">${icon(group.icon)}</span>\n      <span class=\"group-copy\">\n        <span class=\"group-title-row\">\n          <strong>${escapeHtml(group.title)}</strong>\n          <span class=\"group-badge\">${escapeHtml(group.badge)}</span>\n        </span>\n        <span>${escapeHtml(group.action)}</span>\n      </span>\n      <span class=\"group-count\"><strong>${group.count}</strong><small>${group.bucket === 'optional' ? (group.count > 1 ? 'suggestions' : 'suggestion') : (group.count > 1 ? 'fichiers' : 'fichier')}</small></span>\n    </summary>\n    <div class=\"group-body\">\n      <div class=\"mini-list\">\n        ${group.records.map((record) => {\n          const firstIssue = record.issue;\n          return html`<details class=\"mini-file\">\n            <summary class=\"mini-file-row\">\n              <span class=\"role\">${escapeHtml(roleLabel(record.kind))}</span>\n              <span class=\"mini-name\" title=\"${escapeHtml(firstIssue.filePath || firstIssue.label)}\">${escapeHtml(cleanLabel(firstIssue.label))}</span>\n              <span class=\"mini-problem\">${escapeHtml(recordProblemSummary(record))}</span>\n              <span class=\"mini-severity mini-severity--${escapeHtml(firstIssue.severity)}\">${escapeHtml(severityLabel(firstIssue.severity))}</span>\n            </summary>\n            ${recordDetailHtml(record)}\n          </details>`;\n        }).join('')}\n      </div>\n    </div>\n  </details>`;\n}\n\nfunction buildConformingGroups(report) {\n  if (!report) return [];\n  const groups = [];\n  const audioFiles = (report.audioItems || []).filter((item) => isConforming(item.status));\n  if (audioFiles.length) {\n    groups.push({\n      id: 'audio',\n      title: 'Audio conforme',\n      subtitle: 'Silence, volume, format et crête dans les clous.',\n      icon: 'audio',\n      mode: 'files',\n      kind: 'audio',\n      files: audioFiles,\n      metricStrong: String(audioFiles.length),\n      metricSmall: audioFiles.length > 1 ? 'fichiers' : 'fichier',\n    });\n  }\n  const imageFiles = (report.imageItems || []).filter((item) => isConforming(item.status));\n  if (imageFiles.length) {\n    groups.push({\n      id: 'image',\n      title: 'Images conformes',\n      subtitle: 'Dimensions et format conformes.',\n      icon: 'image',\n      mode: 'files',\n      kind: 'image',\n      files: imageFiles,\n      metricStrong: String(imageFiles.length),\n      metricSmall: imageFiles.length > 1 ? 'fichiers' : 'fichier',\n    });\n  }\n  if (titleConforming(report)) {\n    groups.push({\n      id: 'title',\n      title: 'Nom du pack',\n      subtitle: 'Nom et convention valides.',\n      icon: 'file',\n      mode: 'facts',\n      metricStrong: 'Valide',\n      metricSmall: 'Convention OK',\n      facts: [\n        { key: 'name', label: 'Nom', value: report.packName || '—' },\n        { key: 'title', label: 'Titre', value: report.packTitle || '—' },\n        { key: 'version', label: 'Version', value: String(report.packVersion ?? '—') },\n      ],\n    });\n  }\n  if (structureConforming(report)) {\n    const structure = report.structureSummary || {};\n    groups.push({\n      id: 'structure',\n      title: 'Structure',\n      subtitle: 'Navigation et références cohérentes.',\n      icon: 'network',\n      mode: 'facts',\n      metricStrong: 'Correcte',\n      metricSmall: `${structure.stageCount ?? 0} étapes`,\n      facts: [\n        { key: 'lunii', label: 'Compatible Lunii', value: structure.luniiCompatible ? 'Oui' : 'Non' },\n        { key: 'editable', label: 'Éditable Story Studio', value: structure.storyStudioEditable ? 'Oui' : 'Non' },\n        { key: 'stories', label: 'Histoires', value: String(structure.storyCount ?? 0) },\n        { key: 'stages', label: 'Étapes', value: String(structure.stageCount ?? 0) },\n        { key: 'actions', label: 'Listes de choix', value: String(structure.actionCount ?? 0) },\n        { key: 'refAudio', label: 'Audios référencés', value: String(structure.referencedAudioCount ?? 0) },\n        { key: 'refImage', label: 'Images référencées', value: String(structure.referencedImageCount ?? 0) },\n      ],\n    });\n  }\n  const nightDetected = Boolean(report.nightMode?.detected);\n  groups.push({\n    id: 'night',\n    title: 'Mode nuit',\n    subtitle: nightDetected ? 'Piste nuit détectée dans le pack.' : 'Aucune piste nuit (non requis).',\n    icon: 'moon',\n    mode: 'facts',\n    metricStrong: nightDetected ? 'Disponible' : 'Absent',\n    metricSmall: 'Non bloquant',\n    facts: [\n      { key: 'detected', label: 'Mode nuit', value: nightDetected ? 'Disponible' : 'Absent' },\n      { key: 'blocking', label: 'Bloquant', value: 'Non' },\n    ],\n  });\n  return groups;\n}\n\nfunction conformingGroupHtml(group, open = false) {\n  return html`<details class=\"group group--ok group--${group.id}\" ${open ? 'open' : ''}>\n    <summary class=\"group-head\">\n      <span class=\"group-icon\">${icon(group.icon)}</span>\n      <span class=\"group-copy\">\n        <span class=\"group-title-row\">\n          <strong>${escapeHtml(group.title)}</strong>\n          <span class=\"group-badge\">Conforme</span>\n        </span>\n        <span>${escapeHtml(group.subtitle)}</span>\n      </span>\n      <span class=\"group-count\"><strong>${escapeHtml(group.metricStrong)}</strong><small>${escapeHtml(group.metricSmall)}</small></span>\n    </summary>\n    <div class=\"group-body\">\n      ${group.mode === 'files' ? html`<div class=\"mini-list\">\n        ${group.files.map((item) => {\n          const rows = group.kind === 'audio'\n            ? audioMeasureRows(item)\n            : [...imageMeasureRows(item), { key: 'expected', label: 'Attendu', value: expectedImageOk(item) ? '320×240' : '320×240' }];\n          return html`<details class=\"mini-file\">\n            <summary class=\"mini-file-row\">\n              <span class=\"role\">${escapeHtml(roleLabel(group.kind))}</span>\n              <span class=\"mini-name\" title=\"${escapeHtml(item.filePath || item.label)}\">${escapeHtml(cleanLabel(item.label))}</span>\n              <span class=\"mini-problem\">${escapeHtml(fileSummary(group.kind, item))}</span>\n              <span class=\"mini-severity mini-severity--ok\">OK</span>\n            </summary>\n            <div class=\"tech-detail tech-detail--facts\">\n              <div>\n                <div class=\"tech-title\">Mesures</div>\n                ${measureRowsHtml(rows)}\n              </div>\n            </div>\n          </details>`;\n        }).join('')}\n      </div>` : html`<div class=\"tech-detail tech-detail--facts\">\n        <div>\n          <div class=\"tech-title\">Détails</div>\n          ${measureRowsHtml(group.facts)}\n        </div>\n      </div>`}\n    </div>\n  </details>`;\n}\n\nfunction summaryTileHtml({ title, iconName, tone, strong, small, split }) {\n  return html`<div class=\"summary-tile summary-tile--${tone}\">\n    <div class=\"summary-head\">${icon(iconName)}<span>${escapeHtml(title)}</span></div>\n    ${split ? html`<div class=\"split-stat\">\n      <span class=\"split-ok\"><strong>${split.ok}</strong> OK</span>\n      <span class=\"split-fix ${split.needsFix === 0 ? 'is-clean' : ''}\"><strong>${split.needsFix}</strong> à corriger</span>\n    </div>` : html`<div class=\"single-stat\"><strong>${escapeHtml(strong)}</strong><span>${escapeHtml(small)}</span></div>`}\n  </div>`;\n}\n\nfunction reportStyles() {\n  return `\n    :root {\n      color-scheme: light;\n      --bg0: #f3f6fb;\n      --bg1: #ffffff;\n      --bg2: #f7f9fc;\n      --bg3: #edf2f7;\n      --text: #1f2430;\n      --muted: #748095;\n      --border: #dfe6ef;\n      --borderLt: #cfd8e7;\n      --success-bg: #e8f7ee;\n      --success-border: #76c795;\n      --success-text: #21824b;\n      --warning-bg: #fff5d8;\n      --warning-border: #e3b84a;\n      --warning-text: #9a6b00;\n      --danger-bg: #ffe9e9;\n      --danger-border: #f19a9a;\n      --danger-text: #b03636;\n      --listen-bg: #efedff;\n      --listen-border: #aaa3f2;\n      --listen-text: #6157cf;\n      --font: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, \"Segoe UI\", sans-serif;\n      --mono: \"SFMono-Regular\", Consolas, \"Liberation Mono\", monospace;\n    }\n    * { box-sizing: border-box; }\n    body {\n      margin: 0;\n      background: linear-gradient(180deg, #edf1f7 0, #f8fafc 280px);\n      color: var(--text);\n      font-family: var(--font);\n      font-size: 13px;\n      line-height: 1.45;\n    }\n    svg {\n      width: 18px;\n      height: 18px;\n      fill: none;\n      stroke: currentColor;\n      stroke-linecap: round;\n      stroke-linejoin: round;\n      stroke-width: 2;\n    }\n    .document {\n      width: min(1040px, calc(100vw - 32px));\n      margin: 24px auto 36px;\n      overflow: hidden;\n      border: 1px solid var(--borderLt);\n      border-radius: 12px;\n      background: var(--bg1);\n      box-shadow: 0 24px 70px rgba(37, 45, 64, 0.15);\n    }\n    .modal-header {\n      display: flex;\n      align-items: center;\n      justify-content: space-between;\n      gap: 12px;\n      padding: 16px 18px;\n      border-bottom: 1px solid var(--border);\n    }\n    .modal-title {\n      display: flex;\n      align-items: center;\n      gap: 12px;\n      min-width: 0;\n    }\n    .drop-icon,\n    .report-orb,\n    .group-icon {\n      display: grid;\n      place-items: center;\n      flex: 0 0 auto;\n      border: 1px solid #9b8fec;\n      border-radius: 9px;\n      background: #efeaff;\n      color: #695bd6;\n    }\n    .drop-icon { width: 34px; height: 34px; }\n    .modal-title strong { display: block; font-size: 14px; font-weight: 750; }\n    .modal-title span {\n      display: block;\n      max-width: 760px;\n      overflow: hidden;\n      color: var(--muted);\n      font-family: var(--mono);\n      font-size: 11px;\n      text-overflow: ellipsis;\n      white-space: nowrap;\n    }\n    .print-button {\n      flex: 0 0 auto;\n      padding: 7px 12px;\n      border: 1px solid var(--borderLt);\n      border-radius: 8px;\n      background: var(--bg2);\n      color: var(--text);\n      cursor: pointer;\n      font: inherit;\n      font-size: 12px;\n      font-weight: 650;\n    }\n    .print-button:hover { border-color: #9b8fec; background: #f1edff; }\n    .report { display: flex; flex-direction: column; min-width: 0; }\n    .report-verdict {\n      display: flex;\n      align-items: center;\n      gap: 12px;\n      min-width: 0;\n      padding: 16px 18px;\n      border-bottom: 1px solid var(--border);\n    }\n    .report-verdict--ok .report-orb { background: var(--success-bg); border-color: var(--success-border); color: var(--success-text); }\n    .report-verdict--fix .report-orb { background: var(--warning-bg); border-color: var(--warning-border); color: var(--warning-text); }\n    .report-verdict--listen .report-orb { background: var(--listen-bg); border-color: var(--listen-border); color: var(--listen-text); }\n    .report-verdict--quality .report-orb { background: var(--danger-bg); border-color: var(--danger-border); color: var(--danger-text); }\n    .report-orb { width: 40px; height: 40px; border-radius: 999px; }\n    .report-copy { display: flex; flex: 1 1 auto; flex-direction: column; gap: 2px; min-width: 0; }\n    .pack-name {\n      overflow: hidden;\n      color: var(--muted);\n      font-family: var(--mono);\n      font-size: 10px;\n      text-overflow: ellipsis;\n      white-space: nowrap;\n    }\n    .report-copy strong { font-size: 16px; line-height: 1.15; }\n    .report-copy span:not(.pack-name) { color: var(--muted); font-size: 12px; }\n    .report-callout {\n      display: flex;\n      align-items: center;\n      gap: 7px;\n      flex: 0 0 auto;\n      padding: 7px 12px;\n      border: 1px solid var(--listen-border);\n      border-radius: 8px;\n      background: var(--listen-bg);\n      font-size: 12px;\n    }\n    .report-callout svg { color: var(--listen-text); }\n    .summary-tiles {\n      display: grid;\n      grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));\n      gap: 10px;\n      padding: 14px 18px 0;\n    }\n    .summary-tile {\n      min-width: 0;\n      padding: 10px;\n      border: 1px solid var(--border);\n      border-radius: 10px;\n      background: var(--bg2);\n    }\n    .summary-tile--ok { border-color: var(--success-border); background: var(--success-bg); }\n    .summary-tile--fix { border-color: var(--warning-border); background: var(--warning-bg); }\n    .summary-tile--listen { border-color: var(--listen-border); background: var(--listen-bg); }\n    .summary-tile--danger { border-color: var(--danger-border); background: var(--danger-bg); }\n    .summary-head {\n      display: flex;\n      align-items: center;\n      gap: 7px;\n      font-size: 11px;\n      font-weight: 750;\n    }\n    .summary-head svg { width: 15px; height: 15px; }\n    .summary-tile--ok .summary-head { color: var(--success-text); }\n    .summary-tile--fix .summary-head { color: var(--warning-text); }\n    .summary-tile--listen .summary-head { color: var(--listen-text); }\n    .summary-tile--danger .summary-head { color: var(--danger-text); }\n    .split-stat {\n      display: grid;\n      grid-template-columns: 1fr 1fr;\n      gap: 6px;\n      margin-top: 8px;\n    }\n    .split-stat span,\n    .single-stat {\n      min-width: 0;\n      padding: 7px 8px;\n      border-radius: 8px;\n      background: rgba(255, 255, 255, 0.58);\n      color: var(--muted);\n      font-size: 10px;\n      line-height: 1.2;\n    }\n    .split-stat strong,\n    .single-stat strong {\n      color: var(--text);\n      font-family: var(--mono);\n      font-size: 15px;\n      line-height: 1;\n    }\n    .split-ok strong,\n    .split-fix.is-clean strong { color: var(--success-text); }\n    .split-fix strong { color: var(--warning-text); }\n    .single-stat {\n      display: flex;\n      align-items: baseline;\n      justify-content: space-between;\n      gap: 8px;\n      margin-top: 8px;\n    }\n    .single-stat span {\n      min-width: 0;\n      overflow: hidden;\n      font-size: 10px;\n      text-overflow: ellipsis;\n      white-space: nowrap;\n    }\n    .empty,\n    .section-head {\n      display: flex;\n      align-items: center;\n      gap: 8px;\n      margin: 14px 18px 0;\n      color: var(--success-text);\n      font-size: 12px;\n      font-weight: 750;\n    }\n    .empty {\n      padding: 10px 12px;\n      border-radius: 8px;\n      background: var(--bg2);\n      font-weight: 500;\n    }\n    .groups {\n      display: flex;\n      flex-direction: column;\n      gap: 10px;\n      padding: 14px 18px;\n    }\n    .group {\n      overflow: hidden;\n      border: 1px solid var(--border);\n      border-radius: 10px;\n      background: var(--bg1);\n      page-break-inside: avoid;\n    }\n    .group[open] { background: var(--bg2); }\n    .group--fix[open] { border-color: var(--warning-border); }\n    .group--listen[open] { border-color: var(--listen-border); }\n    .group--quality[open] { border-color: var(--danger-border); }\n    .group--optional[open] { border-color: var(--success-border); }\n    .group--ok[open] { border-color: var(--success-border); }\n    .group-head {\n      display: flex;\n      align-items: center;\n      gap: 13px;\n      min-width: 0;\n      padding: 13px 14px;\n      cursor: pointer;\n      list-style: none;\n    }\n    .group-head::-webkit-details-marker,\n    .mini-file-row::-webkit-details-marker { display: none; }\n    .group-icon { width: 40px; height: 40px; border-radius: 10px; }\n    .group--listen .group-icon,\n    .group--listen .group-badge { background: var(--listen-bg); color: var(--listen-text); border-color: var(--listen-border); }\n    .group--fix .group-icon,\n    .group--fix .group-badge { background: var(--warning-bg); color: var(--warning-text); border-color: var(--warning-border); }\n    .group--quality .group-icon,\n    .group--quality .group-badge { background: var(--danger-bg); color: var(--danger-text); border-color: var(--danger-border); }\n    .group--optional .group-icon,\n    .group--optional .group-badge { background: var(--success-bg); color: var(--success-text); border-color: var(--success-border); }\n    .group--ok .group-icon,\n    .group--ok .group-badge { background: var(--success-bg); color: var(--success-text); border-color: var(--success-border); }\n    .group-copy {\n      display: flex;\n      flex: 1 1 auto;\n      flex-direction: column;\n      gap: 3px;\n      min-width: 0;\n    }\n    .group-title-row {\n      display: flex;\n      align-items: center;\n      gap: 8px;\n      min-width: 0;\n    }\n    .group-title-row strong {\n      overflow: hidden;\n      font-size: 14px;\n      font-weight: 750;\n      text-overflow: ellipsis;\n      white-space: nowrap;\n    }\n    .group-title-row + span { color: var(--muted); font-size: 12px; line-height: 1.35; }\n    .group-badge {\n      display: inline-flex;\n      align-items: center;\n      min-height: 20px;\n      padding: 0 8px;\n      border: 1px solid;\n      border-radius: 999px;\n      font-size: 10px;\n      font-weight: 750;\n      white-space: nowrap;\n    }\n    .group-count {\n      display: flex;\n      align-items: flex-end;\n      flex: 0 0 auto;\n      flex-direction: column;\n      gap: 1px;\n      min-width: 54px;\n    }\n    .group-count strong { font-family: var(--mono); font-size: 22px; line-height: 1; }\n    .group--fix .group-count strong { color: var(--warning-text); }\n    .group--listen .group-count strong { color: var(--listen-text); }\n    .group--quality .group-count strong { color: var(--danger-text); }\n    .group--optional .group-count strong { color: var(--success-text); }\n    .group--ok .group-count strong { color: var(--success-text); }\n    .group-count small { color: var(--muted); font-size: 10px; }\n    .group-body { padding: 0 14px 12px; }\n    .mini-file { border-top: 1px solid var(--border); }\n    .mini-file-row {\n      display: flex;\n      align-items: center;\n      gap: 10px;\n      width: 100%;\n      min-width: 0;\n      padding: 8px 4px;\n      cursor: pointer;\n      list-style: none;\n    }\n    .role {\n      flex: 0 0 auto;\n      padding: 2px 5px;\n      border-radius: 4px;\n      background: var(--bg3);\n      color: var(--muted);\n      font-size: 9px;\n      font-weight: 750;\n      text-transform: uppercase;\n    }\n    .mini-name {\n      flex: 1 1 34%;\n      min-width: 0;\n      overflow: hidden;\n      font-size: 12px;\n      font-weight: 650;\n      text-overflow: ellipsis;\n      white-space: nowrap;\n    }\n    .mini-problem {\n      flex: 1.2 1 42%;\n      min-width: 150px;\n      overflow: hidden;\n      color: var(--muted);\n      font-size: 11px;\n      line-height: 1.25;\n      text-overflow: ellipsis;\n      white-space: nowrap;\n    }\n    .mini-severity {\n      flex: 0 0 auto;\n      color: var(--muted);\n      font-size: 10px;\n      font-weight: 750;\n    }\n    .mini-severity--error { color: var(--danger-text); }\n    .mini-severity--warning { color: var(--warning-text); }\n    .mini-severity--ok { color: var(--success-text); }\n    .tech-detail {\n      display: grid;\n      grid-template-columns: repeat(2, minmax(0, 1fr));\n      gap: 2px 28px;\n      margin: 2px 0 12px;\n      padding: 10px 12px;\n      border: 1px solid var(--border);\n      border-radius: 8px;\n      background: var(--bg1);\n    }\n    .tech-detail--facts { grid-template-columns: 1fr; }\n    .tech-title {\n      margin-bottom: 4px;\n      color: var(--muted);\n      font-size: 10px;\n      font-weight: 750;\n      text-transform: uppercase;\n    }\n    .measure {\n      display: flex;\n      align-items: baseline;\n      justify-content: space-between;\n      gap: 10px;\n      padding: 4px 0;\n      border-bottom: 1px solid var(--border);\n    }\n    .measure span {\n      display: inline-flex;\n      align-items: center;\n      gap: 6px;\n      color: var(--muted);\n      font-size: 11px;\n    }\n    .measure svg { width: 12px; height: 12px; }\n    .measure--ok svg { color: var(--success-text); }\n    .measure--bad svg { color: var(--danger-text); }\n    .measure--info svg { color: var(--success-text); }\n    .measure strong {\n      font-family: var(--mono);\n      font-size: 11px;\n      font-weight: 650;\n    }\n    .tech-action {\n      display: flex;\n      gap: 8px;\n      padding: 5px 0;\n      border-bottom: 1px solid var(--border);\n    }\n    .tech-action svg {\n      width: 14px;\n      height: 14px;\n      margin-top: 1px;\n      color: #695bd6;\n    }\n    .tech-action div {\n      display: flex;\n      flex-direction: column;\n      gap: 2px;\n      min-width: 0;\n    }\n    .tech-action strong { font-size: 12px; font-weight: 650; }\n    .tech-action span { color: var(--muted); font-size: 10px; line-height: 1.35; }\n    .technical-log {\n      margin: 0 18px 18px;\n      overflow: hidden;\n      border: 1px solid var(--border);\n      border-radius: 8px;\n      background: var(--bg2);\n    }\n    .technical-log summary {\n      padding: 9px 10px;\n      cursor: pointer;\n      font-size: 12px;\n      font-weight: 750;\n    }\n    .technical-log pre {\n      max-height: 360px;\n      margin: 0;\n      padding: 10px;\n      overflow: auto;\n      border-top: 1px solid var(--border);\n      color: #3e495b;\n      font-family: var(--mono);\n      font-size: 10px;\n      line-height: 1.45;\n      white-space: pre-wrap;\n    }\n    @media (max-width: 720px) {\n      .document { width: 100%; margin: 0; border-radius: 0; }\n      .modal-header,\n      .report-verdict { align-items: stretch; flex-direction: column; }\n      .modal-title span { max-width: 100%; }\n      .summary-tiles { grid-template-columns: repeat(2, minmax(0, 1fr)); }\n      .report-callout { width: fit-content; }\n      .group-head { align-items: flex-start; }\n      .mini-file-row { align-items: flex-start; flex-wrap: wrap; }\n      .mini-problem { order: 3; flex-basis: 100%; min-width: 0; }\n      .tech-detail { grid-template-columns: minmax(0, 1fr); }\n    }\n    @media (max-width: 480px) {\n      .summary-tiles { grid-template-columns: minmax(0, 1fr); }\n    }\n    @media print {\n      body { background: #fff; }\n      .document {\n        width: 100%;\n        margin: 0;\n        border: 0;\n        border-radius: 0;\n        box-shadow: none;\n      }\n      .print-button { display: none; }\n      .technical-log pre { max-height: none; }\n      details { break-inside: avoid; }\n      details:not([open]) > *:not(summary) { display: block; }\n    }\n  `;\n}\n\nexport function reportBaseName(report) {\n  return String(report?.packName || 'rapport-pack')\n    .replace(/\\.(zip|7z)$/i, '')\n    .replace(/[<>:\"/\\\\|?*\\[\\]+]/g, '_')\n    .trim() || 'rapport-pack';\n}\n\nexport function formatTechnicalLog(report) {\n  report = presentCheckerReport(report);\n  return (report?.technicalLog || []).join('\\n');\n}\n\nexport function formatDiagnosticJson(report) {\n  return JSON.stringify(presentCheckerReport(report), null, 2);\n}\n\nexport function formatHtmlReport(report) {\n  report = presentCheckerReport(report);\n  if (!report) return '';\n  const groups = buildProblemGroups(report);\n  const summary = summarizeGroups(groups, report);\n  const correctionCounts = packCorrectionCounts(report);\n  const saturatedCount = saturatedFileCount(groups);\n  const conformingGroups = buildConformingGroups(report);\n  const audio = categoryConformanceStats(report.audioSummary);\n  const images = categoryConformanceStats(report.imageSummary);\n  const title = categoryConformanceStats(report.titleSummary);\n  const titleOk = title.total > 0 && title.needsFix === 0;\n  const structureOk = report.structureSummary?.luniiCompatible && report.structureSummary?.storyStudioEditable;\n  const nightMode = Boolean(report.nightMode?.detected);\n  const generatedAt = new Date().toLocaleString(getIntlLocale());\n  const titleText = `Rapport - ${report.packName || 'Pack'}`;\n\n  return html`<!doctype html>\n<html lang=\"fr\">\n<head>\n  <meta charset=\"utf-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>${escapeHtml(titleText)}</title>\n  <style>${reportStyles()}</style>\n</head>\n<body>\n  <main class=\"document\">\n    <header class=\"modal-header\">\n      <div class=\"modal-title\">\n        <span class=\"drop-icon\">${icon('package')}</span>\n        <div>\n          <strong>Vérifier un pack</strong>\n          <span title=\"${escapeHtml(report.packName || '')}\">${escapeHtml(report.packName || 'Pack analysé')} · ${escapeHtml(generatedAt)}</span>\n        </div>\n      </div>\n      <button class=\"print-button\" type=\"button\" onclick=\"window.print()\">Imprimer / PDF</button>\n    </header>\n    <section class=\"report\" aria-label=\"Rapport de vérification du pack\">\n      <div class=\"report-verdict report-verdict--${summary.tone}\">\n        <span class=\"report-orb\">${icon(summary.icon)}</span>\n        <div class=\"report-copy\">\n          <span class=\"pack-name\">${escapeHtml(report.packName || 'Pack analysé')}</span>\n          <strong>${escapeHtml(summary.title)}</strong>\n          <span>${escapeHtml(summary.subtitle)}</span>\n        </div>\n        <div class=\"report-callout\">\n          ${icon('info')}\n          <span><strong>${summary.listenCount}</strong> à écouter · <strong>${correctionCounts.automatic}</strong> automatiques · <strong>${correctionCounts.optional}</strong> facultatives</span>\n        </div>\n      </div>\n      <div class=\"summary-tiles\" aria-label=\"Résumé du pack\">\n        ${summaryTileHtml({\n          title: 'Audio',\n          iconName: 'audio',\n          tone: saturatedCount > 0 ? 'danger' : (audio.needsFix > 0 ? 'fix' : 'ok'),\n          split: audio,\n        })}\n        ${summaryTileHtml({\n          title: 'Images',\n          iconName: 'image',\n          tone: images.needsFix ? 'fix' : 'ok',\n          split: images,\n        })}\n        ${summaryTileHtml({\n          title: 'Nom du pack',\n          iconName: 'file',\n          tone: titleOk ? 'ok' : 'fix',\n          strong: titleOk ? 'Valide' : 'À corriger',\n          small: titleOk ? 'Convention OK' : 'Métadonnées',\n        })}\n        ${summaryTileHtml({\n          title: 'Structure',\n          iconName: 'network',\n          tone: structureOk ? 'ok' : 'listen',\n          strong: structureOk ? 'Correcte' : 'Vérification manuelle',\n          small: `${report.structureSummary?.stageCount ?? 0} étapes`,\n        })}\n        ${summaryTileHtml({\n          title: 'Mode nuit',\n          iconName: 'moon',\n          tone: nightMode ? 'ok' : 'neutral',\n          strong: nightMode ? 'Disponible' : 'Absent',\n          small: nightMode ? 'Détecté dans le pack' : 'Non bloquant',\n        })}\n      </div>\n      ${groups.length === 0 ? html`<div class=\"empty\">${icon('check')}Tout est conforme dans ce rapport.</div>` : html`<div class=\"groups\">\n        ${groups.map((group, index) => problemGroupHtml(group, index === 0)).join('')}\n      </div>`}\n      ${conformingGroups.length ? html`<div class=\"section-head\">${icon('check')}Ce qui est conforme</div>\n      <div class=\"groups\">\n        ${conformingGroups.map((group, index) => conformingGroupHtml(group, groups.length === 0 && index === 0)).join('')}\n      </div>` : ''}\n      <details class=\"technical-log\">\n        <summary>Journal technique</summary>\n        <pre>${escapeHtml(formatTechnicalLog(report))}</pre>\n      </details>\n    </section>\n  </main>\n</body>\n</html>`;\n}\n\nexport function formatReadableReport(report) {\n  report = presentCheckerReport(report);\n  if (!report) return '';\n  const lines = [];\n  lines.push(`# Vérification du pack`);\n  lines.push('');\n  lines.push(`Pack analysé : ${report.packName}`);\n  lines.push(`Verdict : ${verdictLabel(report.verdict)}`);\n  lines.push('');\n  lines.push(`- Erreurs : ${report.summary?.errors ?? 0}`);\n  lines.push(`- Avertissements : ${report.summary?.warnings ?? 0}`);\n  lines.push(`- Informations : ${report.summary?.infos ?? 0}`);\n  lines.push(`- Éléments conformes : ${report.summary?.ok ?? 0}`);\n  const correctionCounts = packCorrectionCounts(report);\n  lines.push(`- Corrections automatiques disponibles : ${correctionCounts.automatic}`);\n  lines.push(`- Suggestions facultatives : ${correctionCounts.optional}`);\n  lines.push('');\n  lines.push(`## Résumé`);\n  lines.push('');\n  const audio = categoryConformanceStats(report.audioSummary);\n  const images = categoryConformanceStats(report.imageSummary);\n  lines.push(`- Audio : ${audio.ok}/${audio.total} conformes`);\n  lines.push(`- Images : ${images.ok}/${images.total} conformes`);\n  lines.push(`- Structure Lunii : ${report.structureSummary?.luniiCompatible ? 'valide' : 'à corriger'}`);\n  lines.push(`- Édition Story Studio : ${report.structureSummary?.storyStudioEditable ? 'supportée' : 'non supportée ou à vérifier'}`);\n  lines.push(`- Mode nuit : ${report.nightMode?.detected ? 'détecté' : 'absent'}`);\n  lines.push('');\n  lines.push(`## Problèmes et points à vérifier`);\n  lines.push('');\n  const issues = report.issues || [];\n  if (issues.length === 0) {\n    lines.push('Aucun problème détecté.');\n  } else {\n    for (const issue of issues) {\n      lines.push(`- ${severityLabel(issue.severity)} · ${issue.label} : ${issue.message}`);\n      if (issue.filePath) lines.push(`  Fichier : ${issue.filePath}`);\n      if (issue.technicalDetails) lines.push(`  Détail : ${issue.technicalDetails}`);\n      if (issue.autoFixDescription) {\n        const prefix = isOptionalSilenceIssue(issue) ? 'Suggestion facultative' : 'Correction';\n        lines.push(`  ${prefix} : ${issue.autoFixDescription}`);\n      }\n    }\n  }\n  lines.push('');\n  lines.push(`## Ce qui est conforme`);\n  lines.push('');\n  const conformingAudio = (report.audioItems || []).filter((item) => isConforming(item.status));\n  if (conformingAudio.length) {\n    lines.push(`### Audio conforme (${conformingAudio.length})`);\n    for (const item of conformingAudio) {\n      const measures = audioMeasureRows(item).map((row) => `${row.label} : ${row.value}`).join(' · ');\n      lines.push(`- ${cleanLabel(item.label)} — ${measures}`);\n    }\n    lines.push('');\n  }\n  const conformingImages = (report.imageItems || []).filter((item) => isConforming(item.status));\n  if (conformingImages.length) {\n    lines.push(`### Images conformes (${conformingImages.length})`);\n    for (const item of conformingImages) {\n      const measures = imageMeasureRows(item).map((row) => `${row.label} : ${row.value}`).join(' · ');\n      lines.push(`- ${cleanLabel(item.label)} — ${measures}`);\n    }\n    lines.push('');\n  }\n  if (titleConforming(report)) {\n    lines.push(`### Nom du pack`);\n    lines.push(`- Nom : ${report.packName || '—'}`);\n    lines.push(`- Titre : ${report.packTitle || '—'}`);\n    lines.push(`- Version : ${report.packVersion ?? '—'}`);\n    lines.push('');\n  }\n  if (structureConforming(report)) {\n    const structure = report.structureSummary || {};\n    lines.push(`### Structure`);\n    lines.push(`- Compatible Lunii : ${structure.luniiCompatible ? 'oui' : 'non'}`);\n    lines.push(`- Éditable Story Studio : ${structure.storyStudioEditable ? 'oui' : 'non'}`);\n    lines.push(`- Histoires : ${structure.storyCount ?? 0}`);\n    lines.push(`- Étapes : ${structure.stageCount ?? 0}`);\n    lines.push(`- Listes de choix : ${structure.actionCount ?? 0}`);\n    lines.push(`- Audios référencés : ${structure.referencedAudioCount ?? 0}`);\n    lines.push(`- Images référencées : ${structure.referencedImageCount ?? 0}`);\n    lines.push('');\n  }\n  lines.push(`### Mode nuit`);\n  lines.push(`- Mode nuit : ${report.nightMode?.detected ? 'disponible' : 'absent'}`);\n  lines.push(`- Bloquant : non`);\n  lines.push('');\n  lines.push(`## Journal technique`);\n  lines.push('');\n  lines.push('```text');\n  lines.push(formatTechnicalLog(report));\n  lines.push('```');\n  return lines.join('\\n');\n}\n",
 "src/components/CommunityPackChecker/packCheckerFormat.js": "// Helpers purs (sans React) partages par l'UI du verificateur et l'export du\n// rapport : formatteurs de mesures, construction des lignes audio/image, et\n// predicats de conformite. Garde l'export texte independant de tout JSX.\n\nfunction formatNumber(value, digits = 1) {\n  return typeof value === 'number' ? value.toFixed(digits).replace('.', ',') : null;\n}\n\nexport function formatSeconds(value) {\n  const formatted = formatNumber(value, 2);\n  return formatted ? `${formatted} s` : 'Non mesuré';\n}\n\nexport function formatLufs(value) {\n  const formatted = formatNumber(value, 1);\n  return formatted ? `${formatted} LUFS` : 'Non mesuré';\n}\n\nexport function formatPeak(value) {\n  const formatted = formatNumber(value, 1);\n  return formatted ? `${formatted} dBTP` : 'Non mesuré';\n}\n\nexport function cleanLabel(label) {\n  return (label || 'Fichier')\n    .replace(/\\.mp3 (item|Stage node)$/i, '')\n    .replace(/\\.png$/i, '')\n    .replace(/ node$/i, '');\n}\n\nexport function expectedImageOk(item) {\n  return item?.width === 320 && item?.height === 240;\n}\n\n// Lignes de mesure audio. Les `key` servent aussi, cote problemes, a reperer\n// quelle mesure est en defaut (voir hasMeasureIssue).\nexport function audioMeasureRows(item) {\n  return [\n    { key: 'format', label: 'Format', value: `${item?.codec || 'Inconnu'} · ${item?.channels || 'canaux ?'}` },\n    { key: 'sampleRate', label: 'Échantillonnage', value: item?.sampleRate ? `${formatNumber(item.sampleRate / 1000, 1)} kHz` : 'Non mesuré' },\n    { key: 'silenceStart', label: 'Silence début', value: formatSeconds(item?.leadingSilenceSecs) },\n    { key: 'silenceEnd', label: 'Silence fin', value: formatSeconds(item?.trailingSilenceSecs) },\n    { key: 'volume', label: 'Volume', value: formatLufs(item?.integratedLufs) },\n    { key: 'peak', label: 'Crête vraie', value: formatPeak(item?.truePeakDb) },\n  ];\n}\n\nexport function imageMeasureRows(item) {\n  return [\n    { key: 'dimensions', label: 'Dimensions', value: item?.width && item?.height ? `${item.width}×${item.height}` : 'Non mesuré' },\n    { key: 'imageFormat', label: 'Format', value: item?.format || 'Non mesuré' },\n  ];\n}\n\n// Un fichier est conforme s'il n'a ni erreur ni avertissement : complement\n// exact de ce qui apparait dans les cartes de problemes.\nexport function isConforming(status) {\n  return status !== 'error' && status !== 'warning';\n}\n\nexport function titleConforming(report) {\n  const total = report?.titleSummary?.total ?? 0;\n  const ok = report?.titleSummary?.ok ?? 0;\n  return total > 0 && total - ok === 0;\n}\n\nexport function structureConforming(report) {\n  return Boolean(report?.structureSummary?.luniiCompatible && report?.structureSummary?.storyStudioEditable);\n}\n",
 "src/components/CommunityPackChecker/packCheckerIssueClassification.js": "import { formatLufs, formatSeconds } from './packCheckerFormat.js';\nconst SILENCE_ISSUE_CODES = Object.freeze({\n  leadingShort: 'audioLeadingSilenceTooShort',\n  trailingShort: 'audioTrailingSilenceTooShort',\n  leadingLong: 'audioLeadingSilenceLong',\n  trailingLong: 'audioTrailingSilenceLong',\n});\n\nconst SHORT_CODES = new Set([\n  SILENCE_ISSUE_CODES.leadingShort,\n  SILENCE_ISSUE_CODES.trailingShort,\n]);\n\nconst LONG_CODES = new Set([\n  SILENCE_ISSUE_CODES.leadingLong,\n  SILENCE_ISSUE_CODES.trailingLong,\n]);\n\nexport function isAutomaticSilenceIssue(issue) {\n  return issue?.category === 'audio'\n    && issue?.fixDisposition === 'automatic'\n    && SHORT_CODES.has(issue?.code);\n}\n\nexport function isOptionalSilenceIssue(issue) {\n  return issue?.category === 'audio'\n    && issue?.severity === 'info'\n    && issue?.fixDisposition === 'optional'\n    && LONG_CODES.has(issue?.code);\n}\n\nexport function isAutomaticVolumeIssue(issue) {\n  return issue?.category === 'audio'\n    && issue?.autoFixAvailable === true\n    && ['CHECKER_AUDIO_VOLUME', 'CHECKER_AUDIO_NEAR_MUTE'].includes(issue?.code);\n}\n\nexport function silenceEdgeForIssue(issue) {\n  if (issue?.code === SILENCE_ISSUE_CODES.leadingShort || issue?.code === SILENCE_ISSUE_CODES.leadingLong) {\n    return 'leading';\n  }\n  if (issue?.code === SILENCE_ISSUE_CODES.trailingShort || issue?.code === SILENCE_ISSUE_CODES.trailingLong) {\n    return 'trailing';\n  }\n  return null;\n}\n\nexport function optionalSilenceIssues(report) {\n  return (report?.issues || []).filter(isOptionalSilenceIssue);\n}\n\nexport function optionalSilenceSelectionKey(issueOrSelection) {\n  const edge = issueOrSelection?.edge || silenceEdgeForIssue(issueOrSelection);\n  return edge && issueOrSelection?.filePath ? `${issueOrSelection.filePath}\\u0000${edge}` : '';\n}\n\nexport function serializeOptionalSilenceSelection(report, selectedKeys) {\n  const keys = selectedKeys instanceof Set ? selectedKeys : new Set(selectedKeys || []);\n  return optionalSilenceIssues(report)\n    .map((issue) => ({ filePath: issue.filePath, edge: silenceEdgeForIssue(issue) }))\n    .filter((selection) => keys.has(optionalSilenceSelectionKey(selection)));\n}\n\nexport function packCorrectionCounts(report) {\n  return {\n    automatic: report?.correctionsAvailable ?? 0,\n    optional: report?.optionalCorrectionsAvailable ?? optionalSilenceIssues(report).length,\n  };\n}\n\nexport function categoryConformanceStats(summary) {\n  const total = summary?.total ?? 0;\n  const conforming = Math.min(total, (summary?.ok ?? 0) + (summary?.infos ?? 0));\n  return {\n    total,\n    ok: conforming,\n    needsFix: Math.max(0, total - conforming),\n  };\n}\n\nexport function automaticCorrectionCount(record) {\n  const scopedIssues = record?.sectionIssues?.length\n    ? record.sectionIssues\n    : (record?.issues || []);\n  return scopedIssues.filter((issue) => issue.fixDisposition === 'automatic').length;\n}\n\nconst MEASURE_CODES = {\n  format: ['CHECKER_AUDIO_FORMAT', 'CHECKER_AUDIO_CHANNELS'],\n  sampleRate: ['CHECKER_AUDIO_SAMPLE_RATE'],\n  silenceStart: ['audioLeadingSilenceTooShort', 'audioLeadingSilenceLong', 'CHECKER_AUDIO_LEADING_UNMEASURABLE'],\n  silenceEnd: ['audioTrailingSilenceTooShort', 'audioTrailingSilenceLong', 'CHECKER_AUDIO_TRAILING_UNMEASURABLE'],\n  volume: ['CHECKER_AUDIO_VOLUME', 'CHECKER_AUDIO_NEAR_MUTE', 'CHECKER_AUDIO_VOLUME_UNMEASURABLE'],\n  peak: ['CHECKER_AUDIO_CLIPPED', 'CHECKER_AUDIO_VOLUME'],\n  dimensions: ['CHECKER_IMAGE_DIMENSIONS', 'CHECKER_IMAGE_FORMAT_DIMENSIONS'],\n  imageFormat: ['CHECKER_IMAGE_FORMAT', 'CHECKER_IMAGE_FORMAT_DIMENSIONS'],\n};\nexport function issueHasMeasure(issue, key) {\n  const category = ['dimensions', 'imageFormat'].includes(key) ? 'image' : 'audio';\n  return issue?.category === category && (MEASURE_CODES[key] ?? []).includes(issue?.code);\n}\nexport function hasMeasureIssue(issues, key) {\n  return (issues ?? []).some((issue) => issueHasMeasure(issue, key));\n}\nexport function isAudioFormatIssue(issue) {\n  return issue?.autoFixAvailable && (issueHasMeasure(issue, 'format') || issueHasMeasure(issue, 'sampleRate'));\n}\nexport function isSaturatedIssue(issue) { return issue?.category === 'audio' && issue?.code === 'CHECKER_AUDIO_CLIPPED'; }\n\nexport function measuredIssueSummary(issue, item, kind) {\n  const message = issue.message || '';\n  if (kind === 'audio') {\n    if (issueHasMeasure(issue, 'silenceStart') || issueHasMeasure(issue, 'silenceEnd')) {\n      const sides = silenceSummaryParts([issue], item);\n      return sides.length ? sides.join(' | ') : message;\n    }\n    if (issueHasMeasure(issue, 'volume') && issue.code !== 'CHECKER_AUDIO_NEAR_MUTE') {\n      const lufs = item?.integratedLufs;\n      const direction = typeof lufs === 'number' && lufs > -10\n        ? 'trop haut'\n        : 'trop bas';\n      return `Niveau sonore ${direction} (${formatLufs(lufs)})`;\n    }\n    if (issueHasMeasure(issue, 'sampleRate')) {\n      return `Échantillonnage incorrect (${item?.sampleRate ? `${item.sampleRate} Hz` : 'non mesuré'})`;\n    }\n    if (issue.code === 'CHECKER_AUDIO_CHANNELS' && issue.category === 'audio') {\n      return `Audio non mono (${item?.channels || 'canaux non mesurés'})`;\n    }\n    if (issueHasMeasure(issue, 'format')) {\n      return `Mauvais format audio (${item?.codec || 'format non mesuré'})`;\n    }\n  }\n  if (kind === 'image') {\n    const dimensions = item?.width && item?.height ? `${item.width}×${item.height}` : 'dimensions non mesurées';\n    const format = item?.format || 'format non mesuré';\n    if (issueHasMeasure(issue, 'imageFormat')) return `Mauvais format image (${format})`;\n    if (issueHasMeasure(issue, 'dimensions')) return `Dimensions incorrectes (${dimensions})`;\n    return `Image incorrecte (${dimensions} · ${format})`;\n  }\n  return message;\n}\n\nexport function silenceSummaryParts(issues, item) {\n  const hasStart = issues.some((issue) => {\n    if (silenceEdgeForIssue(issue) === 'leading') return true;\n    return issueHasMeasure(issue, 'silenceStart');\n  });\n  const hasEnd = issues.some((issue) => (\n    silenceEdgeForIssue(issue) === 'trailing'\n    || issueHasMeasure(issue, 'silenceEnd')\n  ));\n  const parts = [];\n  if (hasStart) parts.push(`Silence début = ${formatSeconds(item?.leadingSilenceSecs)}`);\n  if (hasEnd) parts.push(`Silence fin = ${formatSeconds(item?.trailingSilenceSecs)}`);\n  return parts;\n}\n",
 "src/components/CommunityPackChecker/packCheckerMeasures.jsx": "// Composant de ligne de mesure (UI). Les helpers purs (formatteurs, lignes de\n// mesure, predicats) vivent dans ./packCheckerFormat et sont re-exportes ici\n// pour les consommateurs JSX.\n\nimport { CircleCheck, Info, X } from '../icons/LucideLocal';\n\nexport * from './packCheckerFormat';\n\nexport function Measure({ label, value, status = 'ok' }) {\n  const StatusIcon = status === 'bad' ? X : (status === 'info' ? Info : CircleCheck);\n  return (\n    <div className={`checker-measure checker-measure--${status}`}>\n      <span>\n        <StatusIcon className=\"checker-measure-icon\" aria-hidden=\"true\" />\n        {label}\n      </span>\n      <strong>{value}</strong>\n    </div>\n  );\n}\n",
 "src/components/CommunityPackChecker/useCommunityPackChecker.js": "import { useMessageLanguage } from '../../i18n/useMessageLanguage.js';\nimport { presentCheckerReport } from '../../i18n/checkerMessages.js';\nimport { presentStoredError } from '../../i18n/userMessage.js';\nimport { presentUserMessage } from '../../i18n/userMessage.js';\nimport { invoke } from '@tauri-apps/api/core';\nimport { listen } from '@tauri-apps/api/event';\nimport { open, save } from '@tauri-apps/plugin-dialog';\nimport { writeTextFile } from '@tauri-apps/plugin-fs';\nimport { openPath } from '@tauri-apps/plugin-opener';\nimport { useCallback, useEffect, useRef, useState } from 'react';\nimport {\n  formatDiagnosticJson,\n  formatHtmlReport,\n  formatReadableReport,\n  formatTechnicalLog,\n  reportBaseName,\n} from './communityPackExports';\nimport { isTauriRuntime } from '../../utils/tauriRuntime';\nimport { releaseTauriListener } from '../../utils/tauriListener';\n\nconst EXPORTS = {\n  report: {\n    extension: 'html',\n    label: 'Rapport HTML',\n    filter: { name: 'Rapport HTML', extensions: ['html'] },\n    content: formatHtmlReport,\n  },\n  markdown: {\n    extension: 'md',\n    label: 'Rapport Markdown',\n    filter: { name: 'Rapport Markdown', extensions: ['md'] },\n    content: formatReadableReport,\n  },\n  log: {\n    extension: 'txt',\n    label: 'Journal technique',\n    filter: { name: 'Journal texte', extensions: ['txt'] },\n    content: formatTechnicalLog,\n  },\n  json: {\n    extension: 'json',\n    label: 'Diagnostic JSON',\n    filter: { name: 'Diagnostic JSON', extensions: ['json'] },\n    content: formatDiagnosticJson,\n  },\n};\n\nexport function useCommunityPackChecker() {\n  useMessageLanguage();\n  const [zipPath, setZipPath] = useState('');\n  const [report, setReport] = useState(null);\n  const [fixedResult, setFixedResult] = useState(null);\n  const [status, setStatus] = useState('idle');\n  const [error, setError] = useState('');\n  const [technicalDetail, setTechnicalDetail] = useState('');\n  const [exportNotice, setExportNotice] = useState('');\n  const [liveLog, setLiveLog] = useState([]);\n  const statusRef = useRef(status);\n\n  const appendLiveLog = useCallback((line) => {\n    if (!line) return;\n    setLiveLog((current) => [...current, line].slice(-10));\n  }, []);\n\n  useEffect(() => {\n    statusRef.current = status;\n  }, [status]);\n\n  useEffect(() => {\n    if (!isTauriRuntime()) return undefined;\n    let cancelled = false;\n    let unlisten = null;\n    listen('community-pack-checker-log', (event) => {\n      if (statusRef.current !== 'analyzing' && statusRef.current !== 'fixing') return;\n      appendLiveLog(event.payload);\n    }).then((fn) => {\n      if (cancelled) releaseTauriListener(fn);\n      else unlisten = fn;\n    });\n    return () => {\n      cancelled = true;\n      releaseTauriListener(unlisten);\n    };\n  }, [appendLiveLog]);\n\n  const analyzePath = useCallback(async (path, options = {}) => {\n    const nextPath = String(path || '').trim();\n    if (!nextPath) return null;\n    setZipPath(nextPath);\n    setFixedResult(null);\n    setError('');\n    setTechnicalDetail('');\n    setExportNotice('');\n    statusRef.current = 'analyzing';\n    setStatus('analyzing');\n    if (options.appendLog) {\n      appendLiveLog(options.label || 'Réanalyse du ZIP corrigé...');\n    } else {\n      setLiveLog(['Analyse du pack demandée...']);\n    }\n    try {\n      const nextReport = await invoke('analyze_community_pack', {\n        zipPath: nextPath,\n      });\n      setReport(nextReport);\n      const finalLines = (nextReport?.technicalLog || []).slice(-3);\n      setLiveLog((current) => [\n        ...current,\n        ...finalLines,\n        'Analyse terminée.',\n      ].slice(-9));\n      statusRef.current = 'idle';\n      setStatus('idle');\n      return nextReport;\n    } catch (err) {\n      const presented = presentUserMessage(err);\n      appendLiveLog({ userMessage: err, prefix: 'Analyse interrompue : ' });\n      setError(err);\n      setTechnicalDetail(presented.technicalDetail);\n      statusRef.current = 'idle';\n      setStatus('idle');\n      return null;\n    }\n  }, [appendLiveLog]);\n\n  const pickPack = useCallback(async () => {\n    const selected = await open({\n      multiple: false,\n      filters: [{ name: 'Pack Lunii', extensions: ['zip', '7z'] }],\n    });\n    if (selected) {\n      await analyzePath(Array.isArray(selected) ? selected[0] : selected);\n    }\n  }, [analyzePath]);\n\n  const fixPack = useCallback(async (metadataPatch = null, options = {}) => {\n    if (!zipPath) return null;\n    setError('');\n    setTechnicalDetail('');\n    setExportNotice('');\n    statusRef.current = 'fixing';\n    setStatus('fixing');\n    setLiveLog(['Correction du pack demandée...']);\n    try {\n      const result = await invoke('create_fixed_community_pack', {\n        zipPath,\n        outputDir: options.outputDir || null,\n        metadataPatch,\n        correctionSelection: options.correctionSelection || null,\n      });\n      appendLiveLog(`ZIP corrigé créé : ${result.fixedZipPath}`);\n      appendLiveLog('Réanalyse automatique du ZIP corrigé...');\n      // La réanalyse réinitialise fixedResult (via analyzePath) : on positionne\n      // donc le résultat APRÈS, pour que la bannière « ZIP corrigé » persiste.\n      const correctedReport = await analyzePath(result.fixedZipPath, {\n        appendLog: true,\n        label: 'Analyse du ZIP corrigé...',\n      });\n      if (correctedReport) {\n        const correctionLine = `[OK] Correction appliquée : ${result.automaticCorrectionsApplied ?? 0} automatique(s), ${result.optionalAudioSilencesFixed ?? 0} suggestion(s) facultative(s) sélectionnée(s).`;\n        setReport({\n          ...correctedReport,\n          technicalLog: [...(correctedReport.technicalLog || []), correctionLine],\n        });\n      }\n      setFixedResult(result);\n      statusRef.current = 'idle';\n      setStatus('idle');\n      return result;\n    } catch (err) {\n      const presented = presentUserMessage(err);\n      appendLiveLog({ userMessage: err, prefix: 'Correction interrompue : ' });\n      setError(err);\n      setTechnicalDetail(presented.technicalDetail);\n      statusRef.current = 'idle';\n      setStatus('idle');\n      return null;\n    }\n  }, [analyzePath, appendLiveLog, zipPath]);\n\n  const exportReport = useCallback(async (kind) => {\n    if (!report || !EXPORTS[kind]) return;\n    const config = EXPORTS[kind];\n    const defaultName = `${reportBaseName(report)} - ${kind}.${config.extension}`;\n    const target = await save({\n      defaultPath: defaultName,\n      filters: [config.filter],\n    });\n    if (!target) return;\n    try {\n      await writeTextFile(target, config.content(report));\n      setExportNotice(`${config.label} exporté.`);\n    } catch (err) {\n      setError({ userMessage: err, prefix: 'Export impossible : ' });\n    }\n  }, [report]);\n\n  const copyLog = useCallback(async () => {\n    if (!report) return;\n    try {\n      await navigator.clipboard.writeText(formatTechnicalLog(report));\n      setExportNotice('Journal copié.');\n    } catch {\n      setError('Impossible de copier le journal.');\n    }\n  }, [report]);\n\n  const openFixedLocation = useCallback(async () => {\n    if (!fixedResult?.fixedZipPath) return;\n    try {\n      await openPath(fixedResult.fixedZipPath);\n    } catch (err) {\n      setError({ userMessage: err, prefix: \"Impossible d'ouvrir le ZIP corrigé : \" });\n    }\n  }, [fixedResult]);\n\n  return {\n    zipPath,\n    report: presentCheckerReport(report),\n    fixedResult,\n    status,\n    error: presentStoredError(error),\n    exportNotice,\n    liveLog: liveLog.map((line) => presentStoredError(line)),\n    analyzePath,\n    pickPack,\n    technicalDetail,\n    fixPack,\n    exportReport,\n    copyLog,\n    openFixedLocation,\n  };\n}\n",
 "src/components/AdvancedWorkspace/DiagnosticsPanel.jsx": "// Les diagnostics, et ce qu'on peut réellement en faire.\n//\n// Les trois familles restent **distinctes** : intégrité du graphe, décision\n// d'auteur, import. Les fondre ferait\n// passer un `UNTESTED` d'import pour un refus. Un diagnostic n'est pas non plus\n// une erreur de génération : un projet diagnostiqué reste éditable et\n// enregistrable.\n//\n// Cliquer révèle le nœud concerné. Une résolution n'est offerte que si elle\n// mène à un geste ou à un formulaire réel — « pas de dialogue sans chemin de\n// résolution réel ».\n\nimport { ArrowRight } from '../icons/LucideLocal';\nimport { Button } from '../common/Button';\nimport {\n  RESOLUTION_FORM,\n  RESOLUTION_GESTURE,\n  RESOLUTION_REVEAL,\n  resolutionsForDiagnostic,\n} from '../../store/advancedAuthoring/diagnosticResolutions.js';\nimport { ExportRefusalReport } from './ExportReport.jsx';\nimport { EXPORT_REFUSAL, PREPARATION_REFUSAL } from '../../store/advancedExport/exportOutcome.js';\n\nexport function DiagnosticsPanel({\n  issues,\n  view,\n  index,\n  disabled,\n  onFocusPath,\n  onGesture,\n  onOpenForm,\n}) {\n  const groups = new Map();\n  for (const issue of issues) {\n    const key = issue.nodeLabel ? (issue.nodePath ?? issue.nodeLabel) : '__pack__';\n    if (!groups.has(key)) {\n      groups.set(key, { label: issue.nodeLabel ?? 'Pack', issues: [] });\n    }\n    groups.get(key).issues.push(issue);\n  }\n\n  return (\n    <section aria-label=\"Éléments à corriger\">\n      {[...groups].map(([key, group]) => (\n        <div key={key} className=\"validation-pill-group\">\n          <div className=\"validation-pill-group-head\">\n            <span className=\"validation-pill-group-label\">{group.label}</span>\n            <span className=\"validation-pill-group-count\">· {group.issues.length}</span>\n          </div>\n          {group.issues.map((issue) => {\n            const resolutions = issue.diagnostic\n              ? resolutionsForDiagnostic({ diagnostic: issue.diagnostic, view, index })\n              : [];\n            return (\n              <details key={issue.id} className=\"validation-pill-details\">\n                <summary className=\"validation-pill-item\">\n                  <span className=\"validation-pill-item-dot\" aria-hidden=\"true\" />\n                  <span className=\"validation-pill-item-label\">{issue.message}</span>\n                  <span className=\"validation-pill-item-go\" aria-hidden=\"true\">\n                    <ArrowRight width={11} height={11} strokeWidth={2.6} />\n                  </span>\n                </summary>\n                <div className=\"validation-pill-details-body\">\n                  <p className=\"validation-pill-details-category\">{issue.category}</p>\n                  <div className=\"validation-pill-details-actions\">\n                    {issue.nodePath && (\n                      <Button size=\"sm\" onClick={() => onFocusPath(issue.nodePath)}>\n                        Corriger\n                      </Button>\n                    )}\n                    {resolutions.map((resolution) => (\n                      <Button\n                        key={resolution.id}\n                        size=\"sm\"\n                        variant={resolution.destructive ? 'danger-outline' : 'secondary'}\n                        disabled={disabled && resolution.nature === RESOLUTION_GESTURE}\n                        onClick={() => {\n                          if (resolution.nature === RESOLUTION_GESTURE) onGesture(resolution.gesture);\n                          else if (resolution.nature === RESOLUTION_FORM) onOpenForm(resolution);\n                          else if (resolution.nature === RESOLUTION_REVEAL) {\n                            onFocusPath(resolution.paths?.[0] ?? issue.nodePath);\n                          }\n                        }}\n                      >\n                        {resolution.label}\n                      </Button>\n                    ))}\n                  </div>\n                </div>\n              </details>\n            );\n          })}\n        </div>\n      ))}\n      {issues.length === 0 && (\n        <p className=\"validation-pill-empty\">Aucun élément à corriger.</p>\n      )}\n    </section>\n  );\n}\n\n// Ce popover commun réunit les diagnostics derrière « à corriger » et reste\n// hors du triptyque Graphe / Inspecteur / liste des nœuds :\n// diagnostics et refus restent une seule surface, sans recréer de\n// bande basse.\nexport function AdvancedIssuesPanel({ context, onRequestClose }) {\n  if (!context) return null;\n  const focusAndClose = (path) => {\n    context.onFocusPath?.(path);\n    onRequestClose?.();\n  };\n  const openFormAndClose = (resolution) => {\n    context.onOpenForm?.(resolution);\n    onRequestClose?.();\n  };\n  const refusal = context.exportState?.refusal ?? null;\n  const refusalAlreadyExplained = refusal?.kind === EXPORT_REFUSAL.PAYLOAD_DECODE\n    || (refusal?.kind === EXPORT_REFUSAL.PREPARATION && [\n      PREPARATION_REFUSAL.GRAPH_INTEGRITY,\n      PREPARATION_REFUSAL.AUTHORING_ACTION_REQUIRED,\n      PREPARATION_REFUSAL.READINESS_BLOCKED,\n    ].includes(refusal?.preparationKind));\n\n  return (\n    <div className=\"advanced-issues-popover\">\n      <DiagnosticsPanel\n        issues={context.blockingIssues ?? []}\n        view={context.view}\n        index={context.index}\n        disabled={context.disabled}\n        onFocusPath={focusAndClose}\n        onGesture={context.onGesture}\n        onOpenForm={openFormAndClose}\n      />\n\n      {context.working && (\n        <p className=\"advanced-export__running\" role=\"status\">\n          Fabrication en cours : l'édition est suspendue, la vue reste navigable.\n        </p>\n      )}\n\n      {refusal && !refusalAlreadyExplained && (\n        <ExportRefusalReport\n          refusal={refusal}\n          stagePaths={context.stagePaths}\n          onFocusPath={focusAndClose}\n          onDismiss={context.exportState.dismissRefusal}\n        />\n      )}\n    </div>\n  );\n}\n",
 "src/components/AdvancedWorkspace/ExportReport.jsx": "import { useTranslation } from 'react-i18next';\nimport { presentTechnicalMessage } from '../../i18n/userMessage.js';\nimport { UserMessage } from '../common/UserMessage.jsx';\n// Ce qu'un refus d'export a empêché.\n//\n// Le branchement se fait sur `kind`, et sur `preparation.error.kind` pour les\n// cinq sous-types — jamais sur une recherche de mots dans un message. Les\n// textes reçus (`message`, `detail`) sont affichés tels quels : ce sont des\n// données, pas des sources de décision.\n//\n// Une **annulation** n'est pas une panne d'écriture : un `output-write` survenu\n// pendant un abandon reste une panne d'écriture, avec résidu possible.\n//\n// Les textes tutoient et parlent du pack, comme le reste du rapport commun.\nimport { useMemo } from 'react';\n\nimport { Button } from '../common/Button';\nimport {\n  EXPORT_REFUSAL,\n  PREPARATION_REFUSAL,\n  groupUnavailableMedia,\n  mediaFieldLabel,\n} from '../../store/advancedExport/exportOutcome.js';\n\n// Les chemins des Écrans, tels que la vue relue les donne. Ce\n// rapport se peint aussi dans la file de rendu, qui ne connaît pas la vue du\n// graphe : la correspondance lui est donc **tendue**, plutôt que déduite d'un\n// index qu'elle n'a pas. Sans elle, l'identifiant reste lisible, il n'est\n// simplement plus cliquable.\nfunction StageList({ stageIds, stagePaths, onFocusPath }) {\n  const pathByUuid = useMemo(() => {\n    const table = new Map();\n    for (const entry of Array.isArray(stagePaths) ? stagePaths : []) {\n      if (entry?.uuid) table.set(entry.uuid, entry.path ?? null);\n    }\n    return table;\n  }, [stagePaths]);\n  if (!stageIds || stageIds.length === 0) return null;\n  return (\n    <ul className=\"advanced-export__stages\">\n      {stageIds.map((uuid) => {\n        // Le chemin d'un nœud appartient à Rust : il est **retrouvé** dans\n        // la vue relue, jamais recomposé à partir d'un UUID.\n        const path = pathByUuid.get(uuid) ?? null;\n        return (\n          <li key={uuid}>\n            {path && onFocusPath\n              ? <button type=\"button\" className=\"advanced-link\" onClick={() => onFocusPath(path)}>{uuid}</button>\n              : <code>{uuid}</code>}\n          </li>\n        );\n      })}\n    </ul>\n  );\n}\n\nfunction RefusalBody({ refusal, embedded, stagePaths, onFocusPath, onOpenDiagnostics }) {\n  // Intégré au rapport commun, le message y est déjà : ne pas le redire.\n  const message = embedded ? null : refusal.message;\n  switch (refusal.kind) {\n    case EXPORT_REFUSAL.PAYLOAD_DECODE:\n      return (\n        <div>\n          <p className=\"advanced-export__row-message\">\n            Le projet n'a pas pu être relu, le pack n'a pas été produit.\n          </p>\n          {refusal.codecError && (\n            <p className=\"advanced-export__row-path\">\n              <code>{refusal.codecError.code}</code> {refusal.codecError.path}\n              {' — trouvé : '}{refusal.codecError.found}\n              {' ; attendu : '}{refusal.codecError.expected}\n            </p>\n          )}\n        </div>\n      );\n\n    case EXPORT_REFUSAL.PREPARATION:\n      return (\n        <div>\n          {message && <p className=\"advanced-export__row-message\">{message}</p>}\n          {refusal.preparationKind === PREPARATION_REFUSAL.GRAPH_INTEGRITY && (\n            <ul className=\"advanced-export__rows\">\n              {refusal.integrityErrors.map((error, position) => (\n                <li key={`${error.code}-${error.path}-${position}`} className=\"advanced-export__row\">\n                  <p className=\"advanced-export__row-head\"><code>{error.code}</code></p>\n                  <div className=\"advanced-export__row-message\"><UserMessage value={error} /></div>\n                  <p className=\"advanced-export__row-path\"><code>{error.path}</code></p>\n                </li>\n              ))}\n            </ul>\n          )}\n          {refusal.preparationKind === PREPARATION_REFUSAL.AUTHORING_ACTION_REQUIRED && (\n            <>\n              <ul className=\"advanced-export__rows\">\n                {refusal.diagnostics.map((diagnostic, position) => (\n                  <li key={`${diagnostic.code}-${diagnostic.path}-${position}`} className=\"advanced-export__row\">\n                    <p className=\"advanced-export__row-head\"><code>{diagnostic.code}</code></p>\n                    <div className=\"advanced-export__row-message\"><UserMessage value={diagnostic} /></div>\n                    <p className=\"advanced-export__row-path\"><code>{diagnostic.path}</code></p>\n                  </li>\n                ))}\n              </ul>\n              {onOpenDiagnostics && (\n                <p className=\"advanced-export__actions\">\n                  {/* La résolution existe déjà, dans le panneau de diagnostics :\n                      ce refus y conduit au lieu d'en fabriquer une seconde. */}\n                  <Button size=\"sm\" onClick={onOpenDiagnostics}>Ouvrir les résolutions</Button>\n                </p>\n              )}\n            </>\n          )}\n          {refusal.preparationKind === PREPARATION_REFUSAL.READINESS_BLOCKED && (\n            <ul className=\"advanced-export__rows\">\n              {refusal.diagnostics.map((line, position) => (\n                <li key={`${position}-${String(line)}`} className=\"advanced-export__row\">{String(line)}</li>\n              ))}\n            </ul>\n          )}\n        </div>\n      );\n\n    case EXPORT_REFUSAL.MEDIA_UNAVAILABLE: {\n      const groups = groupUnavailableMedia(refusal.entries);\n      return (\n        <div>\n          <p className=\"advanced-export__row-message\">\n            Le pack n'a pas été produit : {groups.length} média{groups.length > 1 ? 's sont' : ' est'} introuvable{groups.length > 1 ? 's' : ''}.\n            Pour chacun, les écrans qui l'utilisent sont listés.\n          </p>\n          <ul className=\"advanced-export__rows\">\n            {groups.map((group) => (\n              <li key={group.assetRef} className=\"advanced-export__row\">\n                <p className=\"advanced-export__row-head\">\n                  <code>{group.assetRef}</code>\n                  {' — '}\n                  {group.fields.map(mediaFieldLabel).join(', ')}\n                </p>\n                <p className=\"advanced-export__row-message\">{group.causeLabel}</p>\n                {group.byReferenceOnly ? (\n                  <p className=\"advanced-export__row-message\">\n                    Aucun ancien emplacement n'est connu : choisis le fichier depuis l'écran\n                    concerné.\n                  </p>\n                ) : group.lastKnownPath && (\n                  <p className=\"advanced-export__row-path\">\n                    dernier emplacement connu : <code>{group.lastKnownPath}</code>\n                  </p>\n                )}\n                {group.detail && <p className=\"advanced-export__row-path\">{presentTechnicalMessage(group.detail)}</p>}\n                <StageList stageIds={group.stageIds} stagePaths={stagePaths} onFocusPath={onFocusPath} />\n              </li>\n            ))}\n          </ul>\n        </div>\n      );\n    }\n\n    case EXPORT_REFUSAL.ARCHIVE_NAME_COLLISION:\n      return (\n        <div>\n          <p className=\"advanced-export__row-message\">\n            Deux médias portent le même nom dans le pack. C'est un défaut de Story Studio,\n            pas du projet : le pack n'a pas été produit.\n          </p>\n          <ul className=\"advanced-export__rows\">\n            {refusal.conflicts.map((conflict) => (\n              <li key={`${conflict.assetRef}-${conflict.archiveName}`} className=\"advanced-export__row\">\n                <code>{conflict.assetRef}</code> → <code>{conflict.archiveName}</code>\n              </li>\n            ))}\n          </ul>\n        </div>\n      );\n\n    case EXPORT_REFUSAL.MEDIA_ORACLE:\n      return (\n        <div>\n          <p className=\"advanced-export__row-message\">\n            Les médias préparés ne correspondent pas à ceux du projet. Tes fichiers ne sont pas\n            en cause ; le pack n'a pas été produit.\n          </p>\n          <ul className=\"advanced-export__rows\">\n            {refusal.disagreements.map((disagreement, position) => (\n              <li key={`${disagreement.assetRef}-${position}`} className=\"advanced-export__row\">\n                <p className=\"advanced-export__row-head\">\n                  <code>{disagreement.assetRef}</code>\n                  {disagreement.stageUuid && <> — écran <code>{disagreement.stageUuid}</code></>}\n                  {disagreement.kind && <> — {mediaFieldLabel(disagreement.kind)}</>}\n                </p>\n                <p className=\"advanced-export__row-message\">\n                  attendu <code>{presentTechnicalMessage(disagreement.expected)}</code>, observé <code>{presentTechnicalMessage(disagreement.observed)}</code>\n                </p>\n              </li>\n            ))}\n          </ul>\n        </div>\n      );\n\n    case EXPORT_REFUSAL.CANCELLED:\n      return (\n        <p className=\"advanced-export__row-message\">\n          Génération annulée : aucun pack n'a été produit et le projet est inchangé.\n        </p>\n      );\n\n    case EXPORT_REFUSAL.OUTPUT_WRITE:\n      return (\n        <div>\n          <p className=\"advanced-export__row-message\">\n            L'écriture du pack a échoué. Le projet et tes fichiers d'origine restent intacts.\n          </p>\n          {refusal.path && <p className=\"advanced-export__row-path\"><code>{refusal.path}</code></p>}\n          {message && <p className=\"advanced-export__row-message\">{message}</p>}\n          <p className=\"advanced-export__row-message\">\n            {/* Quand le nettoyage du fichier temporaire échoue après une\n                annulation, le refus **devient** `output-write` pour ne pas\n                masquer le résidu. Le dire est le seul moyen que l'auteur aille\n                voir. */}\n            Un fichier temporaire <code>.partial</code> a pu rester dans le dossier de sortie :\n            tu peux le supprimer.\n          </p>\n        </div>\n      );\n\n    case EXPORT_REFUSAL.REQUEST:\n      return (\n        <p className=\"advanced-export__row-message\">\n          {/* Rien n'a été demandé au moteur : la garde est locale, et le dire\n              évite de laisser croire qu'il a refusé. */}\n          {message ? `${message} ` : ''}La génération n'a pas été lancée.\n        </p>\n      );\n\n    case EXPORT_REFUSAL.UNTYPED:\n    default:\n      return (\n        <p className=\"advanced-export__row-message\">\n          La génération s'est interrompue sans explication précise.\n          {message && <> <code>{message}</code></>}\n        </p>\n      );\n  }\n}\n\n// `embedded` : peint sous le rapport commun de la file, qui porte déjà le titre\n// et le message du refus ; seul le détail utile à la correction reste.\nexport function ExportRefusalReport({ refusal, embedded = false, stagePaths = null, onFocusPath = null, onOpenDiagnostics = null, onDismiss = null }) {\n  useTranslation();\n  if (!refusal) return null;\n  return (\n    <section\n      className=\"advanced-export__outcome advanced-export__outcome--refused\"\n      role=\"alert\"\n      data-kind={refusal.kind}\n    >\n      {!embedded && <h3>{refusal.title}</h3>}\n      <RefusalBody\n        refusal={refusal}\n        embedded={embedded}\n        stagePaths={stagePaths}\n        onFocusPath={onFocusPath}\n        onOpenDiagnostics={onOpenDiagnostics}\n      />\n      {onDismiss && (\n        <p className=\"advanced-export__actions\">\n          <Button size=\"sm\" onClick={onDismiss}>Fermer</Button>\n        </p>\n      )}\n    </section>\n  );\n}\n",
 "src/components/AdvancedWorkspace/ZipReviewPanel.jsx": "// La relecture d'une archive exportée, dans l'espace de travail avancé.\n//\n// C'est **le simulateur du dépôt**, pas une seconde implémentation : le même\n// `FlatSimulator`, le même transport `load_pack_zip` / `get_pack_asset`, le même\n// lecteur audio partagé. Il est monté **sans projet hiérarchique** — lui en\n// fabriquer un vide pour satisfaire une signature monterait un arbre qui\n// n'existe pas dans un document avancé.\n//\n// Il a un frère, `DocumentSimulationPanel`, qui joue le document en\n// cours au lieu de l'archive produite. Les deux ne se remplacent pas : celui-ci\n// prouve ce qui a **réellement** été produit, ce que l'écoute du document ne\n// prouve pas. Ils sont mutuellement exclusifs à l'écran, pas dans l'usage.\n//\n// Le bandeau dit ce que la simulation est vraiment : l'archive produite, à la\n// révision qui l'a produite. Après une nouvelle édition, il cesse de la\n// présenter comme celle du document courant — c'est la seule chose qui empêche\n// de croire qu'on vient d'écouter sa dernière modification.\n\nimport { FloatingSimulator } from '../FloatingSimulator/FloatingSimulator';\nimport { Button } from '../common/Button';\nimport { EDITOR_LAYOUT_SCOPE } from '../../store/persistentSettings.js';\n\nexport function ZipReviewPanel({ review, onClose }) {\n  if (!review) return null;\n  return (\n    <>\n      <div\n        className=\"advanced-review-banner\"\n        role=\"status\"\n        data-current={review.isCurrentRevision ? 'true' : 'false'}\n      >\n        <span className=\"advanced-review-banner__title\">\n          Simulation de l'archive exportée\n        </span>\n        <code className=\"advanced-review-banner__path\">{review.zipPath}</code>\n        <span className=\"advanced-review-banner__state\">\n          {review.isCurrentRevision\n            ? \"elle correspond au document actuellement ouvert\"\n            : \"le document a changé depuis cet export : ce n'est plus ce que tu édites\"}\n        </span>\n        <Button size=\"sm\" onClick={onClose}>Fermer la relecture</Button>\n      </div>\n      <FloatingSimulator\n        zipPath={review.zipPath}\n        hostSelector=\".workspace\"\n        layoutScope={EDITOR_LAYOUT_SCOPE.ADVANCED}\n        onClose={onClose}\n      />\n    </>\n  );\n}\n",
 "src/components/layout/ValidationPill.jsx": "import { lazy, Suspense, useEffect, useMemo, useRef, useState } from 'react';\nimport { ArrowRight, TriangleAlert, CircleCheck, Loader2 } from '../icons/LucideLocal';\nimport { Tooltip } from '../common/Tooltip';\nimport './ValidationPill.css';\n\nconst AdvancedIssuesPanel = lazy(() => import('../AdvancedWorkspace/DiagnosticsPanel.jsx')\n  .then((module) => ({ default: module.AdvancedIssuesPanel })));\n\nexport const ISSUE_KIND_HIERARCHICAL = 'hierarchical';\nexport const ISSUE_KIND_ADVANCED = 'advanced';\n\n// Le caret du bouton est un **glyphe plein**, pas une icône : il joue le rôle\n// typographique d'un « ▾ » à 9 px, taille à laquelle le chevron tracé du jeu\n// partagé rendrait un trait d'un demi-pixel. Il reste donc ici, et l'inventaire\n// des jeux d'icônes le nomme avec cette raison. La flèche qui\n// l'accompagnait, elle, redoublait la flèche du jeu partagé : elle a disparu.\nconst Caret = ({ size = 10 }) => (\n  <svg width={size} height={size} viewBox=\"0 0 10 10\" fill=\"currentColor\" aria-hidden=\"true\">\n    <path d=\"M1 3l4 4 4-4z\" />\n  </svg>\n);\n\nfunction parseIssue(issue) {\n  const text = issue?.text ?? '';\n  const dashIdx = text.indexOf(' — ');\n  if (dashIdx === -1) {\n    return { groupKey: '__pack__', groupLabel: 'Pack', label: text };\n  }\n  const location = text.slice(0, dashIdx);\n  return {\n    groupKey: location,\n    groupLabel: location,\n    label: text.slice(dashIdx + 3),\n  };\n}\n\nfunction buildGroups(issues) {\n  const groupMap = new Map();\n  issues.forEach((issue) => {\n    const parsed = parseIssue(issue);\n    let group = groupMap.get(parsed.groupKey);\n    if (!group) {\n      group = { key: parsed.groupKey, label: parsed.groupLabel, items: [] };\n      groupMap.set(parsed.groupKey, group);\n    }\n    group.items.push({ issue, label: parsed.label });\n  });\n  const groups = [...groupMap.values()];\n  const flat = [];\n  groups.forEach((group) => {\n    group.items.forEach((item) => {\n      item.flatIndex = flat.length;\n      flat.push(item);\n    });\n  });\n  return { groups, flat };\n}\n\nexport function ValidationPill({\n  issueKind = ISSUE_KIND_HIERARCHICAL,\n  validationIssues = [],\n  advancedIssues = null,\n  pathAuditPending = false,\n  open,\n  onOpenChange,\n  onSelectIssue,\n  onCountZeroTransition,\n  shortcutLabel = '',\n}) {\n  const advanced = issueKind === ISSUE_KIND_ADVANCED;\n  const blockingIssues = useMemo(\n    () => validationIssues.filter((issue) => issue?.status === 'error' || issue?.status === 'warning'),\n    [validationIssues],\n  );\n  const advancedBlockingIssues = advancedIssues?.blockingIssues ?? [];\n  const totalCount = advanced ? advancedBlockingIssues.length : blockingIssues.length;\n  const pending = advanced\n    ? pathAuditPending || advancedIssues == null || ['idle', 'pending'].includes(advancedIssues?.readiness?.status)\n    : pathAuditPending;\n  const { groups, flat } = useMemo(() => buildGroups(blockingIssues), [blockingIssues]);\n\n  const state = pending ? 'verifying' : totalCount > 0 ? 'issues' : 'ok';\n  const isOpen = open && state !== 'verifying';\n  const wrapRef = useRef(null);\n  const dropdownRef = useRef(null);\n  const closeTimerRef = useRef(null);\n  const [activeIndex, setActiveIndex] = useState(0);\n\n  useEffect(() => () => {\n    if (closeTimerRef.current) clearTimeout(closeTimerRef.current);\n  }, []);\n\n  useEffect(() => {\n    if (!isOpen) setActiveIndex(0);\n  }, [isOpen]);\n\n  useEffect(() => {\n    if (activeIndex > flat.length - 1) setActiveIndex(Math.max(0, flat.length - 1));\n  }, [flat.length, activeIndex]);\n\n  const prevTotalCountRef = useRef(totalCount);\n  useEffect(() => {\n    if (prevTotalCountRef.current > 0 && totalCount === 0) onCountZeroTransition?.();\n    prevTotalCountRef.current = totalCount;\n  }, [totalCount, onCountZeroTransition]);\n\n  useEffect(() => {\n    if (!isOpen) return undefined;\n    function onPointerDown(event) {\n      if (!wrapRef.current?.contains(event.target)) onOpenChange?.(false);\n    }\n    function onKeyDown(event) {\n      if (event.key === 'Escape') {\n        event.preventDefault();\n        onOpenChange?.(false);\n        return;\n      }\n      if (advanced || !wrapRef.current?.contains(event.target)) return;\n      if (event.key === 'ArrowDown') {\n        event.preventDefault();\n        setActiveIndex((index) => (flat.length === 0 ? 0 : (index + 1) % flat.length));\n      } else if (event.key === 'ArrowUp') {\n        event.preventDefault();\n        setActiveIndex((index) => (flat.length === 0 ? 0 : (index - 1 + flat.length) % flat.length));\n      } else if (event.key === 'Enter') {\n        const item = flat[activeIndex];\n        if (item) {\n          event.preventDefault();\n          selectIssue(item.issue.id);\n        }\n      }\n    }\n    document.addEventListener('pointerdown', onPointerDown);\n    document.addEventListener('keydown', onKeyDown);\n    return () => {\n      document.removeEventListener('pointerdown', onPointerDown);\n      document.removeEventListener('keydown', onKeyDown);\n    };\n  }, [isOpen, advanced, flat, activeIndex, onOpenChange, onSelectIssue]);\n\n  useEffect(() => {\n    if (!isOpen || advanced || !dropdownRef.current) return;\n    const element = dropdownRef.current.querySelector(`[data-flat-idx=\"${activeIndex}\"]`);\n    element?.scrollIntoView?.({ block: 'nearest' });\n  }, [isOpen, advanced, activeIndex]);\n\n  const tooltipText = state === 'verifying'\n    ? 'Vérification en cours…'\n    : `${totalCount} élément${totalCount > 1 ? 's' : ''} à corriger${shortcutLabel ? ` (${shortcutLabel})` : ''}`;\n  const popoverSubtitle = totalCount === 0\n    ? 'Le pack peut être généré.'\n    : `${totalCount} élément${totalCount > 1 ? 's' : ''} empêche${totalCount > 1 ? 'nt' : ''} la génération.`;\n\n  function selectIssue(issueId) {\n    if (!issueId) return;\n    onSelectIssue?.(issueId);\n    onOpenChange?.(false);\n  }\n\n  function handlePillClick() {\n    if (state !== 'verifying') onOpenChange?.(!open);\n  }\n\n  function openPopover() {\n    if (state === 'verifying') return;\n    if (closeTimerRef.current) clearTimeout(closeTimerRef.current);\n    onOpenChange?.(true);\n  }\n\n  function scheduleClose() {\n    if (closeTimerRef.current) clearTimeout(closeTimerRef.current);\n    closeTimerRef.current = setTimeout(() => onOpenChange?.(false), 140);\n  }\n\n  return (\n    <div\n      className={`validation-pill-wrap ${isOpen ? 'is-open' : ''}`}\n      ref={wrapRef}\n      onPointerEnter={openPopover}\n      onPointerLeave={scheduleClose}\n      onMouseEnter={openPopover}\n      onMouseLeave={scheduleClose}\n      onFocus={openPopover}\n    >\n      <Tooltip text={tooltipText} disabled={isOpen}>\n        <button\n          type=\"button\"\n          data-toolbar-id=\"toggleValidation\"\n          className={`validation-pill is-${state} ${isOpen ? 'is-active' : ''}`}\n          onClick={handlePillClick}\n          aria-haspopup={state === 'verifying' ? undefined : 'dialog'}\n          aria-expanded={state === 'verifying' ? undefined : isOpen}\n          aria-label={tooltipText}\n        >\n          {state !== 'verifying' ? (\n            <>\n              <span className={state === 'issues' ? 'validation-pill-icon' : 'validation-pill-check'}>\n                {state === 'issues'\n                  ? <TriangleAlert width={12} height={12} />\n                  : <CircleCheck width={12} height={12} />}\n              </span>\n              <span className=\"validation-pill-count\">{totalCount}</span>\n              <span className=\"validation-pill-label\">à corriger</span>\n              <span className=\"validation-pill-caret\"><Caret size={9} /></span>\n            </>\n          ) : (\n            <>\n              <span className=\"validation-pill-spinner\"><Loader2 width={12} height={12} /></span>\n              <span className=\"validation-pill-label\">Vérification…</span>\n            </>\n          )}\n        </button>\n      </Tooltip>\n\n      {isOpen ? (\n        <>\n          <div className=\"validation-pill-hover-bridge\" aria-hidden=\"true\" />\n          <div\n            className={`validation-pill-dd is-${state}`}\n            ref={dropdownRef}\n            role=\"dialog\"\n            aria-label=\"Liste des éléments à corriger\"\n          >\n            <div className=\"validation-pill-dd-head\">\n              <span className=\"validation-pill-dd-title\">À corriger</span>\n              <span className=\"validation-pill-dd-subtitle\">{popoverSubtitle}</span>\n            </div>\n            <div className=\"validation-pill-dd-body\">\n              {advanced ? (\n                <Suspense fallback={<p className=\"validation-pill-empty\">Chargement…</p>}>\n                  <AdvancedIssuesPanel\n                    context={advancedIssues}\n                    onRequestClose={() => onOpenChange?.(false)}\n                  />\n                </Suspense>\n              ) : (\n                <>\n                  {groups.map((group) => (\n                    <div key={group.key} className=\"validation-pill-group\">\n                      <div className=\"validation-pill-group-head\">\n                        <span className=\"validation-pill-group-label\">{group.label}</span>\n                        <span className=\"validation-pill-group-count\">· {group.items.length}</span>\n                      </div>\n                      {group.items.map((item) => {\n                        const isActive = item.flatIndex === activeIndex;\n                        return (\n                          <button\n                            type=\"button\"\n                            key={`${item.issue.id ?? 'noid'}:${item.flatIndex}`}\n                            data-flat-idx={item.flatIndex}\n                            className={`validation-pill-item ${isActive ? 'is-active' : ''}`}\n                            onClick={() => selectIssue(item.issue.id)}\n                            onMouseEnter={() => setActiveIndex(item.flatIndex)}\n                          >\n                            <span className=\"validation-pill-item-dot\" aria-hidden=\"true\" />\n                            <span className=\"validation-pill-item-label\">{item.label}</span>\n                            <span className=\"validation-pill-item-go\" aria-hidden=\"true\"><ArrowRight width={11} height={11} strokeWidth={2.6} /></span>\n                          </button>\n                        );\n                      })}\n                    </div>\n                  ))}\n                  {blockingIssues.length === 0 && (\n                    <p className=\"validation-pill-empty\">Aucun élément à corriger.</p>\n                  )}\n                </>\n              )}\n            </div>\n          </div>\n        </>\n      ) : null}\n    </div>\n  );\n}\n",
 "src/hooks/useAdvancedReadiness.js": "// La qualification d'export du document courant, recalculée et jamais mémorisée.\n//\n// Un ancien verdict ne survit jamais à un geste : une readiness est dérivée du\n// payload, et ce hook ne fait que trois choses : la demander quand elle est utile,\n// jeter les retours qui ne concernent plus le payload courant, et dire quand\n// elle est périmée plutôt que d'afficher un chiffre faux.\n//\n// Elle n'autorise rien. La commande d'export refait ses propres vérifications\n// et reste l'autorité ; ce que ce hook rend sert à **montrer** ce qui bloque,\n// pas à décider si l'export part.\n\nimport { useCallback, useEffect, useRef, useState } from 'react';\n\nimport { assessAdvancedProjectReadiness, readAuthoringPayload } from '../store/projectModel/authoring.js';\nimport { summarizeReadiness } from '../store/advancedExport/exportReadiness.js';\nimport { logger } from '../utils/logger';\n\nconst READINESS_STATUS = Object.freeze({\n  IDLE: 'idle',\n  PENDING: 'pending',\n  READY: 'ready',\n  FAILED: 'failed',\n});\n\nexport function useAdvancedReadiness({\n  project,\n  // Tant que la qualification n'est pas regardée, elle n'est pas demandée : sur\n  // le profil extrême, décoder le payload à chaque geste coûterait le prix d'un\n  // geste de plus, pour un chiffre que personne ne lit.\n  enabled = false,\n  assess = assessAdvancedProjectReadiness,\n}) {\n  const payload = readAuthoringPayload(project);\n  const [state, setState] = useState({\n    status: READINESS_STATUS.IDLE,\n    summary: null,\n    error: null,\n    revision: null,\n  });\n  const projectRef = useRef(project);\n  projectRef.current = project;\n  const inFlightRef = useRef(null);\n\n  const refresh = useCallback(async () => {\n    const current = projectRef.current;\n    const revision = readAuthoringPayload(current);\n    if (revision === null) return;\n    inFlightRef.current = revision;\n    setState((previous) => ({ ...previous, status: READINESS_STATUS.PENDING }));\n    try {\n      const readiness = await assess(current);\n      // Retour périmé : le payload a changé pendant l'appel. Il est jeté sans\n      // bruit, exactement comme une réponse de geste périmée — l'afficher\n      // donnerait la qualification d'une révision que l'auteur a quittée.\n      if (inFlightRef.current !== revision) return;\n      setState({\n        status: READINESS_STATUS.READY,\n        summary: summarizeReadiness(readiness),\n        error: null,\n        revision,\n      });\n    } catch (error) {\n      if (inFlightRef.current !== revision) return;\n      logger.warn(`advanced:readiness-failed code=${error?.code ?? 'inconnu'}`);\n      setState({\n        status: READINESS_STATUS.FAILED,\n        summary: null,\n        error,\n        revision,\n      });\n    }\n  }, [assess]);\n\n  useEffect(() => {\n    if (!enabled || payload === null) return;\n    refresh();\n  }, [enabled, payload, refresh]);\n\n  return {\n    status: state.status,\n    summary: state.summary,\n    error: state.error,\n    // Le témoin de fraîcheur : la readiness affichée décrit-elle encore le\n    // document ouvert ? Un `true` ici n'est pas une erreur, c'est l'aveu qu'une\n    // édition vient d'avoir lieu et que le chiffre est celui d'avant.\n    stale: state.revision !== null && state.revision !== payload,\n    refresh,\n  };\n}\n",
 "src/hooks/useAdvancedExport.js": "// Le raccord React de la production graphe.\n//\n// **Ce hook ne fait pas tourner d'export.** Le travail vit dans la\n// file de rendu, comme celui de l'éditeur Libre : c'est elle qui tient le poste\n// natif, la progression, l'annulation, le résultat et l'historique. Ce qui reste\n// ici est ce qui ne pouvait pas déménager avec lui —\n//\n// - **la destination**, choisie avant de bloquer l'auteur : le sélecteur est un\n//   dialogue natif qui peut rester ouvert longtemps, et suspendre l'édition\n//   pendant ce temps serait un verrou sans travail derrière ;\n// - **la préparation**, qui bloque l'auteur, attend ses gestes en vol, puis\n//   capture ce qui part. Ses règles vivent dans\n//   `store/production/advancedRenderWork.js`, sans framework et sans Tauri ;\n// - **le refus prononcé avant le moteur** — document à corriger, fichier absent.\n//   Rien n'a été fabriqué, donc rien n'entre dans la file : ce refus se rapporte\n//   là où l'auteur a posé la question, comme la chaîne Libre rapporte le sien\n//   dans sa boîte de dialogue. Décision utilisateur du 16 septembre 2026 ;\n// - **l'archive à relire**, tenue à côté du reste : fermer un compte rendu ne\n//   ferme pas le lecteur, et une nouvelle production ne doit pas effacer\n//   l'archive que l'auteur est en train d'écouter.\n\nimport { useCallback, useMemo, useRef, useState } from 'react';\nimport { open as openDialog } from '@tauri-apps/plugin-dialog';\n\nimport { prepareAdvancedWork } from '../store/production/advancedRenderWork.js';\nimport { promoteDisplayedLayout } from '../store/advancedExport/displayedLayout.js';\nimport { createAdvancedViewBridge } from '../store/advancedGraphView/advancedViewBridge.js';\nimport { GESTURE_APPLIED } from '../store/advancedAuthoring/authoringSession.js';\nimport { readAuthoringPayload } from '../store/projectModel/authoring.js';\nimport { isReviewCurrent } from '../store/advancedExport/exportOutcome.js';\nimport { exportRevisionToken } from '../store/advancedExport/exportRequest.js';\nimport { advancedArchiveBaseName, advancedStoryTitle } from '../store/advancedExport/archiveName.js';\nimport { readAuthoringRevision } from '../store/projectModel/authoringRevision.js';\nimport { ensureExportsDir } from '../store/projectIO';\nimport { getLastExportDir, saveLastExportDir } from './useFileDialog';\nimport { KEYS, read as readSetting } from '../store/persistentSettings';\nimport { logger } from '../utils/logger';\n\n// La vue de lecture sérialise chaque champ avec sa présence :\n// absent, `null` ou valeur. Seule une valeur compte pour composer un nom.\nfunction presenceValue(field) {\n  return field?.presence === 'value' ? field.value : null;\n}\n\nexport function useAdvancedExport({\n  store,\n  authoring,\n  // La lecture du document telle que l'espace de travail la publie : titre et\n  // version. Elle sert au **nom du fichier** produit, et à rien d'autre — le\n  // document qui part reste le payload en mémoire, jamais cette vue.\n  documentInfo = null,\n  workspaceDirRef = null,\n  pickFolder = defaultFolderPicker,\n  readGraphView = (payload) => createAdvancedViewBridge().readGraphView(payload),\n} = {}) {\n  // Le seul état que ce hook tient encore : le refus prononcé **avant** que quoi\n  // que ce soit parte au moteur.\n  const [refusal, setRefusal] = useState(null);\n  // L'archive à relire, tenue **à côté** du refus : les deux ne se chassent pas.\n  const [review, setReview] = useState(null);\n  const projectRef = useRef(store.project);\n  projectRef.current = store.project;\n  // Lecteur stable de l'état courant (absent des doubles de test les plus simples).\n  const readLiveProject = store.readProject ?? null;\n  const epochRef = store.workEpochRef;\n\n  // Les collaborateurs sont lus par **ref écrite pendant le rendu**, jamais\n  // capturés dans les dépendances : la session d'édition rend un objet neuf à\n  // chaque rendu, et une préparation qui en dépendrait serait reconstruite au\n  // milieu de son propre travail.\n  const collaborators = useRef(null);\n  collaborators.current = { authoring, documentInfo };\n\n  // Le témoin du document ouvert. La file le relit au retour d'un travail\n  // graphe : une archive revenue après un changement de projet garde son\n  // fichier, mais n'est pas présentée comme le résultat du document ouvert.\n  const readTicket = useCallback(() => ({\n    projectEpoch: epochRef.current,\n    document: readAuthoringRevision(projectRef.current),\n  }), [epochRef]);\n\n  const resolveDefaultFolder = useCallback(async () => {\n    const remembered = store.savePath ? getLastExportDir() : null;\n    if (remembered) return remembered;\n    const workspace = workspaceDirRef?.current\n      || readSetting(KEYS.WORKSPACE_DIR, { defaultValue: '' });\n    if (!workspace) return undefined;\n    return (await ensureExportsDir(workspace)) || undefined;\n  }, [store.savePath, workspaceDirRef]);\n\n  const chooseFolder = useCallback(async () => {\n    const folder = await pickFolder(await resolveDefaultFolder());\n    if (folder) saveLastExportDir(folder);\n    return folder ?? null;\n  }, [pickFolder, resolveDefaultFolder]);\n\n  /**\n   * Ce qui part au moteur, capturé maintenant.\n   *\n   * L'auteur est suspendu ici et le reste jusqu'à ce que la file n'ait plus de\n   * travail graphe. La suspension\n   * n'est donc pas relâchée par ce hook en cas de succès : elle est dérivée de\n   * la file, qui est la seule à savoir quand il n'y a plus rien à attendre.\n   */\n  const prepare = useCallback(async ({ outputFolder, options }) => {\n    logger.info(`advanced:export-prepare folder='${outputFolder ?? ''}' silence=${options?.silenceMode} harmonize=${options?.harmonizeLoudness}`);\n    // La fiche du pack peut avoir écrit le projet juste avant cet appel, sans\n    // rendu intermédiaire : le ref du rendu serait alors en retard d'une écriture.\n    if (readLiveProject) projectRef.current = readLiveProject();\n    // Ce que le graphe affiche devient la disposition d'auteur, avant que\n    // l'auteur soit verrouillé : les gestes seraient refusés après.\n    const promoted = await promoteDisplayedLayout({\n      readProject: () => projectRef.current,\n      readGraphView: (project) => readGraphView(readAuthoringPayload(project)),\n      runGesture: (gesture, gestureOptions) => (\n        collaborators.current.authoring.runGesture(gesture, gestureOptions)\n      ),\n      settle: () => collaborators.current.authoring.whenIdle(),\n      applied: GESTURE_APPLIED,\n      warn: (message) => logger.warn(`advanced:export-layout ${message}`),\n    });\n    if (promoted) projectRef.current = promoted;\n    const prepared = await prepareAdvancedWork({\n      readProject: () => projectRef.current,\n      readTicket,\n      // Le nom de l'archive : les champs de nommage viennent de l'enveloppe du\n      // projet — ils ne composent que le nom du fichier et n'entrent dans aucun\n      // pack —, le titre et la version du **document**, qui en est la seule\n      // autorité.\n      readArchiveName: () => advancedArchiveBaseName({\n        packMetadata: projectRef.current?.packMetadata ?? null,\n        title: presenceValue(collaborators.current.documentInfo?.metadata?.title),\n        version: presenceValue(collaborators.current.documentInfo?.metadata?.version),\n      }),\n      // Le titre livré dans `story.json`, composé par la même règle : en\n      // convention, l'archive porte l'âge comme côté Libre ; la fiche, elle,\n      // garde le titre lisible du document.\n      readStoryTitle: () => advancedStoryTitle({\n        packMetadata: projectRef.current?.packMetadata ?? null,\n        title: presenceValue(collaborators.current.documentInfo?.metadata?.title),\n        version: presenceValue(collaborators.current.documentInfo?.metadata?.version),\n      }),\n      holdAuthoring: () => collaborators.current.authoring.hold('export'),\n      releaseAuthoring: () => collaborators.current.authoring.releaseHold(),\n      settleAuthoring: () => collaborators.current.authoring.whenIdle(),\n      outputFolder,\n      options,\n    });\n    return prepared;\n  }, [readGraphView, readTicket, readLiveProject]);\n\n  // Un refus prononcé **avant** tout appel : le parcours de production a posé\n  // ses questions, l'une d'elles a dit non, et le moteur n'a rien vu.\n  const refuseBeforeStart = useCallback((localRefusal) => {\n    logger.warn(`advanced:production-refused kind=${localRefusal?.kind ?? 'inconnu'} beforeEngine=true`);\n    setRefusal(localRefusal);\n    return true;\n  }, []);\n\n  const dismissRefusal = useCallback(() => setRefusal(null), []);\n\n  // La relecture porte sur **l'archive effectivement produite**, avec la\n  // révision qui l'a produite et le travail auquel elle appartenait. C'est ce\n  // triplet qui permet de dire, après une nouvelle édition, que la simulation\n  // n'est plus celle du document courant.\n  const openReview = useCallback((produced) => {\n    if (!produced?.zipPath) return;\n    setReview({\n      zipPath: produced.zipPath,\n      revision: produced.revision ?? null,\n      epoch: produced.epoch ?? null,\n      at: Date.now(),\n    });\n  }, []);\n\n  const closeReview = useCallback(() => setReview(null), []);\n\n  // L'empreinte de la sortie inclut les liaisons et le nom du projet : un\n  // remplacement média ou un nouveau titre de secours périme l'archive relue.\n  const currentRevision = exportRevisionToken(store.project);\n  const currentEpoch = epochRef.current;\n\n  const reviewView = useMemo(() => review && {\n    ...review,\n    isCurrentRevision: isReviewCurrent(review, { revision: currentRevision, epoch: currentEpoch }),\n  }, [review, currentRevision, currentEpoch]);\n\n  return {\n    prepare,\n    chooseFolder,\n    readTicket,\n    refusal,\n    refuseBeforeStart,\n    dismissRefusal,\n    review: reviewView,\n    openReview,\n    closeReview,\n  };\n}\n\nasync function defaultFolderPicker(defaultPath) {\n  return openDialog({\n    directory: true,\n    multiple: false,\n    title: 'Dossier de sortie du pack',\n    defaultPath,\n  });\n}\n",
 "src/store/advancedExport/displayedLayout.js": "// À l'export, la disposition affichée devient la disposition d'auteur.\n//\n// Un nœud créé dans l'éditeur porte une position d'éditeur, et un nœud créé\n// sans point désigné n'en porte aucune : le graphe les montre, mais le document\n// ne les contient pas, et l'archive partait sans elles. Rouvert dans STUdio, le\n// pack s'empilait ; rouvert par « Modifier un pack », il était rangé à neuf. Ce\n// que l'auteur voit est ce qui part, et le projet garde ces positions comme les\n// siennes.\n//\n// Ce module choisit **quoi** promouvoir, sans framework ni Tauri. La promotion\n// passe par les deux gestes existants — `apply-view-layout`, puis\n// `apply-layout-to-authoring` —, la seule porte admise vers les positions\n// d'auteur.\n\nimport { SHORT_MAX, SHORT_MIN } from '../advancedGraphView/graphGeometry.js';\nimport { advancedGestures } from '../projectModel/advancedGestures.js';\n\nfunction shortInteger(value) {\n  const rounded = Math.round(Number.isFinite(value) ? value : 0);\n  return Math.min(SHORT_MAX, Math.max(SHORT_MIN, rounded));\n}\n\n// Les nœuds dont la position affichée n'est pas encore une position d'auteur,\n// avec cette position en entiers du domaine d'auteur. Un nœud à identifiant\n// dupliqué n'est adressable par aucun geste : il est laissé tel quel.\nexport function displayedLayoutToPromote(view) {\n  const nodes = [\n    ...(view?.stages ?? []).map((node) => ({ kind: 'stage', id: node.uuid, node })),\n    ...(view?.actions ?? []).map((node) => ({ kind: 'action', id: node.id, node })),\n  ];\n  return nodes\n    .filter(({ node }) => node.uniqueId !== false && node.layout && node.layout.source !== 'authored')\n    .map(({ kind, id, node }) => ({\n      node: { kind, id },\n      position: { x: shortInteger(node.layout.x), y: shortInteger(node.layout.y) },\n    }));\n}\n\n// Les gestes de la promotion, ou aucun s'il n'y a rien à promouvoir. La\n// politique de bornes est `refuse` : les positions sont déjà ramenées dans le\n// domaine, elle ne peut donc pas se déclencher.\nexport function displayedLayoutGestures(view) {\n  const entries = displayedLayoutToPromote(view);\n  if (entries.length === 0) return [];\n  return [\n    advancedGestures.applyViewLayout(entries),\n    advancedGestures.applyLayoutToAuthoring(entries.map((entry) => entry.node), 'refuse'),\n  ];\n}\n\n// La promotion complète, juste avant que l'export verrouille l'auteur.\n//\n// Rend le projet promu, ou `null` si rien n'a changé. L'appelant **doit**\n// capturer ce projet-là : l'état de rendu ne le montre qu'au rendu suivant,\n// et capturer l'ancien ferait partir l'archive sans les positions promues.\n// Un échec ne bloque pas l'export — le pack part comme avant, et le journal le\n// dit.\nexport async function promoteDisplayedLayout({\n  readProject,\n  readGraphView,\n  runGesture,\n  settle = async () => {},\n  applied,\n  warn = () => {},\n}) {\n  await settle();\n  let gestures;\n  try {\n    gestures = displayedLayoutGestures(await readGraphView(readProject()));\n  } catch (error) {\n    warn(`lecture de la disposition impossible : ${String(error?.message ?? error)}`);\n    return null;\n  }\n  let project = null;\n  for (const gesture of gestures) {\n    // Hors historique : l'affichage ne change pas, un Ctrl+Z n'aurait rien à\n    // montrer.\n    const outcome = await runGesture(gesture, { history: false });\n    if (outcome?.status !== applied) {\n      warn(`${gesture.gesture} non appliqué (${outcome?.status ?? 'inconnu'})`);\n      return null;\n    }\n    project = outcome.project ?? project;\n  }\n  return project;\n}\n",
 "src/store/advancedExport/exportOutcome.js": "import { presentUserMessage } from '../../i18n/userMessage.js';\n// Ce que l'export rend, et ce qu'un refus dit — sans jamais lire une phrase.\n//\n// Tous les refus de `export_advanced_pack` portent un `kind`, et les refus de\n// préparation un second `kind` dans `error`. La règle est de « brancher le\n// sous-type, pas une recherche de mots dans le message ». Ce module ne contient\n// donc aucune analyse de texte ; `message` et `detail` sont des **données**\n// affichées telles quelles.\n//\n// Deux pièges nommés par le plan sont tenus ici plutôt que dans l'interface,\n// pour qu'un test pur puisse les éprouver :\n//\n// - un `output-write` **reste** un `output-write` même si l'auteur venait de\n//   demander l'annulation : le nettoyage d'un `.partial` qui échoue emprunte\n//   exactement cette branche, et le présenter comme une simple annulation\n//   masquerait un résidu sur le disque ;\n// - un dossier créé par le préflight n'est pas une archive publiée. La promesse\n//   du writer est l'absence d'archive avant validation, pas l'absence de\n//   dossier.\n\nexport const EXPORT_REFUSAL = Object.freeze({\n  PAYLOAD_DECODE: 'payload-decode',\n  PREPARATION: 'preparation',\n  MEDIA_UNAVAILABLE: 'media-unavailable',\n  ARCHIVE_NAME_COLLISION: 'archive-name-collision',\n  MEDIA_ORACLE: 'media-oracle',\n  CANCELLED: 'export-cancelled',\n  OUTPUT_WRITE: 'output-write',\n  // Hors des refus typés : ce qui n'est pas un refus — une rupture de transport,\n  // une panique. Il est nommé plutôt que rangé de force dans une des sept\n  // familles, parce qu'un diagnostic faux vaut moins qu'un diagnostic absent.\n  UNTYPED: 'untyped',\n  // Refus **local**, avant tout appel : pas de document d'auteur, pas de\n  // dossier choisi. Le moteur n'a rien vu, et le dire évite de laisser croire\n  // qu'il a refusé.\n  REQUEST: 'request',\n});\n\nexport const PREPARATION_REFUSAL = Object.freeze({\n  GRAPH_INTEGRITY: 'graph-integrity',\n  AUTHORING_ACTION_REQUIRED: 'authoring-action-required',\n  PACK_IDENTITY: 'pack-identity',\n  READINESS_BLOCKED: 'readiness-blocked',\n  STANDARD_SERIALIZATION: 'standard-serialization',\n});\n\nconst REFUSAL_TITLES = Object.freeze({\n  [EXPORT_REFUSAL.PAYLOAD_DECODE]: 'Document illisible',\n  [EXPORT_REFUSAL.PREPARATION]: 'Préparation refusée',\n  [EXPORT_REFUSAL.MEDIA_UNAVAILABLE]: 'Médias indisponibles',\n  [EXPORT_REFUSAL.ARCHIVE_NAME_COLLISION]: \"Collision de noms dans l'archive\",\n  [EXPORT_REFUSAL.MEDIA_ORACLE]: 'Rattachement des médias en désaccord',\n  [EXPORT_REFUSAL.CANCELLED]: 'Export annulé',\n  [EXPORT_REFUSAL.OUTPUT_WRITE]: 'Écriture impossible',\n  [EXPORT_REFUSAL.UNTYPED]: 'Export interrompu',\n  [EXPORT_REFUSAL.REQUEST]: 'Export impossible',\n});\n\nconst PREPARATION_TITLES = Object.freeze({\n  [PREPARATION_REFUSAL.GRAPH_INTEGRITY]: 'Intégrité du graphe',\n  [PREPARATION_REFUSAL.AUTHORING_ACTION_REQUIRED]: \"Décision d'auteur requise\",\n  [PREPARATION_REFUSAL.PACK_IDENTITY]: 'Identité du pack',\n  [PREPARATION_REFUSAL.READINESS_BLOCKED]: \"Qualification d'export bloquée\",\n  [PREPARATION_REFUSAL.STANDARD_SERIALIZATION]: 'Sérialisation du document',\n});\n\nconst MEDIA_CAUSE_LABELS = Object.freeze({\n  'binding-absent': 'aucune liaison enregistrée pour cette référence',\n  'path-null': 'liaison sans chemin : le fichier doit être choisi par référence',\n  'not-found': 'fichier introuvable au chemin enregistré',\n  'not-regular': \"le chemin ne désigne pas un fichier régulier\",\n  'read-denied': 'lecture refusée par le système',\n  empty: 'fichier vide',\n  undecodable: 'contenu non décodable',\n  // Un décodage partiel puis échoué emprunte cette cause. Ce n'est pas la\n  // preuve que l'auteur a fourni un fichier volontairement invalide.\n  'validation-failed': 'le fichier a été rejeté par la validation',\n  'tool-unavailable': \"l'outil de conversion n'est pas disponible\",\n  'tool-interrupted': \"l'outil de conversion a été interrompu\",\n  'processing-failed': 'la conversion a échoué',\n});\n\nconst TRANSFORMATION_LABELS = Object.freeze({\n  verbatim: 'copié tel quel',\n  renamed: 'renommé pour le paquet',\n  reencoded: 'ré-encodé pour le paquet',\n  resized: 'redimensionné pour le paquet',\n});\n\nconst MEDIA_FIELD_LABELS = Object.freeze({ image: 'image', audio: 'audio' });\n\n// `path-null` exige une sélection **par référence** : il n'y a pas d'ancien\n// chemin à retrouver. L'interface s'en sert pour offrir la bonne réparation.\nexport function repairByReferenceOnly(entry) {\n  return entry?.cause === 'path-null' || entry?.cause === 'binding-absent';\n}\n\nfunction asList(value) {\n  return Array.isArray(value) ? value : [];\n}\n\n// Le refus, tel qu'il est affichable. `kind` et `preparationKind` sont les deux\n// seules valeurs sur lesquelles l'interface se branche.\nexport function classifyExportRefusal(error) {\n  const kind = typeof error?.kind === 'string' ? error.kind : null;\n  if (kind === null) {\n    return {\n      kind: EXPORT_REFUSAL.UNTYPED,\n      preparationKind: null,\n      title: REFUSAL_TITLES[EXPORT_REFUSAL.UNTYPED],\n      // Un refus non typé n'est pas rangé dans `export-cancelled` : l'auteur\n      // doit voir qu'il n'a pas reçu de diagnostic contractuel.\n      message: presentUserMessage(error).message,\n      cancelled: false,\n      residue: false,\n      entries: [],\n      conflicts: [],\n      disagreements: [],\n      diagnostics: [],\n      integrityErrors: [],\n      path: null,\n      codecError: null,\n    };\n  }\n\n  const preparationKind = kind === EXPORT_REFUSAL.PREPARATION\n    ? (typeof error.error?.kind === 'string' ? error.error.kind : null)\n    : null;\n\n  return {\n    kind,\n    preparationKind,\n    title: preparationKind\n      ? `${REFUSAL_TITLES[kind] ?? kind} — ${PREPARATION_TITLES[preparationKind] ?? preparationKind}`\n      : (REFUSAL_TITLES[kind] ?? kind),\n    message: kind === EXPORT_REFUSAL.OUTPUT_WRITE\n      ? presentUserMessage(error.message ?? '').message\n      : presentUserMessage(error.error?.message ?? error.message ?? '').message,\n    // Seul `export-cancelled` est une annulation. Un `output-write` survenu\n    // pendant un abandon reste une panne d'écriture : c'est la branche du\n    // nettoyage `.partial`.\n    cancelled: kind === EXPORT_REFUSAL.CANCELLED,\n    residue: kind === EXPORT_REFUSAL.OUTPUT_WRITE,\n    entries: kind === EXPORT_REFUSAL.MEDIA_UNAVAILABLE ? asList(error.entries) : [],\n    conflicts: kind === EXPORT_REFUSAL.ARCHIVE_NAME_COLLISION ? asList(error.conflicts) : [],\n    disagreements: kind === EXPORT_REFUSAL.MEDIA_ORACLE ? asList(error.disagreements) : [],\n    diagnostics: asList(error.error?.diagnostics),\n    integrityErrors: asList(error.error?.errors),\n    path: kind === EXPORT_REFUSAL.OUTPUT_WRITE ? (error.path ?? null) : null,\n    codecError: kind === EXPORT_REFUSAL.PAYLOAD_DECODE ? (error.error ?? null) : null,\n  };\n}\n\n// Les médias indisponibles, groupés par référence : la même référence peut\n// servir plusieurs écrans, et l'auteur répare **une** liaison, pas une par\n// écran. Tous les écrans concernés restent listés : la liste est complète,\n// pas un échantillon.\nexport function groupUnavailableMedia(entries) {\n  const byRef = new Map();\n  for (const entry of asList(entries)) {\n    const key = entry?.assetRef ?? '';\n    const existing = byRef.get(key);\n    if (existing) {\n      existing.stageIds = [...new Set([...existing.stageIds, ...asList(entry.stageIds)])];\n      existing.fields = [...new Set([...existing.fields, entry.field].filter(Boolean))];\n      continue;\n    }\n    byRef.set(key, {\n      assetRef: key,\n      fields: [entry?.field].filter(Boolean),\n      stageIds: [...asList(entry?.stageIds)],\n      lastKnownPath: entry?.lastKnownPath ?? null,\n      cause: entry?.cause ?? null,\n      causeLabel: MEDIA_CAUSE_LABELS[entry?.cause] ?? entry?.cause ?? 'cause inconnue',\n      detail: entry?.detail ?? '',\n      byReferenceOnly: repairByReferenceOnly(entry),\n    });\n  }\n  return [...byRef.values()];\n}\n\nexport function mediaFieldLabel(field) {\n  return MEDIA_FIELD_LABELS[field] ?? field ?? 'média';\n}\n\n// La relecture porte-t-elle encore sur le document ouvert ?\n//\n// Deux conditions, et aucune n'est un compteur : l'archive a été produite pour\n// **cette** révision — payload et liaisons, jamais le payload seul — et pour\n// **ce** travail. Comparer des valeurs est ce qui permet à un undo de rendre\n// l'archive courante à nouveau ; un jeton croissant l'interdirait.\n//\n// Sans révision connue des deux côtés, la réponse est « non » : une relecture\n// dont on ne sait pas à quoi elle correspond ne doit pas être présentée comme\n// celle du document ouvert.\nexport function isReviewCurrent(review, current) {\n  const produced = review?.revision ?? null;\n  const open = current?.revision ?? null;\n  if (produced === null || open === null) return false;\n  return produced === open && (review.epoch ?? null) === (current.epoch ?? null);\n}\n\n// Le succès, tel qu'il est affichable.\n//\n// Les empreintes (`snapshotSha256`, `outputSha256`, `taskKey`) restent dans les\n// lignes brutes, accessibles pour un diagnostic, et **ne sont pas** remontées\n// dans le résumé : le plan interdit de les afficher dans le parcours principal.\nexport function summarizeExportSuccess(result) {\n  const conversions = asList(result?.conversions);\n  const byTransformation = new Map();\n  for (const line of conversions) {\n    const key = line?.transformation ?? 'verbatim';\n    byTransformation.set(key, (byTransformation.get(key) ?? 0) + 1);\n  }\n  return {\n    zipPath: result?.zipPath ?? null,\n    packIdentity: result?.packIdentity ?? null,\n    assetCount: conversions.length,\n    transformations: [...byTransformation.entries()]\n      .map(([transformation, count]) => ({\n        transformation,\n        count,\n        label: TRANSFORMATION_LABELS[transformation] ?? transformation,\n      }))\n      .sort((left, right) => left.transformation.localeCompare(right.transformation)),\n    // Une conversion a eu lieu dès qu'une ligne n'est pas `verbatim`. C'est ce\n    // qui déclenche l'explication D-01 : les fichiers de travail restent\n    // intacts, et l'harmonisation des volumes est un réglage distinct.\n    converted: conversions.some((line) => line?.transformation && line.transformation !== 'verbatim'),\n    deduplicated: conversions.filter((line) => line?.deduplicatedWith).length,\n    // Les avertissements d'harmonisation ont la forme de ceux de l'éditeur par\n    // menus — message et mesures — et se lisent au même endroit. Les autres\n    // (un nettoyage de dossier temporaire qui échoue) restent des phrases.\n    warnings: [...asList(result?.audioWarnings), ...asList(result?.warnings)],\n    // `false` est un succès normal quand l'écran d'entrée n'a pas d'image.\n    hasThumbnail: result?.hasThumbnail === true,\n    conversions,\n    destinations: asList(result?.destinations),\n  };\n}\n",
 "src/store/advancedExport/exportReadiness.js": "import { presentUserMessage } from '../../i18n/userMessage.js';\n// La readiness, lue en deux informations qui ne se confondent pas.\n//\n// `SUPPORTED` ne veut pas dire export autorisé : un document peut avoir toutes\n// ses dimensions supportées et une décision d'auteur bloquante. Ce module\n// sépare donc :\n//\n// - **le blocage**, dont `blocked` est l'unique autorité. Il vient de Rust, et\n//   rien ici ne le recalcule, ne l'assouplit ni ne le durcit ;\n// - **la qualification**, `interoperability` et ses dimensions, qui dit ce que\n//   ce document a de qualifié — et où la qualification n'a pas pu être\n//   observée.\n//\n// Le classement des diagnostics par niveau est un **miroir d'affichage** de\n// `ReadinessDiagnostic::level()` : il sert à mettre en tête ce qui bloque, et\n// rien d'autre. Il ne décide jamais si l'export part — la commande d'export\n// refait ses propres vérifications et reste l'autorité, comme le plan l'exige.\n// Un écart entre ce classement et `blocked` est un défaut d'affichage, pas une\n// permission accordée ou retirée.\n\nconst READINESS_SOURCE = Object.freeze({\n  DECODE: 'decode',\n  GRAPH_INTEGRITY: 'graph-integrity',\n  AUTHORING: 'authoring',\n  READINESS: 'readiness',\n});\n\nexport const READINESS_LEVEL = Object.freeze({\n  INFO: 'INFO',\n  WARNING: 'WARNING',\n  ACTION_REQUIRED: 'ACTION_REQUIRED',\n  ERROR: 'ERROR',\n});\n\nconst QUALIFICATION = Object.freeze({\n  UNTESTED: 'UNTESTED',\n  PREPARED: 'PREPARED',\n  SUPPORTED: 'SUPPORTED',\n});\n\nconst QUALIFICATION_LABELS = Object.freeze({\n  UNTESTED: 'non qualifié',\n  PREPARED: 'préparé',\n  SUPPORTED: 'supporté',\n});\n\nconst SOURCE_LABELS = Object.freeze({\n  decode: 'décodage',\n  'graph-integrity': 'intégrité du graphe',\n  authoring: \"décision d'auteur\",\n  readiness: 'qualification',\n});\n\nconst LEVEL_LABELS = Object.freeze({\n  INFO: 'information',\n  WARNING: 'avertissement',\n  ACTION_REQUIRED: 'décision requise',\n  ERROR: 'erreur',\n});\n\n// Le niveau d'un diagnostic, tel que chaque source le sérialise. `graph-integrity`\n// n'en porte pas : Rust le fixe à `Error` dans `level()`, et cette absence est\n// la seule valeur déduite ici.\nexport function readinessDiagnosticLevel(diagnostic) {\n  switch (diagnostic?.source) {\n    case READINESS_SOURCE.DECODE:\n      return diagnostic.severity === 'ERROR' ? READINESS_LEVEL.ERROR : READINESS_LEVEL.WARNING;\n    case READINESS_SOURCE.GRAPH_INTEGRITY:\n      return READINESS_LEVEL.ERROR;\n    case READINESS_SOURCE.AUTHORING:\n    case READINESS_SOURCE.READINESS:\n      return diagnostic.level ?? READINESS_LEVEL.INFO;\n    default:\n      return READINESS_LEVEL.INFO;\n  }\n}\n\nfunction readinessLevelLabel(level) {\n  return LEVEL_LABELS[level] ?? level;\n}\n\nfunction blocksDisplay(level) {\n  return level === READINESS_LEVEL.ERROR || level === READINESS_LEVEL.ACTION_REQUIRED;\n}\n\nfunction codeOf(diagnostic) {\n  return typeof diagnostic?.code === 'string' ? diagnostic.code : String(diagnostic?.code ?? '');\n}\n\n// La readiness rendue affichable. `blocked` est recopié tel quel : c'est le\n// seul champ sur lequel l'interface a le droit de conclure « export refusé ».\nexport function summarizeReadiness(readiness) {\n  if (!readiness) return null;\n  const diagnostics = Array.isArray(readiness.diagnostics) ? readiness.diagnostics : [];\n  const rows = diagnostics.map((diagnostic) => {\n    const level = readinessDiagnosticLevel(diagnostic);\n    return {\n      source: diagnostic?.source ?? null,\n      sourceLabel: SOURCE_LABELS[diagnostic?.source] ?? diagnostic?.source ?? 'diagnostic',\n      code: codeOf(diagnostic),\n      path: diagnostic?.path ?? '',\n      message: presentUserMessage(diagnostic).message,\n      level,\n      levelLabel: readinessLevelLabel(level),\n      blocking: blocksDisplay(level),\n      resolutions: Array.isArray(diagnostic?.resolutions) ? diagnostic.resolutions : [],\n    };\n  });\n\n  const dimensions = Array.isArray(readiness.dimensions) ? readiness.dimensions : [];\n  const unevaluated = Array.isArray(readiness.unevaluated) ? readiness.unevaluated : [];\n\n  return {\n    blocked: readiness.blocked === true,\n    interoperability: readiness.interoperability ?? QUALIFICATION.UNTESTED,\n    interoperabilityLabel: QUALIFICATION_LABELS[readiness.interoperability]\n      ?? readiness.interoperability\n      ?? QUALIFICATION_LABELS.UNTESTED,\n    // Les blocages d'abord, dans l'ordre où Rust les a rendus : l'ordre\n    // rendu est une information, le réordonner par sévérité perdrait le lien\n    // avec lui.\n    blocking: rows.filter((row) => row.blocking),\n    advisory: rows.filter((row) => !row.blocking),\n    diagnostics: rows,\n    dimensions: dimensions.map((dimension) => ({\n      id: dimension?.id ?? '',\n      qualification: dimension?.qualification ?? QUALIFICATION.UNTESTED,\n      qualificationLabel: QUALIFICATION_LABELS[dimension?.qualification] ?? dimension?.qualification,\n      evidence: Array.isArray(dimension?.evidence) ? dimension.evidence : [],\n    })),\n    // `UNTESTED` est une limite de qualification, pas un document invalide :\n    // ces dimensions sont montrées comme « non observées », jamais comme des\n    // erreurs.\n    unevaluated: unevaluated.map((dimension) => ({\n      id: dimension?.id ?? '',\n      reason: dimension?.reason ?? '',\n      lines: Array.isArray(dimension?.lines) ? dimension.lines : [],\n    })),\n  };\n}\n",
 "src/store/advancedExport/exportRequest.js": "// Ce qui part à `export_advanced_pack`, et d'où ça vient.\n//\n// Deux règles se tiennent ici, à l'écart de React :\n//\n// 1. **Le payload courant en mémoire**, jamais une sauvegarde ni une readiness\n//    mémorisée. L'export est associé à la révision que l'auteur regarde ; la\n//    demande porte donc le document et ses liaisons **du même projet**, pris\n//    ensemble.\n// 2. **Les défauts du Libre.** Sans choix explicite, les silences sont\n//    ajustés et les volumes harmonisés, comme dans le Libre : les deux chaînes\n//    ne donnent pas deux recommandations opposées pour le même geste. Les\n//    valeurs restent envoyées explicitement, alors même que le `Default` de\n//    Rust vaut `off` : le choix est ainsi lisible dans le journal comme dans\n//    les tests.\n//\n//    Conséquence assumée, et c'est elle qui se vérifie à l'oreille : un projet\n//    graphe dont l'auteur ne touche à rien voit désormais ses sons mesurés et\n//    ré-encodés, là où le moteur les recopiait à l'octet.\n//\n// La demande porte aussi le **nom de l'archive**, composé par\n// `archiveName.js` — exactement comme la chaîne Libre transporte son\n// `name: getExportPackName(packMetadata)`. Le vide n'est pas transmis : le\n// moteur retombe alors sur le titre du document.\n\nimport { DEFAULT_PACK_AUDIO_PROCESSING, PACK_SILENCE_MODES } from '../../config/audioProcessing.js';\nimport { readAuthoringPayload } from '../projectModel/authoring.js';\nimport { authoringRevisionOf } from '../projectModel/authoringRevision.js';\nimport { readMediaBindings } from '../projectModel/mediaBindings.js';\n\n// Réexport de la liste unique : les trois modes sont une propriété du pack,\n// pas de cette chaîne, et une seconde copie finirait par diverger.\nconst SILENCE_MODES = PACK_SILENCE_MODES;\n\n// Les défauts du tiroir, lus à la source unique plutôt que recopiés : le\n// tiroir affiche `readPackAudioProcessing`, la demande envoie la même chose, et\n// aucun écart ne peut s'installer entre ce qui est montré et ce qui part.\nexport const DEFAULT_EXPORT_AUDIO_OPTIONS = Object.freeze({\n  ...DEFAULT_PACK_AUDIO_PROCESSING,\n});\n\nexport class ExportRequestError extends Error {\n  constructor(code, message) {\n    super(message);\n    this.name = 'ExportRequestError';\n    this.code = code;\n  }\n}\n\nfunction normalizeAudioOptions(options) {\n  const silenceMode = SILENCE_MODES.includes(options?.silenceMode)\n    ? options.silenceMode\n    : DEFAULT_EXPORT_AUDIO_OPTIONS.silenceMode;\n  // L'absence de choix vaut le défaut commun, jamais `false` : un appelant qui\n  // ne dit rien demande ce que le tiroir affiche, pas le contraire.\n  const harmonizeLoudness = options?.harmonizeLoudness === undefined\n    ? DEFAULT_EXPORT_AUDIO_OPTIONS.harmonizeLoudness\n    : options.harmonizeLoudness === true;\n  const request = { silenceMode, harmonizeLoudness };\n  // Les durées ne sont transmises que là où elles s'appliquent : en mode `off`,\n  // Rust les ignore, et les envoyer laisserait croire à un réglage actif.\n  if (silenceMode !== 'off') {\n    if (Number.isFinite(options?.leadingSilenceSec)) request.leadingSilenceSec = options.leadingSilenceSec;\n    if (Number.isFinite(options?.trailingSilenceSec)) request.trailingSilenceSec = options.trailingSilenceSec;\n  }\n  return request;\n}\n\nfunction projectNameOf(projectName) {\n  return typeof projectName === 'string' ? projectName.trim() : '';\n}\n\n// La demande complète, prête à passer l'IPC. Elle est construite en **un seul\n// point** depuis le projet, ce qui interdit structurellement d'assembler le\n// payload d'une révision avec les liaisons d'une autre.\nexport function buildExportRequest({\n  project, outputFolder, options, archiveName = null, storyTitle = null,\n} = {}) {\n  const payload = readAuthoringPayload(project);\n  if (payload === null) {\n    throw new ExportRequestError(\n      'ADVANCED_PAYLOAD_REQUIRED',\n      \"Ce projet ne porte pas de document d'auteur avancé : il n'y a rien à exporter.\",\n    );\n  }\n  const folder = typeof outputFolder === 'string' ? outputFolder.trim() : '';\n  if (folder.length === 0) {\n    throw new ExportRequestError('OUTPUT_FOLDER_REQUIRED', 'Aucun dossier de sortie choisi.');\n  }\n  const archive = typeof archiveName === 'string' ? archiveName.trim() : '';\n  // Le titre livré dans `story.json` : le nom de convention, comme la chaîne\n  // Libre l'écrit. Vide en nom libre — le moteur garde le titre du document.\n  const delivered = typeof storyTitle === 'string' ? storyTitle.trim() : '';\n  // Le nom du projet sert de titre de secours dans le contenu du ZIP quand le\n  // document n'en porte pas. Il ne remplace jamais un titre saisi par l'auteur.\n  const projectName = projectNameOf(project?.projectName);\n  // La vignette catalogue est un média d'**enveloppe**, comme côté Libre : elle\n  // n'est ni une référence du document ni une liaison, donc ni `payload` ni\n  // `mediaBindings` ne la portent. Elle voyage comme `archiveName`, par la même\n  // frontière, et son absence laisse le moteur sur son repli — l'image de\n  // l'Écran d'entrée, qui était le comportement d'origine.\n  const cover = typeof project?.thumbnailImage === 'string' ? project.thumbnailImage.trim() : '';\n  return {\n    payload,\n    mediaBindings: readMediaBindings(project),\n    outputFolder: folder,\n    options: normalizeAudioOptions(options),\n    // Omis quand il est vide, pas envoyé vide : une chaîne vide se lirait comme\n    // « l'auteur a demandé un nom vide », alors qu'elle veut dire « il n'a rien\n    // demandé ».\n    ...(archive ? { archiveName: archive } : {}),\n    ...(delivered ? { storyTitle: delivered } : {}),\n    ...(projectName ? { projectName } : {}),\n    ...(cover ? { coverImage: cover } : {}),\n  };\n}\n\n// Le témoin de révision d'un export : payload et liaisons comparés à l'octet,\n// nom du projet comparé après le même nettoyage que la demande. Il permet de\n// dire plus tard\n// « cette archive est celle de cette révision » sans ouvrir le payload, et donc\n// de ne pas présenter une relecture comme celle du document courant après une\n// nouvelle édition.\n//\n// Les liaisons en font partie : un remplacement média change le fichier que\n// l'archive contient sans toucher au payload, et un témoin réduit au payload\n// affirmait encore que l'ancien ZIP correspondait au document ouvert. Le nom du\n// projet entre aussi dans la copie quand aucun titre d'auteur n'est disponible.\nexport function exportRequestRevision({ payload, mediaBindings, projectName } = {}) {\n  const document = authoringRevisionOf({ payload, mediaBindings });\n  if (document === null) return null;\n  const name = projectNameOf(projectName);\n  return `${document}#${name.length}:${name}`;\n}\n\nexport function exportRevisionToken(project) {\n  return exportRequestRevision({\n    payload: readAuthoringPayload(project),\n    mediaBindings: readMediaBindings(project),\n    projectName: project?.projectName,\n  });\n}\n",
 "src/store/packIdentityCheck.js": "import { presentUserMessage } from '../i18n/userMessage.js';\n// Le seul contrôle posé sur l'UUID choisi dans la fiche du pack : les passerelles\n// savent-elles le lire ? La règle est tenue par Rust (`check_pack_identity`),\n// celle-là même que l'export applique : une saisie acceptée ici n'est jamais\n// refusée au moment de produire. Aucun avertissement d'une autre nature.\n//\n// `invoke` est reçu en paramètre pour que la décision se teste sans Tauri.\n\n// Rend le motif du refus, prêt à afficher, ou `null` si l'UUID convient.\nexport async function packIdentityRefusal(value, invoke) {\n  try {\n    await invoke('check_pack_identity', { value: String(value ?? '') });\n    return null;\n  } catch (error) {\n    const reason = presentUserMessage(error).message.trim()\n      || \"L'UUID du pack n'a pas pu être vérifié.\";\n    return `${reason} En saisir un autre, ou en générer un nouveau.`;\n  }\n}\n",
 "src/store/projectValidation.js": "import { presentImportWarning } from '../i18n/importWarnings.js';\n// Validation projet cote frontend.\n//\n// Contrat partage avec Rust : src-tauri/src/domain/validation.rs#validate_project_for_generation.\n// Les regles \"structurelles\" doivent rester miroirs ; le test de parite\n// scripts/validationParity.test.mjs + le module #[cfg(test)] de validation.rs ancrent\n// 4 cas canoniques (pack valide, story sans audio, pack vide, simple sans audio racine).\n//\n// Regles partagees JS <-> Rust (toute divergence est un bug a corriger):\n//   - Audio racine obligatoire (rootAudio).\n//   - Image racine obligatoire ; sans vignette propre, le catalogue la reprend.\n//   - Story : audio obligatoire, accessibilite disque verifiee.\n//   - Story : itemImage obligatoire, itemAudio obligatoire sauf titre explicite silencieux.\n//   - Zip : zipPath obligatoire et fichier accessible.\n//   - Pack non-vide : au moins une histoire jouable.\n//   - Cibles de navigation cassees (returnAfterPlay, returnOnHome, refs, sequences,\n//     destinations du message de fin global).\n//   - Regles d'activite (native_pack/canonical.rs) : un champ que le reglage courant\n//     rend inutile (fin locale sous Auto-next, image d'un Ecran transparent, message\n//     de fin global qu'aucune histoire n'emprunte) n'est ni exige ni verifie.\n//\n// Regles UX uniquement (cote JS, signalees a l'utilisateur en temps reel) :\n//   - \"duplicateId\" : doublons d'ID dans rootEntries. Rust ne controle pas\n//     (la generation cree des ids assainis distincts).\n//   - \"rootReservedId\" : ID 'root' reserve. Rust applique implicitement.\n//   - emptyMenu / emptyPack : warnings JS, Rust refuse via \"aucune histoire\".\n//   - \"storyWithoutExit\" : histoire dont l'écran de lecture n'a ni OK, ni lecture\n//     automatique, ni Accueil. Rust refuse a la generation (native_pack/port_rules.rs) ;\n//     seule cette forme est realisable depuis la fiche d'une histoire\n//     (native_pack/tests/menu_endings.rs), les autres fins sont normalisees.\n//\n// Si une regle est ajoutee : l'implementer des deux cotes, etendre\n// validation-projects.json + le module tests::parity_* de Rust.\n//\n// Taxonomie UI actuelle :\n//   - aucune issue bloquante/warning -> \"Pack prêt\" ;\n//   - status \"error\" ou \"warning\" -> \"À corriger\".\n// Les deux statuts empechent aujourd'hui la generation cote React\n// (voir App.jsx/canGenerate et getGenerateErrors). La distinction interne\n// reste utile pour diagnostiquer les erreurs structurelles, mais elle n'est\n// pas exposee comme deux categories dans l'UI parent.\n\nimport { buildProjectIndex, getPlayableDescendantCount, visitProjectEntries } from './projectModel.js';\nimport { decodeNavigationMenuId, decodeNavigationStoryId, isCurrentMenuNavigationTarget, isNextStoryNavigationTarget, isRootNavigationTarget, isStoryHomeStepNavigationTarget, isStoryNavigationTarget, normalizeNavigationTarget } from './navigationTargets.js';\nimport { VALIDATION_MESSAGES, brokenField, emptyTarget, missingField, missingTarget, validationLabel } from './validationMessages.js';\nimport { isStorySelectionAudioRequired } from './storyTitleStage.js';\nimport { isEndHomeStepActive, isEndPromptActive, isEndSequenceActive, projectReachesEndNode } from './generatedNavigation.js';\nimport { getGeneratedStoryPlayControls } from './generatedPlayback.js';\n\nfunction hasPath(value) {\n  return typeof value === 'string' && value.trim().length > 0;\n}\n\nfunction isBrokenPath(value, fileAudit = {}) {\n  return hasPath(value) && fileAudit[value] === false;\n}\n\nfunction labelOrFallback(value, fallback) {\n  return (value || '').trim() || fallback;\n}\n\n// status === 'error'   → vraie erreur structurelle (référence cassée, donnée corrompue)\n// status === 'warning' → projet en construction (champ manquant, fichier introuvable, contenu vide)\n// Les deux bloquent la génération ; seule la couleur d'affichage diffère.\nfunction pushError(issues, id, text) {\n  issues.push({ id, status: 'error', text });\n}\n\nfunction pushWarning(issues, id, text) {\n  issues.push({ id, status: 'warning', text });\n}\n\nfunction collectProjectGraphStats(projectIndex) {\n  return {\n    entryIdCounts: projectIndex.entryIdCounts,\n    menuMap: new Map(projectIndex.menuEntries.map((entry) => [entry.id, entry])),\n    firstSimpleStory: projectIndex.firstSimpleStory,\n    rootPlayableCount: projectIndex.rootPlayableCount,\n  };\n}\n\n// `navigation` : les dossiers existants et le projet, dont les réglages\n// décident quelles réactions Accueil le constructeur construit.\nfunction validateNavigationTarget(issues, id, label, target, projectIndex, navigation) {\n  const normalized = normalizeNavigationTarget(target);\n  if (!normalized) return;\n  if (isRootNavigationTarget(normalized) || isCurrentMenuNavigationTarget(normalized) || isNextStoryNavigationTarget(normalized)) {\n    return;\n  }\n  if (isStoryNavigationTarget(normalized)) {\n    const storyId = decodeNavigationStoryId(normalized);\n    const entry = storyId ? projectIndex.entryById.get(storyId) : null;\n    if (!entry || entry.type !== 'story') {\n      pushError(issues, id, missingTarget(label, 'histoire'));\n    } else if (\n      isStoryHomeStepNavigationTarget(normalized)\n      && !(entry.afterPlaybackHomeStep && isEndHomeStepActive(entry, navigation.project))\n    ) {\n      // « Retour de fin » ne vise qu'une réaction que le constructeur construit.\n      pushError(issues, id, VALIDATION_MESSAGES.storyReturnLost(label));\n    }\n    return;\n  }\n  const menuId = decodeNavigationMenuId(normalized);\n  if (!menuId || !navigation.menuIds.has(menuId)) {\n    pushError(issues, id, missingTarget(label, 'dossier'));\n  } else if (getPlayableDescendantCount(projectIndex, menuId) === 0) {\n    pushError(issues, id, emptyTarget(label, 'dossier'));\n  }\n}\n\nfunction validateStorySelectionItem(issues, item, fallbackName, fileAudit, project) {\n  const name = labelOrFallback(item?.name, fallbackName);\n  const itemId = item?.id ?? null;\n  const selectionAudioRequired = isStorySelectionAudioRequired(item);\n  if (!hasPath(item?.audio)) pushWarning(issues, itemId, missingField(name, 'histoire', { feminine: true }));\n  else if (isBrokenPath(item?.audio, fileAudit)) pushWarning(issues, itemId, brokenField(name, 'histoire'));\n  if (!hasPath(item?.itemImage)) pushWarning(issues, itemId, missingField(name, 'image', { feminine: true }));\n  else if (isBrokenPath(item?.itemImage, fileAudit)) pushWarning(issues, itemId, brokenField(name, 'image'));\n  if (!hasPath(item?.itemAudio) && selectionAudioRequired) pushWarning(issues, itemId, missingField(name, 'audio titre'));\n  else if (isBrokenPath(item?.itemAudio, fileAudit)) pushWarning(issues, itemId, brokenField(name, 'audio titre'));\n  // Médias de fin : seuls ceux que le moteur écrit sont vérifiés (miroir des\n  // règles d'activité Rust). Une étape ou une réaction sans média reste valide :\n  // le moteur et les lecteurs acceptent un écran muet.\n  if (isEndPromptActive(item, project) && isBrokenPath(item?.afterPlaybackPromptAudio, fileAudit)) {\n    pushWarning(issues, itemId, brokenField(name, \"audio de fin d'histoire\"));\n  }\n  if (isEndSequenceActive(item, project)) {\n    for (const [index, step] of item.afterPlaybackSequence.entries()) {\n      if (isBrokenPath(step?.audio, fileAudit)) pushWarning(issues, itemId, brokenField(name, { code: 'VALIDATION_FIELD_ENDING_AUDIO_NUMBERED', params: { index: index + 1 } }));\n      if (isBrokenPath(step?.image, fileAudit)) pushWarning(issues, itemId, brokenField(name, { code: 'VALIDATION_FIELD_ENDING_IMAGE_NUMBERED', params: { index: index + 1 } }));\n    }\n  }\n  const homeStep = item?.afterPlaybackHomeStep;\n  if (homeStep && isEndHomeStepActive(item, project)) {\n    if (isBrokenPath(homeStep.audio, fileAudit)) pushWarning(issues, itemId, brokenField(name, 'audio de la réaction Accueil'));\n    if (isBrokenPath(homeStep.image, fileAudit)) pushWarning(issues, itemId, brokenField(name, 'image de la réaction Accueil'));\n  }\n}\n\nfunction validateZipItem(issues, item, fallbackName, fileAudit) {\n  const name = labelOrFallback(item?.name, fallbackName);\n  if (!hasPath(item?.zipPath)) pushWarning(issues, item?.id ?? null, missingField(name, 'zip'));\n  else if (isBrokenPath(item?.zipPath, fileAudit)) pushWarning(issues, item?.id ?? null, brokenField(name, 'zip'));\n}\n\nexport function getProjectValidationIssues(project, fileAudit = {}, providedProjectIndex = null) {\n  const issues = [];\n  const projectType = project?.projectType;\n  const rootName = labelOrFallback(project?.projectName || project?.packMetadata?.title, validationLabel('LABEL_PROJECT_UNNAMED_PACK'));\n  const autoNext = !!project?.globalOptions?.autoNext;\n  const nightMode = !!project?.globalOptions?.nightMode;\n  // Le message de fin global n'est vérifié que si une histoire l'emprunte : remplacé\n  // partout par des fins locales, le moteur ne l'écrit pas.\n  const hasEndNode = !autoNext\n    && (nightMode || !!project?.nightModeAudio || !!project?.globalOptions?.endNode)\n    && projectReachesEndNode(project);\n  const projectIndex = providedProjectIndex ?? buildProjectIndex(project);\n  const { entryIdCounts, menuMap, firstSimpleStory, rootPlayableCount } = collectProjectGraphStats(projectIndex);\n  const navigation = { menuIds: new Set(menuMap.keys()), project };\n\n  if (!projectType) {\n    pushWarning(issues, 'root', VALIDATION_MESSAGES.noProjectType);\n    return issues;\n  }\n\n  for (const warning of project?.importWarnings ?? []) {\n    pushWarning(\n      issues,\n      warning?.entryId ?? 'root',\n      warning?.message ? presentImportWarning(warning) : VALIDATION_MESSAGES.importedTransitionUnmodeled,\n    );\n  }\n\n  for (const [entryId, count] of entryIdCounts.entries()) {\n    if (count > 1) {\n      pushError(issues, entryId, VALIDATION_MESSAGES.duplicateId(count, entryId));\n    }\n  }\n  if (entryIdCounts.has('root')) {\n    pushError(issues, 'root', VALIDATION_MESSAGES.rootReservedId);\n  }\n\n  if (!hasPath(project?.rootAudio)) pushWarning(issues, 'root', missingField(validationLabel('LABEL_PROJECT_ROOT_MENU'), 'audio intro'));\n  else if (isBrokenPath(project?.rootAudio, fileAudit)) pushWarning(issues, 'root', brokenField(validationLabel('LABEL_PROJECT_ROOT_MENU'), 'audio intro'));\n  if (!hasPath(project?.rootImage)) pushWarning(issues, 'root', missingField(validationLabel('LABEL_PROJECT_ROOT_MENU'), 'image de couverture', { feminine: true }));\n  else if (isBrokenPath(project?.rootImage, fileAudit)) pushWarning(issues, 'root', brokenField(validationLabel('LABEL_PROJECT_ROOT_MENU'), 'image de couverture'));\n  // Sans vignette propre, le catalogue reprend l'image racine : il ne manque\n  // donc jamais de vignette. Une vignette propre se vérifie comme un média.\n  if (!project?.sameImage && hasPath(project?.thumbnailImage) && isBrokenPath(project?.thumbnailImage, fileAudit)) {\n    pushWarning(issues, 'root', brokenField(validationLabel('LABEL_PROJECT_PACK_CARD'), 'vignette catalogue'));\n  }\n  if (hasEndNode && !hasPath(project?.nightModeAudio)) {\n    pushWarning(issues, 'end-node', missingField(validationLabel('LABEL_PROJECT_END_MESSAGE'), 'audio'));\n  } else if (hasEndNode && isBrokenPath(project?.nightModeAudio, fileAudit)) {\n    pushWarning(issues, 'end-node', brokenField(validationLabel('LABEL_PROJECT_END_MESSAGE'), 'audio'));\n  }\n\n  if (projectType === 'simple') {\n    if (!hasPath(firstSimpleStory?.audio)) {\n      pushWarning(issues, 'root', missingField(rootName, 'histoire', { feminine: true }));\n    } else if (isBrokenPath(firstSimpleStory?.audio, fileAudit)) {\n      pushWarning(issues, 'root', brokenField(rootName, 'histoire'));\n    }\n    return issues;\n  }\n\n  // Une destination du message de fin qui ne mène plus nulle part (histoire ou\n  // dossier supprimé) reste visible et à corriger : le moteur la remplacerait\n  // sans le dire par le retour propre à chaque histoire.\n  if (hasEndNode) {\n    validateNavigationTarget(issues, 'end-node', validationLabel('LABEL_PROJECT_END_AFTER'), project?.nightModeReturn, projectIndex, navigation);\n    validateNavigationTarget(issues, 'end-node', validationLabel('LABEL_PROJECT_END_HOME'), project?.nightModeHomeReturn, projectIndex, navigation);\n  }\n\n  visitProjectEntries(project, (entry, ancestors) => {\n    const entryLabel = labelOrFallback(entry?.name, entry?.type === 'menu' ? validationLabel('LABEL_PROJECT_COLLECTION') : validationLabel('LABEL_PROJECT_ELEMENT'));\n    const pathLabel = { messages: [...ancestors.map((parent) => labelOrFallback(parent?.name, validationLabel('LABEL_PROJECT_COLLECTION'))), entryLabel], separator: ' / ', data: true };\n    const entryId = typeof entry?.id === 'string' ? entry.id.trim() : '';\n    if (!entryId) {\n      pushError(issues, null, VALIDATION_MESSAGES.missingInternalId(pathLabel));\n    } else if (entryId === 'root') {\n      pushError(issues, entryId, VALIDATION_MESSAGES.reservedIdInvalid(pathLabel));\n    }\n    if (entry?.type === 'ref') {\n      // Une reference est un pointeur pur : sa seule contrainte est de resoudre\n      // vers une cible existante. On reutilise le resolveur de navigation.\n      if (!hasPath(entry?.target)) {\n        pushError(issues, entry?.id ?? null, VALIDATION_MESSAGES.refTargetMissing(pathLabel));\n      } else {\n        validateNavigationTarget(\n          issues,\n          entry?.id ?? null,\n          validationLabel('LABEL_UI_REFERENCE_TARGET', { label: entryLabel }),\n          entry?.target,\n          projectIndex,\n          navigation,\n        );\n      }\n      return;\n    }\n\n    if (entry?.type !== 'menu' && entry?.type !== 'story' && entry?.type !== 'zip') {\n      pushError(issues, entry?.id ?? null, VALIDATION_MESSAGES.unsupportedEntryType(pathLabel));\n      return;\n    }\n\n    if (entry?.type === 'menu') {\n      const menuId = entry?.id ?? null;\n      const isSilentImportedContinuation = !!entry?.importedContinuation;\n      if (!hasPath(entry?.audio) && !isSilentImportedContinuation) pushWarning(issues, menuId, missingField(pathLabel, 'audio'));\n      else if (isBrokenPath(entry?.audio, fileAudit)) pushWarning(issues, menuId, brokenField(pathLabel, 'audio'));\n      if (entry?.autoBlackImage) {\n        // Écran transparent : le moteur n'écrit pas l'image éventuellement conservée.\n      } else if (!hasPath(entry?.image)) {\n        pushWarning(issues, menuId, missingField(pathLabel, 'image', { feminine: true }));\n      } else if (isBrokenPath(entry?.image, fileAudit)) {\n        pushWarning(issues, menuId, brokenField(pathLabel, 'image'));\n      }\n      if (getPlayableDescendantCount(projectIndex, entry.id) === 0) {\n        pushWarning(issues, menuId, VALIDATION_MESSAGES.emptyMenu(pathLabel));\n      }\n      if (!autoNext && hasPath(entry?.returnAfterPlay)) {\n        validateNavigationTarget(\n          issues,\n          menuId,\n          validationLabel('LABEL_UI_STORIES_TARGET', { label: entryLabel }),\n          entry?.returnAfterPlay,\n          projectIndex,\n          navigation,\n        );\n      }\n      validateNavigationTarget(\n        issues,\n        menuId,\n        validationLabel('LABEL_UI_FOLDER_HOME', { label: entryLabel }),\n        entry?.returnOnHome,\n        projectIndex,\n        navigation,\n      );\n      return;\n    }\n\n    if (!autoNext && hasPath(entry?.returnAfterPlay)) {\n      validateNavigationTarget(\n        issues,\n        entry?.id ?? null,\n        validationLabel('LABEL_UI_ENDING_TARGET', { label: entryLabel }),\n        entry?.returnAfterPlay,\n        projectIndex,\n        navigation,\n      );\n    }\n\n    if (hasPath(entry?.returnOnHome)) {\n      validateNavigationTarget(\n        issues,\n        entry?.id ?? null,\n        validationLabel('LABEL_UI_HOME_BUTTON', { label: entryLabel }),\n        entry?.returnOnHome,\n        projectIndex,\n        navigation,\n      );\n    }\n\n    if (!entry?.titleReturnOnHomeNone) {\n      validateNavigationTarget(\n        issues,\n        entry?.id ?? null,\n        validationLabel('LABEL_UI_TITLE_HOME', { label: entryLabel }),\n        entry?.titleReturnOnHome,\n        projectIndex,\n        navigation,\n      );\n    }\n\n    if (entry?.type === 'zip') validateZipItem(issues, entry, pathLabel, fileAudit);\n    else {\n      validateStorySelectionItem(issues, entry, pathLabel, fileAudit, project);\n      // Les réglages que le générateur écrira réellement (lecture automatique\n      // forcée comprise) : sans OK, lecture automatique ni Accueil, l'enfant\n      // reste bloqué à la fin de l'histoire. Une étape de fin active donne une\n      // destination OK à l'écran de lecture, et le générateur y rallume OK.\n      const parentMenu = ancestors.at(-1)?.type === 'menu' ? ancestors.at(-1) : null;\n      const playControls = getGeneratedStoryPlayControls(entry, parentMenu, project);\n      const hasEndStep = isEndSequenceActive(entry, project)\n        || (isEndPromptActive(entry, project) && hasPath(entry?.afterPlaybackPromptAudio));\n      if (!hasEndStep && !playControls.ok && !playControls.autoplay && !playControls.home) {\n        pushError(issues, entry?.id ?? null, VALIDATION_MESSAGES.storyWithoutExit(pathLabel));\n      }\n      if (isEndPromptActive(entry, project) && hasPath(entry?.afterPlaybackPromptAudio)) {\n        validateNavigationTarget(\n          issues,\n          entry?.id ?? null,\n          validationLabel('LABEL_UI_PROMPT_OK', { label: entryLabel }),\n          entry?.afterPlaybackPromptOkTarget,\n          projectIndex,\n          navigation,\n        );\n        if (!entry?.afterPlaybackPromptHomeNone) {\n          validateNavigationTarget(\n            issues,\n            entry?.id ?? null,\n            validationLabel('LABEL_UI_PROMPT_HOME', { label: entryLabel }),\n            entry?.afterPlaybackPromptHomeTarget,\n            projectIndex,\n            navigation,\n          );\n        }\n      }\n      if (isEndSequenceActive(entry, project)) {\n        for (const [index, step] of entry.afterPlaybackSequence.entries()) {\n          validateNavigationTarget(\n            issues,\n            entry?.id ?? null,\n            validationLabel('LABEL_UI_ENDING_OK', { label: entryLabel, index: index + 1 }),\n            step?.okTarget,\n            projectIndex,\n            navigation,\n          );\n          for (const target of step?.okChoiceTargets ?? []) {\n            validateNavigationTarget(\n              issues,\n              entry?.id ?? null,\n              validationLabel('LABEL_UI_ENDING_OK', { label: entryLabel, index: index + 1 }),\n              target,\n              projectIndex,\n              navigation,\n            );\n          }\n          if (!step?.homeFollowsOk && !step?.homeNone) {\n            validateNavigationTarget(\n              issues,\n              entry?.id ?? null,\n              validationLabel('LABEL_UI_ENDING_HOME', { label: entryLabel, index: index + 1 }),\n              step?.homeTarget,\n              projectIndex,\n              navigation,\n            );\n          }\n        }\n      }\n      // Réaction au bouton Accueil : mêmes règles d'activité que ses médias\n      // (miroir de `validation.rs`, « retour Home de fin »).\n      const homeStep = entry?.afterPlaybackHomeStep;\n      if (homeStep && isEndHomeStepActive(entry, project)) {\n        for (const target of [homeStep.okTarget, ...(homeStep.okChoiceTargets ?? [])]) {\n          validateNavigationTarget(\n            issues,\n            entry?.id ?? null,\n            validationLabel('LABEL_UI_REACTION_OK', { label: entryLabel }),\n            target,\n            projectIndex,\n            navigation,\n          );\n        }\n        if (!homeStep.homeFollowsOk && !homeStep.homeNone) {\n          validateNavigationTarget(\n            issues,\n            entry?.id ?? null,\n            validationLabel('LABEL_UI_REACTION_HOME', { label: entryLabel }),\n            homeStep.homeTarget,\n            projectIndex,\n            navigation,\n          );\n        }\n      }\n    }\n  }, projectIndex);\n\n  if (rootPlayableCount === 0) {\n    pushWarning(issues, 'root', VALIDATION_MESSAGES.emptyPack);\n  }\n  return issues;\n}\n\nexport function getGenerateErrors(project, fileAudit = {}) {\n  return getProjectValidationIssues(project, fileAudit)\n    .filter((issue) => issue.status === 'error' || issue.status === 'warning')\n    .map((issue) => issue.text);\n}\n",
 "src/store/validationMessages.js": "import { presentUserMessage } from '../i18n/userMessage.js';\n\nconst message = (code, params = {}) => presentUserMessage({ code, params }).message;\n\nconst FIELD_LABELS = Object.freeze({\n  \"audio\": 'VALIDATION_PROJECT_FIELD_AUDIO',\n  \"audio intro\": 'VALIDATION_PROJECT_FIELD_INTRO_AUDIO',\n  \"audio titre\": 'VALIDATION_PROJECT_FIELD_TITLE_AUDIO',\n  \"histoire\": 'VALIDATION_PROJECT_FIELD_STORY',\n  \"image\": 'VALIDATION_PROJECT_FIELD_IMAGE',\n  \"image de couverture\": 'VALIDATION_PROJECT_FIELD_COVER_IMAGE',\n  \"image biblioth\\u00e8que\": 'VALIDATION_PROJECT_FIELD_LIBRARY_IMAGE',\n  \"zip\": 'VALIDATION_PROJECT_FIELD_ZIP',\n  \"audio de fin d'histoire\": 'VALIDATION_PROJECT_FIELD_ENDING_AUDIO',\n  \"audio de la r\\u00e9action Accueil\": 'VALIDATION_PROJECT_FIELD_HOME_AUDIO',\n  \"image de la r\\u00e9action Accueil\": 'VALIDATION_PROJECT_FIELD_HOME_IMAGE',\n  \"vignette catalogue\": 'VALIDATION_PROJECT_FIELD_CATALOG_IMAGE',\n  \"dossier\": 'VALIDATION_PROJECT_FIELD_FOLDER',\n  \"\": 'VALIDATION_PROJECT_FIELD_ELEMENT',\n});\n\nexport const validationLabel = (code, params = {}) => ({ code, params });\nfunction fieldLabel(field) {\n  if (field && typeof field === 'object' && field.code) return field;\n  const code = FIELD_LABELS[field || ''];\n  return code ? validationLabel(code) : String(field);\n}\nfunction lowerField(field) {\n  const value = fieldLabel(field);\n  return value && typeof value === 'object' ? { ...value, case: 'lower' } : value.toLowerCase();\n}\n\nexport function missingField(label, field, { feminine = false } = {}) {\n  void feminine;\n  return message('VALIDATION_PROJECT_UI_MISSING_FIELD', { label, field: fieldLabel(field) });\n}\nexport function brokenField(label, field) {\n  return message('VALIDATION_PROJECT_UI_BROKEN_FIELD', { label, field: lowerField(field) });\n}\nexport function missingTarget(label, what) {\n  return message('VALIDATION_PROJECT_UI_MISSING_TARGET', { label, what: lowerField(what) });\n}\nexport function emptyTarget(label, what) {\n  return message('VALIDATION_PROJECT_UI_EMPTY_TARGET', { label, what: lowerField(what) });\n}\nexport const VALIDATION_MESSAGES = Object.freeze({\n  get noProjectType() { return message('VALIDATION_PROJECT_UI_NO_TYPE'); },\n  get importedTransitionUnmodeled() { return message('VALIDATION_UI_IMPORTED_TRANSITION'); },\n  get rootReservedId() { return message('VALIDATION_PROJECT_UI_ROOT_RESERVED'); },\n  missingInternalId: (label) => message('VALIDATION_PROJECT_UI_MISSING_ID', { label }),\n  unsupportedEntryType: (label) => message('VALIDATION_PROJECT_UI_UNSUPPORTED_TYPE', { label }),\n  refTargetMissing: (label) => message('VALIDATION_PROJECT_UI_REF_TARGET', { label }),\n  reservedIdInvalid: (label) => message('VALIDATION_PROJECT_UI_RESERVED_ID', { label }),\n  duplicateId: (count, entryId) => message('VALIDATION_PROJECT_UI_DUPLICATE_ID', { count, entryId }),\n  storyReturnLost: (label) => message('VALIDATION_PROJECT_UI_LOST_RETURN', { label }),\n  storyWithoutExit: (label) => message('VALIDATION_PROJECT_UI_STORY_EXIT', { label }),\n  emptyMenu: (label) => message('VALIDATION_PROJECT_UI_EMPTY_MENU', { label }),\n  get emptyPack() { return message('VALIDATION_PROJECT_UI_EMPTY_PACK'); },\n});\n",
 "src/utils/packConvention.js": "// Convention supportee :\n// - prefixe age : N+]\n// - titre : espaces encodes en underscores\n// - bonus optionnel : _(bonus)\n// - auteur optionnel : [by_auteur\n// - version optionnelle : _Vn dans le bloc auteur ou apres le titre\n// - producteur optionnel : Producteur-Titre quand producteur et auteur sont differents\n\nfunction toUnderscored(value) {\n  return String(value || '').trim().replace(/\\s+/g, '_');\n}\n\nfunction toIntVersion(value) {\n  const number = Number.parseInt(String(value ?? '').replace(/\\D/g, ''), 10);\n  return Number.isFinite(number) && number > 0 ? number : 1;\n}\n\nfunction looksLikeProducerCandidate(value) {\n  const parts = String(value || '').split('_').filter(Boolean);\n  if (parts.length < 1 || parts.length > 2) return false;\n  return parts.every((part) => /^[A-Za-zÀ-ž][A-Za-zÀ-ž0-9]*$/.test(part));\n}\n\nexport function parseConventionName(raw) {\n  if (!raw) return null;\n  const value = String(raw).trim().replace(/\\.(zip|7z)$/i, '');\n  const ageMatch = value.match(/^(\\d+)\\+\\]/);\n  if (!ageMatch) return null;\n  const minAge = ageMatch[1];\n  let rest = value.slice(ageMatch[0].length);\n\n  let author = '';\n  let version = 1;\n  const byIdx = rest.indexOf('[by_');\n  if (byIdx !== -1) {\n    const byPart = rest.slice(byIdx + 4);\n    const vMatch = byPart.match(/[_-][Vv](\\d+)$/);\n    if (vMatch) {\n      version = toIntVersion(vMatch[1]);\n      author = byPart.slice(0, byPart.length - vMatch[0].length).replace(/_/g, ' ').trim();\n    } else {\n      author = byPart.replace(/_/g, ' ').trim();\n    }\n    rest = rest.slice(0, byIdx);\n  } else {\n    const standaloneV = rest.match(/_[Vv](\\d+)$/);\n    if (standaloneV) {\n      version = toIntVersion(standaloneV[1]);\n      rest = rest.slice(0, rest.length - standaloneV[0].length);\n    }\n  }\n\n  let producer = '';\n  let core = rest;\n  const prodSep = rest.indexOf('_-_');\n  if (prodSep !== -1) {\n    producer = rest.slice(0, prodSep).replace(/_/g, ' ').trim();\n    core = rest.slice(prodSep + 3);\n  } else {\n    const firstDash = rest.indexOf('-');\n    if (firstDash > 0) {\n      const candidate = rest.slice(0, firstDash);\n      if (looksLikeProducerCandidate(candidate)) {\n        producer = candidate.replace(/_/g, ' ').trim();\n        core = rest.slice(firstDash + 1);\n      }\n    }\n  }\n\n  let bonus = '';\n  let title = core;\n  const bonusParen = core.match(/_\\((.+)\\)$/);\n  if (bonusParen) {\n    bonus = bonusParen[1].replace(/_/g, ' ').trim();\n    title = core.slice(0, core.length - bonusParen[0].length);\n  } else {\n    const lastDash = core.lastIndexOf('-');\n    if (lastDash !== -1) {\n      const potBonus = core.slice(lastDash + 1).replace(/_/g, ' ').trim();\n      if (potBonus && /^\\d/.test(potBonus)) {\n        bonus = potBonus;\n        title = core.slice(0, lastDash);\n      }\n    }\n  }\n\n  return {\n    title: title.replace(/_/g, ' ').trim(),\n    author,\n    version,\n    minAge,\n    producer,\n    bonus,\n    description: '',\n    namingMode: 'convention',\n    legacyExportName: '',\n    legacyName: '',\n  };\n}\n\n/**\n * Sépare un préfixe d'âge « N+ » en tête d'un titre (« 3+ Example »,\n * « 6+]Titre »). Sans séparateur — « 3+5 », « 3+Titre » —, ce n'est pas un\n * préfixe d'âge. Rend `null` quand le titre n'en porte pas.\n */\nexport function splitLeadingAge(name) {\n  const match = String(name || '').match(/^\\s*(\\d{1,2})\\s*\\+(?:\\]|\\s)\\s*(\\S.*)$/);\n  return match && match[2].trim() ? { minAge: match[1], title: match[2].trim() } : null;\n}\n\nexport function generateConventionName(metadata = {}) {\n  // Un titre qui porte déjà la convention complète (« 3+]Titre[by_Auteur_V5 »,\n  // repris tel quel d'un pack produit) n'est composé qu'une fois : on repart de\n  // ses champs, sans empiler l'âge, l'auteur ni la version. Les champs saisis\n  // l'emportent ; la version est toujours celle demandée.\n  const parsed = parseConventionName(metadata.title);\n  if (parsed) {\n    return generateConventionName({\n      ...metadata,\n      title: parsed.title,\n      minAge: metadata.minAge || metadata.age || parsed.minAge,\n      author: metadata.author || parsed.author,\n      producer: metadata.producer || parsed.producer,\n      bonus: metadata.bonus || parsed.bonus,\n    });\n  }\n  // Le préfixe `N+]` porte déjà l'âge : un titre qui le répète (« 3+ Example »,\n  // tel qu'un pack FS le reçoit de son nom de fichier) ne le double pas.\n  const leading = splitLeadingAge(metadata.title);\n  const title = toUnderscored(leading?.title ?? metadata.title);\n  if (!title) return '';\n\n  const bonus = toUnderscored(metadata.bonus);\n  const author = toUnderscored(metadata.author);\n  const producer = toUnderscored(metadata.producer);\n  const rawProducer = String(metadata.producer || '').trim();\n  const rawAuthor = String(metadata.author || '').trim();\n  // Sans âge saisi, celui que le titre porte en tête (« 5+ Le prince… ») :\n  // retomber sur 3 renommait « 3+] » un pack importé de 5 ans.\n  const minAge = String(metadata.minAge || metadata.age || leading?.minAge || '3').replace(/\\D/g, '') || '3';\n  const version = toIntVersion(metadata.version);\n  const bonusPart = bonus ? `_(${bonus})` : '';\n  const prefix = `${minAge}+]`;\n  const titlePart = producer && (!author || rawProducer !== rawAuthor)\n    ? `${producer}-${title}${bonusPart}`\n    : `${title}${bonusPart}`;\n  const versionSuffix = version > 1 ? `_V${version}` : '';\n\n  if (!author) return `${prefix}${titlePart}${versionSuffix}`;\n  return `${prefix}${titlePart}[by_${author}${versionSuffix}`;\n}\n\n/**\n * Version suivante suggérée pour un pack : incrémente\n * la version courante d'une unité. Sans version (ou version invalide), suggère 2\n * → suffixe `_V2`. L'utilisateur reste libre de la changer.\n */\nexport function bumpPackVersion(version) {\n  return toIntVersion(version) + 1;\n}\n\nexport function getExportPackName(metadata = {}) {\n  const legacy = String(metadata.legacyExportName || '').trim();\n  if (metadata.namingMode === 'legacy') return legacy || String(metadata.title || '').trim() || 'Story Studio';\n  return generateConventionName(metadata) || legacy || String(metadata.title || '').trim() || 'Story Studio';\n}\n"
};
